// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 행운
// ==========================================
//
// 노름꾼 · 행상 · 점술가 · 수집가 · 거지
// 에일리언 · 공룡 — 머리 좋은 것들이 어둠 속에서 사람을 사냥한다.
// 행운의 몫은 여기서도 같다. 더 좋은 것을 줍는다.
// 다만 여기서는, 줍는 사람도 누군가의 몫이다.

// ==========================================
// 🎲 노름꾼 (gambler) · 자원 없음
// ==========================================
kJob('gambler', 'S', [

{ at:'S', t:'갈림길 — 드나든 셈',
  x:`길이 둘로 갈린다. 바닥이 물러서 발자국이 잘 남는다.<br><br>
    왼쪽 길. 들어간 발자국 열둘, 나온 발자국 셋. 오른쪽 길. 들어간 것은 없고 나온 것만 줄줄이다.<br>
    일행이 오른쪽을 가리킨다. 아무것도 안 들어간 길이라고.<br><br>
    노름꾼은 쭈그리고 앉아 수를 다시 센다. 나오기만 하는 문이 어떤 문인지, 판에서 배웠다. 물주가 드나드는 문이다.`,
  o:[
    { l:'① 드나든 수를 끝까지 센다.', k:'luck', dc:25, wake:1,
      ok:`발자국 가장자리를 짚었다. 왼쪽 길 핏자국은 아직 번들거린다. 방금 먹은 자리다.<br><br>방금 먹은 것은 당분간 안 먹는다. 제일 험해 보이는 왼쪽이 지금은 제일 싼 길이다. 일행을 끌고 왼쪽으로 들어갔다. 뜯다 만 것 옆을 지났다. 아무것도 따라오지 않았다.<br><br>길에도 값이 있고, 값은 시세가 있다. 발자국 수로 시세를 읽는 눈이 생겼다.`,
      ng:`세는 사이 수가 틀어졌다. 다시 셌다. 또 틀어졌다.<br><br>발자국이 하나 늘어 있었다. 이쪽 발 뒤에. 젖은 자국에서 김이 올라온다.<br>돌아보지 않고 걸었다. 등 뒤에서 수를 세는 건 이제 이쪽이 아니다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 발자국 없는 쪽을 고른다.', k:'sense', dc:24,
      ok:`둘 다 버렸다. 갈림길 모서리, 발자국이 한 톨도 없는 좁은 틈을 찾았다.<br><br>아무도 안 다닌 길은 느리다. 대신 아무도 안 기다린다. 어깨를 긁히며 빠져나갔다.<br>틈 끝에서 두 길이 다시 만나는 게 보였다. 만나는 자리에 무엇이 엎드려 둘 다 보고 있었다.`,
      ng:`발자국 없는 틈으로 들어갔다. 왜 없는지는 안에서 알았다.<br><br>천장이 낮다. 그리고 천장에 긁힌 자국이 줄줄이다. 여기 것들은 바닥으로 안 다닌다.<br>위에서 무엇이 몸을 뒤집는 소리가 났다. 기어서 뛰었다. 등짝이 다 긁혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'어둠 — 세 번 울고 한 번 쉰다',
  x:`어둠 저쪽에서 소리가 난다. 딱. 딱. 딱. 그리고 쉼.<br><br>
    또 딱. 딱. 딱. 쉼. 박자가 정확하다. 소리를 내고, 돌아오는 소리를 듣는 것이다. 귀로 어둠을 더듬는 사냥이다.<br>
    일행은 쉼에 움직이려 한다. 조용할 때 가자고.<br><br>
    노름꾼은 고개를 젓는다. 패 돌리는 소리가 멎었을 때가 판이 제일 무서운 때다. 쉼은 그것이 듣는 시간이다.`,
  o:[
    { l:'① 딱 소리에 맞춰 같이 걷는다.', k:'luck', dc:25,
      doom:{ title:'네 번째 딱', what:'어둠 속의 것에게 물려 끌려갑니다', dc:19, sec:45,
        text:`딱 소리에 한 걸음. 딱 소리에 한 걸음. 제 소리에 제 귀가 먹는 틈만 골라 디뎠다.<br><br>반쯤 건넜을 때 박자가 바뀌었다. 딱. 딱. 그리고 바로 코앞에서, 딱.<br>패를 바꿔 치는 놈은 어디에나 있다. 턱이 장딴지를 물었다. 끌고 간다. 어둠 안쪽으로, 박자도 없이.<br><br>박자를 읽힌 쪽이 먼저 바꾼다. 판의 기본인데, 상대도 노름꾼이었다.`,
        dieText:`어둠 속에서 소리가 난다. 딱. 딱. 딱. 딱. 그리고 쉼.<br><br>네 번 울고 한 번 쉰다. 하나 늘었다.<br>새 소리는 조금 무디다. 아직 이가 덜 여물었다.` },
      ok:`딱 소리에 한 걸음. 쉼에는 돌이 됐다. 숨도 반으로 접었다.<br><br>소리 내는 것은 제 소리에 저도 귀가 먹는다. 그 틈만 디뎠다. 끝까지.<br>다 건너고 돌아보니 박자는 그대로였다. 딱. 딱. 딱. 쉼. 끝까지 몰랐다는 소리다. 판돈을 다 들고 나온 판이 오랜만이었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 돌을 던져 딴 박자를 섞는다.', k:'fix', dc:24,
      ok:`쉼에 맞춰 돌을 멀리 던졌다. 탁. 저쪽 벽.<br><br>딱 소리가 그쪽으로 몰려간다. 박자가 빨라진다. 제가 센 수와 돌아온 수가 안 맞아서 그것이 화를 낸다.<br>셈이 엉킨 쪽은 판을 못 읽는다. 그 사이에 다 건넜다.`,
      ng:`돌을 던졌다. 소리가 그쪽으로 가지 않는다.<br><br>딱 소리가 뚝 그쳤다. 돌 소리와 발소리를 가릴 줄 아는 귀다. 어둠이 통째로 이쪽을 듣는다.<br>등불을 끄고 벽에 붙어 반 시진을 굳어 있었다. 손가락이 펴지지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'쉬는 자리 — 제비 뽑기',
  x:`불침번 차례를 정했다. 노름꾼이 제비를 만들었다. 마른 줄기 다섯. 하나만 짧다.<br><br>
    짧은 제비가 다친 일행에게 갔다. 다시 섞었다. 또 그 사람이다. 세 번째도.<br>
    다섯에 하나가 세 번 연달아 올 수는 있다. 백스물다섯에 하나. 있을 수 있는 일과 벌어진 일은 다르다.<br><br>
    판이 짜였다. 누가 짰는지는 모른다. 다친 사람을 혼자 어둠 앞에 세우고 싶은 무엇이 짰다.`,
  o:[
    { l:'① 제비를 접고 둘씩 세운다.', k:'fix', dc:24,
      ok:`제비를 다 꺾어 버렸다. 오늘은 뽑기 없이 둘씩 선다. 다친 사람은 가운데 자리, 불 옆이다.<br><br>밤중에 등불 가장자리로 무엇이 왔다. 혼자 앉았을 자리를 오래 보다가 갔다.<br>짜 놓은 판에 손님이 안 앉으면 판은 저절로 깨진다.`,
      ng:`둘씩 세웠는데 새벽에 한 명이 졸았다. 남은 한 명이 그걸 깨우러 간 사이 울타리 쪽이 비었다.<br><br>빈 쪽 어둠에서 흙 밟는 소리가 세 걸음 들어왔다가 나갔다. 재 보고 간 것이다.<br>아침까지 아무도 다시 잠들지 못했다.`,
      win:{ exp:17, dream:2, mind:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 짧은 제비를 제 손에 숨긴다.', k:'luck', dc:25, wake:1,
      ok:`네 번째 판. 섞으면서 짧은 것을 손바닥에 접어 숨겼다. 평생 그 반대로 쓰던 손기술이다.<br><br>다친 사람이 긴 제비를 뽑고 웃었다. 이쪽이 짧은 제비를 폈다. 혼자 불가에 앉아 밤을 받았다.<br>어둠 속에서 그것이 왔다. 다친 냄새를 좇아왔는데 멀쩡한 눈이 마주 본다. 셈이 틀린 것은 돌아간다.<br><br>속임수는 평생 따는 쪽으로만 썼다. 처음으로 무는 쪽으로 썼다. 손은 같은 손인데 패가 달랐다.`,
      ng:`숨기다 들켰다. 사람한테가 아니다.<br><br>손바닥을 접는 순간 어둠 쪽에서 숨소리가 한 박자 흔들렸다. 보고 있었다. 수를 바꾼 걸 저쪽도 안다.<br>그날 밤 그것은 오지 않았다. 다음 수를 다시 짜는 중이다. 그게 더 길게 무서웠다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-15, spirit:-24 } },
    { l:'③ 제비를 등불에 비춰 본다.', k:'gaze', dc:24,
      ok:`짧은 제비를 불에 비췄다. 끝이 축축하다. 냄새를 맡았다. 피 냄새. 다친 사람 붕대 냄새다.<br><br>제비가 짠 게 아니다. 젖은 줄기가 피 묻은 손에 붙은 것뿐이다. 그리고 그 말은, 여기 것들 코에는 그 사람이 제일 밝게 보인다는 말이다.<br>상처를 다시 싸매고 겉에 재를 발랐다. 그날 밤은 조용했다.`,
      ng:`불에 비추는데 제비 끝이 꿈틀했다. 줄기가 아니다. 무엇의 더듬이 마디다.<br><br>언제 섞여 들었는지 모른다. 다섯 다 불에 던졌다. 타면서 쇳내가 났다.<br>뽑기로 정한 모든 게 의심스러워졌다. 그날 차례는 아무도 안 믿었다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'허물 — 판돈 오르는 꼴',
  x:`벽을 따라 허물이 줄지어 있다. 벗어 둔 겉가죽. 하나, 둘, 셋, 넷.<br><br>
    갈수록 크다. 눈대중으로 두 배씩. 노름꾼은 판돈 오르는 꼴을 안다. 두 배, 두 배, 두 배 다음 판이 어떤 판인지도 안다.<br>
    넷째 허물은 사람 둘을 덮고도 남는다.<br><br>
    다섯째는 없다. 아직 입고 있다는 뜻이다.`,
  o:[
    { l:'① 허물 사이 거리를 잰다.', k:'luck', dc:24,
      ok:`허물과 허물 사이를 걸음으로 쟀다. 열둘, 아홉, 다섯.<br><br>사이가 준다. 갈수록 자주 벗는다. 빨리 크고 있고, 멀리 안 갔다는 셈이다. 넷째 허물 안쪽을 짚으니 축축했다.<br>오늘 벗은 것이다. 갓 벗은 것은 가죽이 무르다. 무를 때는 깊이 숨는다. 지금이 이 길의 제일 싼 시간이다. 일행을 재촉해 지나갔다.`,
      ng:`걸음으로 재는데 넷째 허물이 부풀었다 꺼졌다.<br><br>빈 가죽이 아니다. 안에서 무엇이 숨을 쉰다. 벗다 만 것인지, 벗은 것을 덮고 자는 것인지.<br>뒷걸음으로 물러났다. 허물 입이 천천히 이쪽을 향해 돌았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 허물 안쪽을 들춰 본다.', k:'sense', dc:24,
      ok:`넷째 허물 안쪽을 들췄다. 가죽 안벽에 흉터가 그대로 떠 있다.<br><br>왼쪽 뒷다리 자리에 깊게 패인 골. 오래된 상처다. 그 다리를 전다는 뜻이다.<br>절름발이는 도는 쪽이 정해져 있다. 만나면 오른쪽으로 빠지면 된다. 산 패 한 장을 공으로 얻었다.`,
      ng:`들추는데 가죽이 와삭 소리를 냈다. 마른 데가 찢어진 것이다.<br><br>복도 저쪽 어둠에서 똑같은 와삭 소리가 돌아왔다. 대답이다.<br>허물을 놓고 걸음을 늘렸다. 뒤에서 가죽 끄는 소리가 한참 따라오다 그쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-19 } }
  ] },

{ at:'S', t:'사냥 길 — 열어 둔 길',
  x:`길이 이상하게 깨끗하다.<br><br>
    양옆 샛길은 죄다 무너진 더미와 가시덤불로 막혔다. 가운데만 비로 쓴 듯 훤하다. 걷기 좋게.<br>
    일행 걸음이 저절로 빨라진다. 노름꾼만 걸음을 늦춘다.<br><br>
    판에서 공짜 패를 받아 본 적이 있다. 그 판에서 바지까지 잃었다. 공짜로 열린 길이 제일 비싼 길이다.`,
  o:[
    { l:'① 열린 길을 버리고 막힌 데를 넘는다.', k:'luck', dc:25, wake:1,
      ok:`제일 엉성하게 막힌 더미를 골라 소리 죽여 넘었다. 가시에 뜯기며 한참을 돌았다.<br><br>돌아 나와 열린 길 끝이 보이는 데 섰다. 길 끝 바위 뒤에 그것이 엎드려 있었다. 턱을 땅에 붙이고, 열린 길만 보고.<br>한참 뒤 그것이 몸을 털고 일어났다. 기다림이 공친 것이다. 빈 판을 접는 물주 등짝을 구경하는 기분은 어디서나 좋다.<br><br>거저 열린 길 앞에서 다리가 먼저 멈추게 됐다. 길값부터 세는 버릇이 발에 붙었다.`,
      ng:`더미를 넘다 마른 가지를 밟았다. 소리가 길게 났다.<br><br>길을 막아 둔 쪽이 막은 데를 모를 리 없다. 양쪽 어둠에서 낮게 우는 소리가 서로 주고받았다.<br>몰이가 시작되기 전에 뛰었다. 가시밭을 그대로 질렀다. 다들 피투성이가 됐지만 포위는 벗어났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 열린 길로 전속력으로 지른다.', k:'evade', dc:26,
      doom:{ title:'목 좋은 자리', what:'길목의 것에게 채여 끌려갑니다', dc:19, sec:40,
        text:`덫은 닫히기 전에 빠져나가면 덫이 아니다. 전속력으로 질렀다.<br><br>길이 한 번 꺾였다. 꺾인 자리에 그것이 있었다. 물주는 판돈 곁을 안 떠난다. 당연한 것을 뛰면서 잊었다.<br>옆구리를 채였다. 발이 땅에서 떨어졌다. 물려서 끌려간다. 열어 둔 길을 되짚어, 아주 익숙한 걸음으로.<br><br>덫이 문제가 아니었다. 덫을 놓은 놈 집이 덫 안에 있었다.`,
        dieText:`길이 다시 비로 쓴 듯 깨끗하다.<br><br>흙 위에 끌린 자국 한 줄만 길게 남았다.<br>자국 끝에 동전 한 닢이 떨어져 있다. 앞면이다.` },
      ok:`전속력으로 질렀다. 꺾이는 자리에서 몸을 낮추며 어깨부터 굴렀다.<br><br>머리 위로 턱 닫히는 소리가 지나갔다. 바람이 뺨을 쳤다.<br>구른 채로 그대로 내달렸다. 등 뒤에서 흙 긁는 소리가 세 걸음 따라오다 멎었다. 제 길목을 못 버린 것이다. 판돈에 묶인 물주는 쫓아오지 못한다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'웅덩이 — 동전 던지기',
  x:`바닥 곳곳에 검게 고인 웅덩이가 있다. 물 같다. 다 물은 아니다.<br><br>
    아까 일행 하나가 신발 끝을 담갔다 뺐다. 신발 코가 녹아 있었다. 연기도 없이.<br>
    어느 것이 물이고 어느 것이 그것인지, 빛깔로는 안 갈린다.<br><br>
    노름꾼 주머니에 동전이 한 줌 있다. 평생 던져 온 물건이다.`,
  o:[
    { l:'① 동전을 던져 소리로 가린다.', k:'luck', dc:24,
      ok:`웅덩이마다 동전을 던졌다. 퐁, 하면 물이다. 치익, 하고 거품이 끓으면 아니다.<br><br>퐁 나는 것만 골라 디뎠다. 치익 나는 것 사이로 길이 났다. 동전은 줍지 않았다. 녹는 쪽에 던진 건 이미 없고, 물에 던진 건 길값이다.<br>마지막 웅덩이는 소리가 안 났다. 동전이 그냥 사라졌다. 그것만 크게 돌아서 지났다.`,
      ng:`던졌다. 퐁. 디뎠다. 그런데 발목이 뜨겁다.<br><br>위는 물이고 밑에 그것이 가라앉아 있었다. 반반씩 고인 웅덩이다. 소리는 위쪽 것만 난다.<br>신발을 벗어 던지고 맨발로 뛰었다. 발등 가죽이 한 겹 벗겨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 작은 짐승 발자국을 따라 디딘다.', k:'sense', dc:23,
      ok:`웅덩이 사이로 작은 발자국이 요리조리 나 있다. 여기 사는 것들은 어디가 녹는지 안다.<br><br>그 자국만 밟았다. 보폭이 안 맞아 우스운 걸음이 됐지만 아무도 안 웃었다.<br>자국은 마른 바닥까지 이어졌다. 공으로 얻은 길 치고 좋은 길이었다.`,
      ng:`자국을 따라가는데 자국이 웅덩이 한가운데서 뚝 끊겼다.<br><br>건너뛴 게 아니다. 끊긴 자리 양옆에 미끄러진 흔적이 있다. 걷다가 집혀 간 것이다. 위에서.<br>고개를 들었다. 천장 어둠에서 물방울이 하나 떨어져 발 앞 바닥을 태웠다. 그 밑을 전속력으로 빠져나왔다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-15, spirit:-21 } }
  ] },

{ at:'S', t:'죽은 척 — 올인',
  x:`트인 데 한가운데서 걸렸다. 숨을 데가 없다. 그것이 들어온다. 코부터.<br><br>
    뛰면 등을 준다. 서면 눈을 준다. 패가 없다.<br>
    늙은 노름꾼들이 패 없을 때 쓰는 수가 하나 있다. 죽은 패인 척하는 것이다.<br><br>
    판돈은 목숨이고, 접을 수도 없다. 올인이다.`,
  o:[
    { l:'① 숨을 걸고 엎드린다.', k:'steady', dc:25,
      doom:{ title:'들춰 보는 콧김', what:'죽은 척하던 채로 물려 끌려갑니다', dc:19, sec:45,
        text:`엎드렸다. 숨을 바닥까지 낮췄다. 콧김이 목덜미를 훑는다. 뜨겁고 비리다.<br><br>그것이 코끝으로 옆구리를 민다. 한 번. 두 번. 굴러가 준다. 죽은 것처럼. 됐나 싶었을 때 턱이 외투째 등을 물었다.<br>먹으려는 게 아니다. 문 채로 걷는다. 나른다. 죽은 것은 저장하는 것이다.<br><br>죽은 패인 척은 통했다. 죽은 패가 어디로 가는지를 몰랐을 뿐이다.`,
        dieText:`트인 바닥에 눌린 자국 하나와 끌린 자국 한 줄이 남았다.<br><br>자국 끝은 어둠이다.<br>바닥에 동전 한 닢. 뒷면이다.` },
      ok:`엎드려 숨을 바닥까지 낮췄다. 그것이 발톱 하나를 등에 얹었다. 무게를 단다.<br><br>몸에서 힘이란 힘은 다 뺐다. 눌리는 대로 눌렸다. 산 것은 눌리면 굳는다. 죽은 것은 눌리면 퍼진다.<br>발톱이 거둬졌다. 콧김이 멀어졌다. 그래도 백을 셀 때까지 엎드려 있었다. 일어났을 때 등에 발톱 자리가 멍으로 남아 있었다. 딴 판돈이다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 되레 크게 서서 등불을 흔든다.', k:'fix', dc:24,
      ok:`죽은 척의 반대로 갔다. 외투를 활짝 펴고 등불을 머리 위로 크게 돌렸다.<br><br>그것이 멈췄다. 처음 보는 것은 셈이 안 된다. 셈 안 되는 판에 이빨부터 거는 사냥꾼은 오래 못 산다. 저쪽도 그걸 안다.<br>그것이 반 바퀴를 돌고 물러났다. 허세가 판을 접게 만들었다. 다리가 후들거린 건 그 다음이었다.`,
      ng:`등불을 흔들었다. 그것이 물러나는 대신 목을 꺾고 길게 울었다.<br><br>어둠 저쪽에서 대답이 왔다. 둘. 셋. 혼자 셈 안 되는 판에는 식구를 부르는 놈이었다.<br>포위가 닫히기 전 틈으로 내달렸다. 옆구리를 발톱 끝이 스쳤다. 외투가 반으로 갈라졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-31, spirit:-17 } }
  ] },

{ at:'S', t:'둥지 어귀 — 두고 간 판돈',
  x:`둥지 어귀에 짐이 쌓여 있다. 배낭, 물통, 끈 달린 괴나리봇짐.<br><br>
    먼저 들어온 사람들 것이다. 사람만 없다. 가죽과 마른 것에는 입을 안 대는 모양이다.<br>
    판돈만 쌓인 빈 탁자. 임자가 안에 있는지가 문제다.<br><br>
    어귀 어둠은 숨을 쉬는지 안 쉬는지도 안 보일 만큼 깊다.`,
  o:[
    { l:'① 제일 가까운 짐 하나만 끌어낸다.', k:'luck', dc:25,
      ok:`끈을 발끝으로 걸어 천천히 끌었다. 눈은 어둠에 둔 채.<br><br>배낭이 소리 없이 끌려 나왔다. 그 이상은 안 건드렸다. 판돈을 쓸어 담는 손은 꼭 한 번 더 욕심을 내다 잡힌다.<br>배낭 속에 말린 고기가 기름종이째 들어 있었다. 죽은 사람 몫이 산 사람 끼니가 됐다. 여기 셈은 그렇게 돈다.`,
      ng:`끌다가 끈이 뼈 무더기에 걸렸다. 와르르.<br><br>어귀 깊은 데서 숨 들이켜는 소리가 났다. 길고, 천천히.<br>배낭을 버리고 물러났다. 어둠 밖으로 코끝이 반 뼘 나왔다가 들어갔다. 그 반 뼘이 밤새 눈에 밟혔다.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ hp:-27, mind:-15 } },
    { l:'② 돌을 던져 넣고 반응을 본다.', k:'sense', dc:24,
      ok:`돌 하나를 어귀 안으로 굴려 넣었다. 구르는 소리가 길게 갔다. 벽에 닿고, 끝. 숨소리도 뒤척임도 없다.<br><br>빈집이다. 지금은. 짐 두 개를 메고 나왔다. 물통 하나가 묵직했다.<br>나오면서 돌 떨어진 자리를 봤다. 돌이 없었다.`,
      ng:`돌을 굴려 넣었다. 한참 조용했다.<br><br>그리고 돌이 도로 굴러 나왔다. 똑바로, 이쪽 발 앞까지.<br>받은 것은 돌려준다는 것이다. 다음에 들어오는 것도 돌려보낼지는 적혀 있지 않았다. 짐은 포기하고 바로 떴다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'어둠 — 홀로 선 눈',
  x:`등불 가장자리 어둠에 눈이 떠 있다. 불빛을 받아 희게 빛난다.<br><br>
    둘, 둘, 둘. 짝으로 세면 되는데 세다 보니 일곱이다. 홀수다.<br>
    눈은 짝으로 다닌다. 홀수라는 건 하나가 옆얼굴이라는 것이다.<br><br>
    옆얼굴은 이쪽을 안 본다. 이쪽 옆을 본다. 도는 중이다.`,
  o:[
    { l:'① 홀수의 임자부터 찾는다.', k:'luck', dc:25,
      ok:`정면 눈들은 버려두고 외눈만 찾았다. 왼쪽, 허리 높이. 있다.<br><br>등불을 그쪽으로 홱 돌렸다. 옆으로 돌던 것이 빛에 박혀 멈췄다. 도는 패가 들키면 판은 끝이다.<br>정면의 눈들이 하나씩 꺼졌다. 몰이는 도는 놈이 자리를 잡아야 닫힌다. 닫히다 만 판은 버리는 것이다.`,
      ng:`왼쪽을 뒤지는데 외눈이 안 보인다. 아래를 안 본 탓이다.<br><br>그것은 배로 기어 발치까지 와 있었다. 들리는 건 일행 비명이 먼저였다.<br>정강이를 긁히고 뒹굴며 등불을 휘둘렀다. 눈들이 일제히 꺼졌다 켜졌다. 웃은 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 등불 하나를 더 켜고 다시 센다.', k:'fix', dc:23,
      ok:`기름이 아깝지만 두 번째 등불을 켰다. 빛이 넓어졌다.<br><br>여덟이다. 짝이 맞다. 하나는 아까 빛 밖에 걸쳐 있었을 뿐이다.<br>짝 맞는 눈들은 재기만 하다 간다. 수가 맞는 판은 무섭지 않다. 기름값은 시세보다 쌌다.`,
      ng:`불을 키우니 눈이 더 늘었다. 열둘. 그 가운데 둘은 너무 높다.<br><br>너무 높은 데서, 깜빡이지도 않고.<br>등불을 도로 줄였다. 못 본 것으로 하기엔 늦었지만, 보이는 채로 걷기엔 더 글렀다. 벽에 붙어 반 바퀴를 돌아 나왔다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S', t:'버릇 — 숨길 것',
  x:`사흘째다. 매복이 자꾸 앞서 있다.<br><br>
    쉬려고 고른 자리에 먼저 와 엎드려 있고, 꺾으려던 모퉁이에 미리 서 있다. 우연이 아니다.<br>
    일행을 봤다. 쉴 때는 꼭 벽을 등진다. 갈림길에서는 꼭 넓은 쪽을 고른다. 다 버릇대로 움직인다.<br><br>
    읽히고 있다. 노름꾼은 남의 버릇으로 먹고살았다. 제 버릇 숨기는 법도 같이 배웠다.`,
  o:[
    { l:'① 갈림길마다 주사위로 정한다.', k:'luck', dc:25, wake:1,
      ok:`꺼내 든 주사위에 길을 맡겼다. 홀수면 왼쪽, 짝수면 오른쪽. 쉴 자리도, 쉬는 시간도.<br><br>버릇이 사라진 일행은 읽을 수가 없다. 다음 모퉁이에 매복이 없었다. 그다음에도. 한 번은 버린 길 쪽에서 기다리다 지친 것이 돌아가는 소리를 들었다.<br>일행이 주사위를 신처럼 모시기 시작했다. 신이 아니라 셈이라고는 말하지 않았다.<br><br>제 패 숨기던 손이 판 전체의 패를 숨긴다. 열 사람 버릇을 주사위 한 알에 접어 넣는 법을 익혔다.`,
      ng:`주사위가 세 번 연달아 같은 길을 가리켰다. 일행이 주사위를 의심하기 시작했다.<br><br>반은 주사위를 따르고 반은 제 버릇대로 갔다. 갈라진 틈을 그것이 정확히 때렸다.<br>다시 모일 때까지 둘이 피를 흘렸다. 판이 갈라지면 어떤 패도 소용없다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 버릇을 미끼로 쓴다.', k:'hide', dc:25,
      ok:`늘 하던 대로 자리를 폈다. 등불, 깔개, 벽을 등진 배치. 그리고 빈 깔개만 두고 다들 맞은편 어둠에 엎드렸다.<br><br>그것이 왔다. 버릇대로 차려진 빈자리를 한참 내려다봤다.<br>속은 걸 알았을 때 그것이 낸 소리를 다들 오래 기억했다. 그날부터 매복이 끊겼다. 읽은 패가 가짜였다는 걸 아는 상대는 더는 못 읽는다.`,
      ng:`빈 깔개를 차려 두고 엎드렸다. 그것이 깔개 앞을 지나쳤다. 곧장 이쪽으로 왔다.<br><br>미끼를 보자마자 미끼 놓은 손을 센 것이다.<br>엎드린 채로 포위를 뚫었다. 등불도 깔개도 다 버렸다. 그 뒤로는 저쪽이 이쪽 수를 한 장 위에서 읽었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'S', t:'일행 — 소매 속 패',
  x:`일행 하나가 어제부터 왼팔을 아낀다.<br><br>
    짐은 오른쪽으로만 메고, 웃을 때 입만 웃는다. 노름꾼 눈에는 보인다. 소매에 패를 숨긴 손이다.<br>
    여기서 숨긴 패는 대개 상처다. 두고 갈까 봐 숨긴다.<br><br>
    문제는 여기 것들 코가 그 패를 먼저 읽는다는 것이다.`,
  o:[
    { l:'① 판 돌리듯 자연스럽게 소매를 걷게 한다.', k:'luck', dc:24, wake:1,
      ok:`쉴 때 끈 매듭을 그 사람 왼쪽에 놓고 풀어 달라 했다. 왼손이 나왔다. 소매가 걷혔다. 팔뚝에 긁힌 상처가 곪아 가고 있었다.<br><br>아무도 타박하지 않게 먼저 말했다. "숨긴 패 치고 작네." 웃음이 나오자 상처도 나왔다.<br>씻기고 약초를 붙이고 재를 덧발랐다. 그날 밤 어둠이 평소보다 가까이 왔다가, 읽을 냄새가 없어 돌아갔다.<br><br>패 숨긴 손을 꺾지 않고 탁자 위로 올리게 하는 법. 판에서 평생 쓴 재주의 가장 좋은 쓸모를 여기서 찾았다.`,
      ng:`매듭을 내밀자 그 사람이 오른손으로 받았다. 두 번째도. 세 번째에 눈치채고 낯빛이 굳었다.<br><br>숨긴 패를 지키는 손은 억지로 열면 판을 엎는다. 그 사람이 밤에 혼자 상처를 씻으러 갔다.<br>물가에서 비명이 났다. 달려가 끌어냈을 때 상처가 하나 늘어 있었다.`,
      win:{ exp:24, dream:3, item:'약초 뭉치' }, lose:{ hp:-28, mind:-16 } },
    { l:'② 밤새 그 사람 곁을 지킨다.', k:'steady', dc:23,
      ok:`아무 말 없이 잘 자리를 그 사람 옆에 폈다. 어둠 쪽에 이쪽 등을 두고.<br><br>밤중에 무엇이 왔다. 곪은 냄새를 따라온 것이다. 눈을 뜨고 있는 것과 눈이 마주쳤다.<br>재는 눈빛이 한참 오갔다. 셈이 안 맞았는지 돌아갔다. 아침에 그 사람이 제 입으로 상처를 보여 줬다.`,
      ng:`새벽녘에 깜빡 졸았다.<br><br>깨 보니 옆자리가 반쯤 끌려 나가 있었다. 발목을 잡고 당기는 중이었다. 소리 지르며 어깨를 잡아 되당겼다. 줄다리기 끝에 그것이 놓고 갔다.<br>그 사람 발목에 이빨 자리가 반지처럼 남았다. 숨긴 상처가 둘이 됐다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-17, spirit:-23 } }
  ] },

{ at:'S1', t:'표본실 — 금 가는 소리',
  x:`표본 선반이 벽을 가득 채웠다. 큰 병마다 무엇이 잠겨 있다.<br><br>
    몇 병은 안에서 두드린다. 똑. 똑. 유리마다 금이 실처럼 가 있다.<br>
    금 간 유리가 버티는 시간은 정해져 있다. 초읽기다. 병마다 초가 다를 뿐이다.<br><br>
    노름꾼은 초읽기 시계를 눈으로 잰다. 금의 길이가 남은 초다.`,
  o:[
    { l:'① 금 간 길이로 초를 센다.', k:'luck', dc:25, wake:1,
      ok:`병마다 금을 훑었다. 제일 길게 간 놈, 가지 친 놈, 아직 실금인 놈. 방 전체가 시계판이 됐다.<br><br>제일 급한 병에서 제일 먼 벽을 따라 길을 잡았다. 걸음도 초에 맞춰 끊었다.<br>마지막 사람이 문을 나설 때 등 뒤에서 퍽, 하고 첫 병이 터졌다. 센 초와 세 초 차이였다. 쏟아진 것이 바닥을 치는 소리를 문이 끊었다.<br><br>터질 것들 사이에서 초를 나눠 세는 눈. 판의 시계를 제 손목에 찬 것 같았다.`,
      ng:`금 하나 없는 병이 먼저 터졌다. 셈 밖의 패였다.<br><br>안에 든 것이 금을 안 내고 마개 쪽을 갉고 있었던 것이다. 유리가 아니라 뚜껑이 날았다.<br>쏟아진 것이 바닥에서 몸을 추스르는 사이 방을 가로질렀다. 뒤꿈치에 튄 것이 신발을 태웠다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, spirit:-17 } },
    { l:'② 두드리는 병에 등을 안 보이고 걷는다.', k:'evade', dc:24,
      ok:`선반을 마주 본 채 게걸음으로 지났다. 두드림이 이쪽 걸음을 따라온다. 똑. 똑.<br><br>등을 안 주면 조급해지는 건 저쪽이다. 두드림이 빨라지다 제풀에 그쳤다.<br>문턱을 넘고 나서야 등을 돌렸다. 병 하나하나에 손바닥이 안쪽에서 붙어 있었다.`,
      ng:`게걸음 중에 두드림이 뚝 그쳤다. 발도 멈췄다. 정적이 길었다.<br><br>다시 걷자 두드림이 아니라 긁는 소리가 났다. 모든 병에서 한꺼번에.<br>박자고 뭐고 뛰었다. 문을 닫을 때 유리 하나가 벌써 우는 소리를 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-21 } }
  ] },

{ at:'S1', t:'통풍구 — 주사위 소리',
  x:`천장 격자 위에서 그것이 따라온다. 발소리를 좇는 것이다.<br><br>
    이 복도는 길고, 격자는 스무 걸음마다 하나씩이다. 숨을 데가 없다.<br>
    주머니 속에서 뼈 주사위 두 알이 달그락거렸다. 평생 쥐고 산 물건이다.<br><br>
    잘 구르고, 멀리 가고, 소리가 좋다.`,
  o:[
    { l:'① 주사위를 굴려 보낸다.', k:'luck', dc:24, wake:1,
      ok:`샛복도 쪽으로 두 알을 힘껏 굴렸다. 달그락달그락. 뼈 구르는 소리가 복도를 길게 갔다.<br><br>천장 위 끌리는 소리가 그쪽으로 쏠렸다. 그 사이에 본복도를 다 건넜다.<br>멀리서 격자가 한 번 울리고, 와작, 하는 소리가 났다. 육이 나왔는지는 못 봤다.<br><br>평생 쥐어 온 것을 놓는 손이 떨리지 않았다. 판돈과 목숨의 시세를 한 번에 셈하는 법을 손이 먼저 알았다.`,
      ng:`굴렸는데 주사위가 문턱에 걸려 바로 앞 격자 밑에 멈췄다.<br><br>천장의 것이 바로 머리 위로 왔다. 격자 틈으로 침이 한 줄 떨어졌다.<br>벽에 붙어 숨을 끊고 반 시진을 섰다. 그것이 지나간 뒤 주사위를 주웠다. 합이 둘이었다. 최악의 패다. 맞는 점괘였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 낡은 송풍기 박자에 발을 맞춘다.', k:'hide', dc:25,
      ok:`복도 끝 송풍기가 돌다 걸리다 한다. 걸릴 때마다 철컹, 큰 소리가 난다.<br><br>철컹에 세 걸음. 멎으면 돌. 그 박자로 복도를 끊어 건넜다.<br>천장의 것은 철컹 소리가 날 때마다 격자를 긁었다. 쇳소리에 저도 귀가 먹는 것이다. 끝까지 발소리는 못 들었다.`,
      ng:`반쯤 갔을 때 송풍기가 아주 죽었다. 복도가 통째로 조용해졌다.<br><br>마지막 반걸음 소리가 천장까지 올라갔다. 위에서 몸 트는 소리.<br>격자와 격자 사이 벽에 붙어 버텼다. 그것이 격자마다 눈을 대고 들여다보며 지나갔다. 숨을 너무 오래 참아 눈앞이 깜깜해졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S1', t:'흰 가운 — 가슴에 숨긴 패',
  x:`복도 끝에서 흰 가운이 비틀비틀 걸어온다. 사람이다. 산 사람.<br><br>
    살려 달라고 한다. 같이 가게 해 달라고. 그런데 말하는 내내 왼손이 가슴께를 떠나지 않는다.<br>
    웃는데 눈만 웃고, 숨이 얕고 빠르다.<br><br>
    노름꾼은 저 손을 안다. 지는 패를 숨긴 손이다. 본인도 아는 지는 패.`,
  o:[
    { l:'① 멀찍이 세워 두고 패를 보자고 한다.', k:'luck', dc:25, wake:1,
      ok:`"거기 서서, 가운부터 열어 보시오." 열 걸음 밖에 세웠다.<br><br>사내 손이 한참 떨리다 단추를 풀었다. 갈비뼈 밑 살가죽이 숨과 따로 움직이고 있었다. 사내가 그걸 내려다보고, 울었다. 알고 있던 것이다.<br>먹을 것과 등불 하나를 바닥에 밀어 주고 문 하나를 사이에 뒀다. 사내가 문 저쪽에서 고맙다고 했다. 진심 같았다.<br><br>상대 패를 보는 눈만 있었다. 진 패를 쥔 사람을 어떻게 보낼지도 눈에 들어오기 시작했다.`,
      ng:`열라고 하자 사내 눈빛이 바뀌었다. 숨기던 손에 힘이 들어갔다.<br><br>"그냥 가게. 나도 몰라. 모른다고." 소리치며 다가온다. 막아선 일행과 실랑이가 붙었다.<br>그 바람에 가슴 속 것이 깼다. 가운 안에서 무엇이 요동치는 걸 다 같이 봤다. 사내가 제 발로 어둠으로 뛰어 들어갔다. 말리지 못했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 그대로 끼워 준다.', k:'bond', dc:24,
      doom:{ title:'품은 것', what:'숙주에서 나온 것에게 얼굴을 잡혀 끌려갑니다', dc:19, sec:40,
        text:`사내를 가운데 세우고 걸었다. 쉴 때는 곁에 앉았다. 그래야 낯빛을 읽는다.<br><br>새벽에 사내가 아주 편안한 숨을 쉬었다. 그게 신호였다. 가운이 안쪽에서 벌어졌다. 단추 풀리듯 조용히.<br>나온 것은 작고 빨랐다. 제일 가까운 체온으로 왔다. 얼굴에 감긴다. 숨이 막힌다. 그대로 바닥을 끌려간다. 격자 틈 쪽으로. 작은 것이 힘은 황소다.<br><br>곁을 준 게 패착이 아니다. 거리를 셈하지 않은 게 패착이다.`,
        dieText:`쉬는 자리에 흰 가운 사내가 혼자 앉아 있다.<br><br>가슴을 쓸어내린다. 이제 숨이 아주 편하다.<br>옆자리 바닥에, 격자까지 끌린 자국이 한 줄 나 있다.` },
      ok:`끼워 주되 자리는 이쪽이 정했다. 맞은편, 불 건너.<br><br>새벽에 사내 가슴이 벌어졌다. 나온 것이 체온을 찾아 뛰었다. 불을 넘지는 못했다. 미리 불가에 빙 둘러 둔 기름걸레가 제 몫을 했다.<br>타는 것은 작았고 소리는 컸다. 사내는 숨진 얼굴이 편안했다. 가운을 덮어 주었다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 먹을 것을 들려 보낸다.', k:'steady', dc:23,
      ok:`"같이는 못 가오." 대신 말린 고기 한 줄과 물을 들려 보냈다.<br><br>사내는 두 번 돌아보고 복도 저쪽으로 사라졌다.<br>이튿날 그 복도를 지나는데 격자 밑에 가운이 반듯하게 개켜 있었다. 들려 보낸 몫은 그 위에 그대로 있었다. 손도 안 댄 채. 마지막까지 제 입에 넣을 생각이 없던 사람이다. 다들 말없이 지나쳤다.`,
      ng:`들려 보냈는데 사내가 안 간다. 스무 걸음 뒤에서 계속 따라온다.<br><br>돌아보면 서고, 걸으면 걷는다. 하루 종일. 어두워질수록 거리가 줄었다.<br>결국 갈림길에서 길을 두 번 꺾어 떼어 냈다. 뒤가 허전한 게 꼭 빚 떼먹고 도망친 기분이었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S1', t:'에어록 — 바늘이 떠는 쪽',
  x:`에어록이 둘이다. 왼쪽 문, 오른쪽 문. 계기판은 다 죽었는데 바늘만 산 것처럼 떤다.<br><br>
    왼쪽 바늘은 고르게 떤다. 지잉, 지잉. 오른쪽 바늘은 셋 떨고 한 번 쉰다.<br>
    기계가 떠는 건가, 문 너머 무엇이 기대 있는 건가.<br><br>
    노름꾼은 떨림을 오래 봤다. 손 떠는 걸 보고 패를 읽는 게 업이었다.`,
  o:[
    { l:'① 바늘 떨림의 박자를 읽는다.', k:'luck', dc:25,
      ok:`왼쪽은 박자가 죽은 떨림이다. 기계 떨림. 오른쪽은 셋 떨고 쉰다. 쉬는 게 있는 건 숨이다.<br><br>숨 쉬는 문은 버리고 왼쪽으로 들어갔다. 낡은 펌프가 벽 속에서 돌고 있었다.<br>문이 닫히기 직전, 오른쪽 문 유리에 김이 한 번 뿌옇게 서렸다 걷혔다. 내쉰 것이다. 박자대로.`,
      ng:`읽는 사이 두 바늘이 같은 박자로 떨기 시작했다.<br><br>맞춰 주는 것이다. 어느 쪽에 있는 게 아니라 벽 속 어딘가에서, 양쪽 다 흔들면서.<br>아무 쪽이나 열고 뛰었다. 관 속 안개가 복도까지 따라 나왔다. 한참 달린 뒤에도 등 뒤에서 지잉, 지잉, 소리가 들리는 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-21 } },
    { l:'② 문틈에 손등을 대 본다.', k:'sense', dc:23,
      ok:`두 문틈에 차례로 손등을 댔다. 왼쪽은 찬바람이 가늘게 샌다. 뚫린 길이다. 오른쪽은 미지근하고 축축하다.<br><br>찬 쪽으로 들어갔다. 바람은 거짓말을 안 한다.<br>문을 잠그고 돌아서는데 오른쪽 문 안에서 문고리 돌리는 소리가 났다. 안쪽에서. 천천히.`,
      ng:`오른쪽 문틈에 손등을 댄 순간 문이 안쪽에서 울컥 밀렸다.<br><br>문고리를 쥐고 있던 모양이다. 이쪽 체온을 기다리면서.<br>온몸으로 문을 되밀고 빗장을 걸었다. 문짝이 두 번 더 울리고 조용해졌다. 손등에 소름이 한나절 갔다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S1', t:'녹은 바닥 — 성한 칸',
  x:`복도 바닥이 레이스처럼 삭았다. 그것들 피가 지나간 자리다.<br><br>
    구멍마다 아래층 어둠이 올려다보인다. 성한 칸이 띄엄띄엄 패처럼 남았다.<br>
    어느 칸이 무게를 받는지는 밟아 봐야 안다.<br><br>
    밟아 보고 알면 늦는다.`,
  o:[
    { l:'① 성한 칸을 골라 징검다리로 삼는다.', k:'luck', dc:25,
      doom:{ title:'무른 칸', what:'꺼진 바닥 밑 어둠으로 끌려 내려갑니다', dc:19, sec:45,
        text:`배낭을 먼저 던져 칸을 시험했다. 받는 칸만 디뎠다. 셋째 칸까지는.<br><br>넷째 칸은 겉만 성했다. 삭은 속이 바스러지며 허리까지 꺼졌다. 그리고 아래에서 무엇이 신발을 쥐었다.<br>아래층 것들은 구멍 밑에서 기다린다. 자리까지 깔고. 떨어지는 것이 끼니인 것이다. 바닥 밑으로 끌려 내려간다. 손톱이 삭은 바닥을 긁는다.<br><br>칸은 제대로 읽었다. 칸 밑에 물주가 사는 걸 못 읽었다.`,
        dieText:`바닥 구멍 하나가 조금 넓어졌다.<br><br>테두리가 반질반질하다. 자주 쓰는 구멍이다.<br>구멍가에 뼈 주사위 한 알이 놓여 있다. 일이 위를 보고 있다.` },
      ok:`배낭을 칸마다 먼저 던졌다. 받으면 산 칸, 꺼지면 죽은 칸.<br><br>산 칸만 이어 디뎠다. 구멍 위를 건널 때마다 아래에서 찬 공기가 올라왔다. 숨 냄새가 섞여 있었다.<br>다 건너고 배낭을 주워 멨다. 바닥짐이 바닥값을 했다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 벽 배관을 잡고 가장자리로 돈다.', k:'evade', dc:24,
      ok:`바닥을 버리고 벽을 골랐다. 배관을 잡고 가장자리 성한 줄을 게걸음으로 탔다.<br><br>배관이 우는 소리를 낼 때마다 멈췄다 갔다.<br>중간에 발밑 구멍으로 아래층이 보였다. 구멍 바로 밑에 무엇이 입을 벌리고 기다리고 있었다. 떨어지는 것만 받아먹는 자세로. 발끝에 힘이 저절로 들어갔다.`,
      ng:`배관 한 마디가 삭아 있었다. 쥐는 순간 부러졌다.<br><br>쏟아진 관 속 물이 바닥을 태우며 구멍을 넓혔다. 매달린 채 발 디딜 칸이 녹아 없어지는 걸 봤다.<br>남은 배관을 타고 억지로 건넜다. 손바닥이 녹물에 데어 한 꺼풀 일어났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-16 } }
  ] },

{ at:'S1', t:'알의 방 — 엎어 둔 패',
  x:`넓은 방 바닥에 가죽 주머니 같은 것들이 줄지어 앉아 있다. 허리 높이. 수십.<br><br>
    꼭 엎어 둔 패다. 몇은 꺼져서 쭈그러들었고, 몇은 팽팽하다. 팽팽한 것 겉에는 김이 서렸다.<br>
    방을 가로지르면 지름길이다. 돌아가면 어둠 속 한 시진.<br><br>
    판 위를 질러가느냐, 판을 접고 일어서느냐.`,
  o:[
    { l:'① 판을 접는다 — 먼 길로 돈다.', k:'steady', dc:24, wake:1,
      ok:`방을 안 질렀다. 벽을 따라 어둠 속을 한 시진 돌았다.<br><br>아무 일도 없었다. 그게 딴 것이다. 아무 일도 없는 한 시진이 이 방에서 제일 비싼 상품이다.<br>다 돌았을 때 등 뒤 방 안에서 무엇이 젖은 소리로 움직이는 게 들렸다. 패 사이를 도는 물주 소리다. 앉았으면 만났을 것이다.<br><br>노름꾼의 제일 센 기술이 접는 것이라는 걸 아는 데 평생이 걸렸다. 이길 판이 아니라 앉을 판을 고르는 눈이 떠졌다.`,
      ng:`돌아가는 어둠이 빈 어둠이 아니었다.<br><br>벽 중간, 잠든 무엇의 옆구리를 스쳤다. 비늘이 손바닥 밑에서 꿈틀했다.<br>숨을 끊고 뒷걸음으로 빠져 다시 돌았다. 두 시진이 걸렸다. 다 돌고 나니 무릎이 꺾였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 꺼진 패만 밟고 지른다.', k:'luck', dc:26,
      doom:{ title:'살아 있는 패', what:'알 틈의 것에게 발목을 잡혀 둥지로 끌려갑니다', dc:20, sec:40,
        text:`쭈그러든 것만 골라 디뎠다. 죽은 패는 안 문다. 하나, 둘, 여섯.<br><br>일곱째 꺼진 것은 꺼진 게 아니라 비운 것이었다. 속을 비우고 뚜껑이 된 것. 밑에서 긴 것이 발목을 감았다.<br>당긴다. 팽팽한 주머니들 사이로, 방 안쪽 젖은 어둠으로. 지나는 길에 주머니들이 일제히 이쪽으로 기우는 게 보였다. 상 차려지는 걸 아는 것이다.<br><br>죽은 패만 밟는 수는 좋았다. 죽은 패인 척하는 놈까지는 셈에 없었다.`,
        dieText:`방바닥 주머니들 사이에 쓸린 자국이 한 줄 나 있다.<br><br>자국 끝에 신발 한 짝.<br>쭈그러졌던 주머니 하나가 다시 팽팽해졌다.` },
      ok:`쭈그러든 것만 밟았다. 발바닥에 닿는 느낌이 마른 것만 골라.<br><br>방 한가운데서 팽팽한 놈 하나가 이쪽으로 기울었다. 숨을 끊고 반 박자 기다렸다 다음 칸을 밟았다.<br>다 건너고 돌아보니 디딘 자국이 한 줄로 곧았다. 꺼진 것들이 처음부터 길처럼 놓여 있었던 것이다. 누가, 무엇이 깔아 둔 길인지는 생각하지 않기로 했다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S1', t:'당직 책상 — 물주의 장부',
  x:`쓰러진 당직 책상에 장부가 펴져 있다. 먹이 주는 시간표다.<br><br>
    「급이 후 두 시간, 순회 없음」. 밑줄이 두 번 그어져 있다. 마지막 장은 글씨가 흐트러졌다.<br>
    「이제 그것이 우리를 급이 시간에 센다」.<br><br>
    시계는 다 죽었다. 하지만 셈은 남는다. 노름꾼은 남의 장부 읽는 걸 좋아한다.`,
  o:[
    { l:'① 장부로 판때를 짠다.', k:'luck', dc:24,
      ok:`멀리서 유리 두드리는 소리가 한바탕 끓다가 뚝 그쳤다. 어디선가 먹은 것이다.<br><br>그때부터 제 맥으로 두 시간을 쟀다. 장부 말이 맞다면 지금부터가 빈 시간이다.<br>빈 시간 안에 두 구역을 질렀다. 마지막 모퉁이에서 순회가 다시 시작되는 발소리를 등 뒤로 들었다. 죽은 사람 장부가 산 사람 넷을 건넸다.`,
      ng:`두 시간을 쟀는데 한 시간 반 만에 발소리가 왔다.<br><br>장부가 낡은 것이다. 그것이 자랐고, 끼니가 늘었다.<br>모퉁이 하나를 사이에 두고 엇갈렸다. 벽 하나 너머로 비린 숨이 지나갔다. 장부 귀퉁이에 적어 넣었다. 「지금은 한 시간 반」. 다음 사람 몫이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 책상 서랍을 턴다.', k:'sense', dc:23,
      ok:`서랍 둘은 비었고 셋째는 잠겼다. 잠긴 서랍이 좋은 서랍이다.<br><br>철사로 열었다. 봉한 물병 하나와 호루라기, 그리고 가족 사진이 나왔다.<br>물병만 챙기고 사진은 도로 엎어 두었다. 호루라기는 두고 간다. 여기서 소리 나는 물건은 짐이 아니라 빚이다.`,
      ng:`셋째 서랍을 당기자 안에서 유리병이 넘어져 깨졌다. 노란 김이 훅 올라왔다.<br><br>표식 약품이다. 옷에 밴 냄새가 지워지지 않는다. 복도 저쪽에서 코 훌쩍이는 소리가 났다.<br>고인 빗물에 겉옷을 빨아 쥐어짰다. 냄새는 반만 빠졌다. 그날 내내 뒤가 시끄러웠다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-14, spirit:-20 } }
  ] },

{ at:'S2', t:'울타리 — 차례로 미는 것들',
  x:`밤. 울타리 말뚝이 운다. 한 칸, 그 옆 칸, 또 그 옆 칸.<br><br>
    차례대로다. 어둠 속에서 그것들이 칸마다 몸을 대 보고 있다. 어제는 여기까지, 오늘은 한 칸 더.<br>
    시험이 끝난 칸은 다시 안 민다.<br><br>
    수를 세면서 민다. 노름꾼은 수 세는 상대를 반긴다. 수를 세는 쪽은 수에 걸린다.`,
  o:[
    { l:'① 어제 시험한 칸 뒤에 잔다.', k:'luck', dc:25, wake:1,
      ok:`우는 칸들을 세서 저쪽의 장부를 그렸다. 시험이 끝난 칸, 오늘 밀 칸, 내일 밀 칸.<br><br>시험 끝난 칸 안쪽에 자리를 폈다. 한 번 민 칸은 다시 안 민다. 저쪽 셈이 그렇다.<br>밤새 세 칸 너머에서 말뚝이 울었다. 정확히 차례대로. 상대의 장부를 베껴 적으면 상대의 다음 수는 내 자리 밖이다.<br><br>쫓기며 세던 수를 마주 서서 세게 됐다. 상대가 셈을 쓰면 그 셈이 곧 상대의 버릇이다.`,
      ng:`새벽에 순서가 깨졌다. 우는 칸이 갑자기 세 칸을 건너뛰었다. 이쪽 칸으로.<br><br>세는 걸 들킨 것이다. 보던 눈이 어둠 속에 있었다.<br>말뚝이 넘어가기 전에 짐을 걷어 뛰었다. 등 뒤에서 울타리 한 칸이 길게 비명을 질렀다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 오늘 밀 칸에 쇳소리를 매단다.', k:'fix', dc:24,
      ok:`빈 깡통과 볼트를 철사에 꿰어 다음 차례 칸에 매달았다.<br><br>밤중에 그 칸이 밀리며 쇳소리가 자지러졌다. 어둠 속에서 혼비백산 흩어지는 발소리들.<br>그 뒤 사흘, 울타리가 조용했다. 시험지에 모르는 문제가 나온 것이다. 채점을 다시 하는 동안 이쪽은 잤다.`,
      ng:`쇳소리가 한 번 울리고, 다음 날 깡통이 사라져 있었다.<br><br>철사째 뜯어 간 것이다. 울타리 너머 풀밭에서 깡통 소리가 났다. 일부러 내는 소리. 달그락. 달그락.<br>겁주려는 건지 배우는 건지 알 수 없었다. 어느 쪽이든 잠은 다 잤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'S2', t:'물에 잠긴 양치밭 — 잔물결',
  x:`양치잎이 가슴 높이로 솟은 물밭이다. 건너편까지 백 걸음.<br><br>
    수면에 잔물결이 지나간다. 간격을 두고, 두 줄기로. 바닥을 걷는 무엇의 등이 미는 물이다.<br>
    물결과 물결 사이가 비는 때가 있다.<br><br>
    노름꾼은 패와 패 사이를 세며 살았다. 이건 그냥 큰 판이다. 패가 이빨일 뿐.`,
  o:[
    { l:'① 물결 간격에 맞춰 끊어 건넌다.', k:'luck', dc:26,
      doom:{ title:'둘째 물결', what:'물밑의 것에게 끌려 가라앉습니다', dc:20, sec:40,
        text:`물결이 가고, 다음 물결까지 스물. 그 스물 안에 열 걸음씩 끊어 건넜다.<br><br>반쯤 건넜을 때 셈에 없던 물결이 왼쪽에서 왔다. 두 마리였다. 사이사이가 빈 게 아니라 교대였던 것이다.<br>정강이를 무엇이 감았다. 물이 뒤집히고 하늘이 물밑으로 갔다. 양치잎들이 머리 위에서 닫힌다. 끌려 내려가는 내내 수면이 멀어지는 게 보였다.<br><br>간격은 맞게 셌다. 패가 두 벌인 걸 몰랐을 뿐이다.`,
        dieText:`양치밭 수면이 고요하다.<br><br>물결 두 줄이 밭 한가운데서 만난다.<br>만나는 자리에 거품이 몇 알 올라와 터졌다.` },
      ok:`물결이 지나가고 다음 물결까지를 맥으로 쟀다. 스물. 그 안에 열 걸음.<br><br>끊어 건너기를 다섯 번. 마지막 열 걸음 앞에서 물결이 뚝 멎었다. 멎은 게 제일 나쁘다. 듣고 있는 것이다.<br>숨을 물에 잠그고 돌이 됐다. 영원 같은 스물 뒤에 물결이 다시 지나갔다. 그 등을 배웅하며 뭍에 올랐다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 잠긴 울타리 윗대를 타고 건넌다.', k:'evade', dc:25,
      ok:`물에 반쯤 잠긴 울타리가 밭을 가로지른다. 윗대가 손 뼘 너비다.<br><br>팔을 벌리고 외줄 타듯 건넜다. 물결이 밑을 지나갈 때마다 울타리가 흔들렸다. 흔들리면 앉아서 쇠를 끌어안았다.<br>건너편에 내려서자 울타리가 등 뒤에서 한 번 크게 출렁였다. 돌아보지 않았다.`,
      ng:`중간쯤에서 삭은 윗대가 발밑에서 내려앉았다. 허리까지 물에 빠졌다.<br><br>물밭 전체의 물결이 일제히 이쪽으로 방향을 틀었다.<br>울타리를 타 넘으며 미친 듯이 갔다. 마지막엔 반쯤 헤엄이었다. 뭍에 구르고 나서 보니 바짓단이 한 뼘 찢겨 나가 있었다. 이빨 모양으로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S2', t:'진창 — 큰 보폭',
  x:`진창에 발자국이 찍혀 있다. 하나에 사람 둘이 들어앉을 크기다.<br><br>
    보폭이 스무 걸음. 자국마다 빗물이 고여 작은 못이 됐다.<br>
    잔발자국들이 사방에 있는데, 큰 자국 줄만은 하나같이 피해 갔다. 아무도 그 길을 안 밟는다.<br><br>
    땅이 울리기 시작했다. 돌아오는 것이다. 그 큰 것이.`,
  o:[
    { l:'① 큰 발자국 속에 엎드린다.', k:'luck', dc:24,
      ok:`셈은 이렇다. 모두가 피하는 자리는 저쪽 셈에 없는 자리다. 제 발자국을 제가 살피는 짐승은 없다.<br><br>고인 자국 속에 일행을 눕히고 흙탕을 끼얹었다. 울림이 커지고, 하늘이 어두워지고, 다음 발이 스무 걸음 앞 제자리에 내려앉았다. 진흙 비가 쏟아졌다.<br>울림이 멀어질 때까지 못 속에 있었다. 아무도 숨을 쉰 기억이 없다고 했다.`,
      ng:`보폭을 열아홉으로 잘못 쟀다. 다음 발이 한 걸음 옆에 떨어졌다.<br><br>땅이 뒤집히며 못물이 통째로 쏟아져 나왔다. 귀가 멍하고 눈앞이 흔들렸다.<br>뒹굴어 나와 진창을 기었다. 그것은 발밑을 안 봤다. 그게 전부였다. 한나절 귀에서 종이 울렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 잔발자국들이 돌아간 길로 돈다.', k:'sense', dc:24,
      ok:`잔발자국이 큰 자국을 피해 꺾인 결을 따라갔다. 여기 사는 것들의 에움길이다.<br><br>길은 물가 바위 틈으로 이어졌다. 틈 안 마른 웅덩이에 물고기가 갇혀 퍼덕이고 있었다.<br>울림이 지나가는 동안 바위 틈에서 물고기를 건졌다. 남의 길에서 남의 끼니까지. 오늘 셈은 이쪽이 땄다.`,
      ng:`에움길 중간에 잔것들의 몸이 널려 있었다. 에움길이 길목이 된 것이다.<br><br>길목 주인은 바위 위에 있었다. 뛰어내리는 그림자를 보고 흩어졌다.<br>다리를 긁히며 빠져나왔다. 남의 길은 남의 사정까지 얹어 파는 길이었다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'급이대 — 종 줄',
  x:`숲 가장자리 빈터에 녹슨 급이대가 섰다. 도르래, 빈 고기 갈고리, 그리고 종.<br><br>
    종 줄이 바람도 없는데 흔들리고 있다. 방금까지 누가, 무엇이 쥐고 있던 것처럼.<br>
    여기 것들은 종소리가 고기라는 걸 배웠을 것이다. 종 치던 사람들은 이제 없다.<br><br>
    빈터를 질러야 한다. 종을 쓸 것인가, 치울 것인가.`,
  o:[
    { l:'① 종을 먼저 쳐 판을 연다.', k:'luck', dc:25,
      ok:`줄을 세게 당기고 바람 위쪽 덤불로 뛰었다. 종소리가 빈터를 갈랐다.<br><br>사방에서 그것들이 몰려들었다. 빈 갈고리 밑에 모여 서로 으르렁대는 사이, 빈터 반대편을 질렀다.<br>다 건넜을 때 등 뒤에서 종이 다시 울렸다. 바람이 아니다. 줄 끝을 쥔 것이 이쪽을 보고 있었다. 종 치는 법을 배운 것이다. 판을 여는 법을.`,
      ng:`종을 치고 뛰는데 바람이 돌았다. 냄새가 빈터를 가로질러 깔렸다.<br><br>갈고리 밑에 모였던 것들이 일제히 고개를 들었다. 고기가 어디 있는지 안 것이다.<br>전력으로 뛰었다. 맨 뒤에서 꼬리가 허공을 후렸다. 등을 스친 바람만으로 어깨가 빠질 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 줄을 끊고 추를 챙긴다.', k:'break', dc:24,
      ok:`종 줄을 타고 올라가 추를 뽑고 줄을 끊었다. 소리 없이.<br><br>이제 이 빈터에서 저녁 종은 안 울린다. 종에 길든 것들은 종 없는 빈터에 볼일이 없다.<br>빈터를 느긋하게 질렀다. 주머니 속 종 추가 걸음마다 허벅지를 쳤다. 묵직한 게 꼭 따 온 판돈 같았다.`,
      ng:`줄을 끊는 순간 종이 마지막으로 한 번 울었다. 길고, 크게.<br><br>이 빈터가 생긴 이래 제일 성실한 종소리였을 것이다.<br>사방에서 답이 왔다. 나무 위로 올라가 한나절을 버텼다. 종 추는 챙겼다. 값은 치렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-31, mind:-15 } },
    { l:'③ 급이대 물품함을 턴다.', k:'sense', dc:23,
      ok:`급이대 다리에 물품함이 붙어 있다. 녹은 자물쇠가 손에서 부서졌다.<br><br>기름 먹인 장갑, 갈고리 날, 그리고 가축용 소금 덩이가 나왔다. 소금은 소금이다.<br>함 바닥에 사육 일지가 깔려 있었다. 마지막 줄. 「이제 종을 치면 우리가 나간다」.`,
      ng:`물품함을 여는데 함 속에서 새 같은 것들이 터져 나왔다. 비늘 날개가 얼굴을 치고 지나갔다.<br><br>날것들이 빈터 위를 돌며 자지러지게 울었다. 위치를 광고하는 소리다.<br>함을 버리고 덤불로 뛰었다. 한참을 돌아 나왔다. 손등이 긁혀 피가 났다.`,
      win:{ exp:17, dream:2, item:'소금 덩이' }, lose:{ mind:-15, spirit:-19 } }
  ] },

{ at:'S2', t:'알 무덤 — 어미의 셈',
  x:`흙무덤이 김을 올리고 있다. 둘레에 알이 돌려 묻혔다. 가지런히.<br><br>
    무덤 곁에 사냥감이 쟁여져 있다. 갓 잡은 것. 제일 좋은 부위가 그대로다.<br>
    어미는 순찰 중이다. 언제 도는지는 모른다.<br><br>
    알의 배치가 눈에 밟힌다. 가지런한 것은 세어 둔 것이다. 세어 둔 것은 축나면 들킨다.`,
  o:[
    { l:'① 무덤은 안 건드리고 곁의 고기만 벤다.', k:'luck', dc:25,
      doom:{ title:'돌아온 어미', what:'어미에게 물려 알 무덤 곁으로 끌려갑니다', dc:19, sec:45,
        text:`알은 눈길도 안 주고 쟁인 고기에만 칼을 댔다. 두 근만. 티 안 나게.<br><br>그늘이 등을 덮었다. 소리가 없었다. 그 덩치가, 소리가 없었다.<br>어깨와 외투가 통째로 물렸다. 들린다. 끌려간다. 알 무덤 곁, 쟁인 것들 옆자리에 내려놓는다. 가지런히. 어미는 셈이 밝다. 축난 두 근을 채워 넣은 것이다.<br><br>고기만 센 게 아니었다. 무게로 세는 셈이었다.`,
        dieText:`알 무덤 곁에 쟁인 몫이 하나 늘었다.<br><br>가지런히 놓였다.<br>김 오르는 무덤가에서 알 하나가 처음으로 움직였다.` },
      ok:`쟁인 것 맨 밑단에서만 두 근을 베고, 벤 자리를 양치잎으로 덮어 모양을 살렸다.<br><br>무게는 줄어도 모양은 그대로다. 어미 눈은 모양을 센다. 그쪽에 걸었다.<br>빠져나와 한참 뒤에 돌아봤다. 돌아온 어미가 쟁임 더미에 코를 대고 오래 서 있었다. 더 오래는 안 봤다. 딴 판은 빨리 뜨는 것이다.`,
      win:{ exp:22, dream:3, item:'짐승 고기' } },
    { l:'② 다 버리고 바람 아래로 크게 돈다.', k:'steady', dc:23,
      ok:`고기도 알도 셈에서 지웠다. 바람 아래쪽으로 크게 돌았다.<br><br>도는 길에 어미와 스쳤다. 숲 하나를 사이에 두고. 나무 꼭대기들이 차례로 휘는 걸로만 알았다.<br>빈손이지만 다들 손이 떨리지 않았다. 그게 남는 장사일 때가 있다.`,
      ng:`도는 길이 어미의 순찰길과 겹쳤다. 마주 오는 울림에 양치밭에 처박혔다.<br><br>어미가 바로 옆을 지나갔다. 기둥 같은 다리가 한 걸음, 두 걸음. 젖은 흙이 튀어 얼굴을 덮었다.<br>지나가고 한참 뒤에야 누가 울음을 터뜨렸다. 막느라 다들 혼났다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-18, spirit:-23 } }
  ] },

{ at:'S2', t:'짐 승강기 — 삭은 줄',
  x:`낡은 승강기 곁에 작은 짐 승강기가 따로 있다. 웅크리면 사람 하나, 아니면 짐 전부.<br><br>
    줄을 봤다. 꼬인 쇠줄 아홉 가닥 중 여섯이 삭아 끊겼다. 남은 세 가닥.<br>
    아래는 어둡고, 사다리는 녹슬었지만 통째다.<br><br>
    셋 중 몇이 버틸지. 이건 아주 낯익은 종류의 판이다.`,
  o:[
    { l:'① 짐만 올리고 몸은 사다리로 간다.', k:'steady', dc:24,
      ok:`짐을 다 싣고 줄을 올렸다. 승강기가 비명을 지르며 올라갔다. 온 어둠이 그 소리를 들었다.<br><br>그 사이 일행은 반대쪽 사다리를 소리 없이 탔다. 어둠의 귀가 전부 승강기 쪽에 가 있었다.<br>위에서 짐을 찾고 사다리 입구를 막았다. 소리를 판돈으로 걸고 몸을 건졌다. 남는 셈이다.`,
      ng:`반쯤 올라갔을 때 줄이 끊겼다. 짐이 통째로 바닥을 때렸다.<br><br>어둠 속 사방에서 그 소리를 향해 몰려가는 기척이 났다. 사다리를 미친 듯이 탔다.<br>짐은 포기했다. 아침에 내려다보니 터진 자루들 사이에 먹을 것만 골라 사라지고 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 제일 가벼운 제가 타 본다.', k:'luck', dc:26,
      doom:{ title:'삭은 자리', what:'끊긴 승강기와 함께 어둠 밑으로 떨어져 끌려갑니다', dc:20, sec:40,
        text:`세 가닥이면 한 사람 몫은 된다. 제일 가벼운 몸으로 탔다.<br><br>중간쯤에서 한 가닥이 퉁, 하고 나갔다. 두 가닥. 그리고 퉁. 바닥까지 한참을 떨어졌다.<br>부서진 틀 속에서 숨을 고르는데 밑바닥 어둠이 움직였다. 여기는 떨어진 것이 모이는 자리다. 모이는 자리에는 줍는 것이 산다. 틀째로 끌려간다. 위쪽 빛이 동전만 하게 멀어진다.<br><br>세 가닥 중 둘이 나갔다. 셈보다 하나 빨랐다. 늘 그 하나가 문제다.`,
        dieText:`수직 통로 밑에서 쇠 긁리는 소리가 한 번 올라왔다.<br><br>끊긴 줄 세 가닥이 바람에 흔들린다.<br>통로 가장자리에 뼈 주사위 두 알이 놓여 있다. 합이 일곱이다.` },
      ok:`탔다. 줄이 울면서 올라갔다. 꼭대기 반 뼘 전에 한 가닥이 퉁, 하고 나갔다.<br><br>틀이 기우는 순간 문턱으로 몸을 던졌다. 등 뒤에서 승강기가 반 층 미끄러져 걸렸다.<br>턱에 걸터앉아 한참 웃었다. 딴 판돈은 목숨 하나. 원금 그대로지만, 판이 판인 만큼 큰 장사다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S2', t:'비 — 공평한 판',
  x:`천장 유리 안쪽에 맺힌 물이 비가 되어 쏟아지는 시간이 있다. 한바탕, 장대비처럼.<br><br>
    빗소리에 모든 귀가 먹는다. 이쪽 귀도, 저쪽 귀도.<br>
    일행은 비를 피해 기다리자 한다. 노름꾼 생각은 다르다.<br><br>
    서로 패를 못 보는 판은 공평한 판이다. 공평한 판은 준비한 쪽이 먹는다.`,
  o:[
    { l:'① 비 오기 전에 길을 세어 두고, 비에 걷는다.', k:'luck', dc:25, wake:1,
      ok:`비 그친 사이에 건널 길을 걸음 수로 다 세어 두었다. 마흔둘, 왼쪽 꺾어 열일곱, 바위 짚고 아홉.<br><br>비가 쏟아지자 눈 감고도 걷는 그 길을 걸었다. 빗소리가 발소리를 지우고, 빗물이 냄새를 지웠다.<br>사냥하는 것들은 비에 움직이지 않았다. 패 안 보이는 판에 돈 거는 짐승은 없다. 걸 줄 아는 건 사람뿐이다.<br><br>남들이 운에 맡기는 시간을 미리 센 수로 바꿔 넣었다. 운을 준비로 바꾸는 것, 그게 평생 하던 일의 알맹이였다.`,
      ng:`세어 둔 길 복판에 쓰러진 나무가 새로 누워 있었다. 비 오기 전엔 없던 것이다.<br><br>걸음 수가 다 틀어졌다. 빗속에서 길을 잃고 바위 밑에 처박혀 비가 그치기를 기다렸다.<br>젖은 몸으로 밤을 났다. 이가 밤새 딱딱 부딪쳤다. 그 소리가 어디까지 들렸을지는 생각 안 하기로 했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 비를 받아 둔다.', k:'fix', dc:23,
      ok:`기름천을 돌려 빗물을 받았다. 유리 천장을 거쳐 온 물이라 맑다.<br><br>물통마다 채우고도 남았다. 남은 것으로 다들 얼굴을 씻었다. 며칠 만에 처음으로.<br>빗소리 밑에서는 웃어도 안 들린다. 다들 조금씩 웃었다.`,
      ng:`천이 빗물을 받아 북처럼 울렸다. 둥. 둥. 빗소리와 다른 소리.<br><br>천 귀퉁이가 어둠 쪽에서 당겨졌다. 궁금한 것이 와서 물고 있었다.<br>천을 놓아 주고 물통 하나만 건졌다. 비 그친 뒤 그 천이 높은 가지에 깃발처럼 걸려 있었다.`,
      win:{ exp:17, dream:2, item:'맑은 물' }, lose:{ mind:-14, spirit:-18 } }
  ] }

]);

// ==========================================
// 🧺 행상 (peddler) · 자원 없음
// ==========================================
kJob('peddler', 'S', [

{ at:'S', t:'입구 — 짐 덜기',
  x:`문턱 앞에서 봇짐을 내렸다. 들어가기 전에 짐을 다시 싸는 건 행상의 오랜 버릇이다.<br><br>
    여기부터는 사냥터다. 무거우면 느리고, 느리면 끼니가 된다.<br>
    무엇을 지고 무엇을 버릴 것인가. 평생 물건의 값을 매겨 왔다.<br><br>
    오늘 저울 한쪽에는 물건이, 한쪽에는 목숨이 올라가 있다.`,
  o:[
    { l:'① 값나가는 것부터 버린다.', k:'luck', dc:25, wake:1,
      ok:`놋그릇, 거울, 비단 반 필. 제일 비싼 것부터 문턱에 부렸다. 반짝이고, 소리 나고, 냄새 배는 것들이다.<br><br>남긴 건 끈, 소금, 마른 먹을 것, 기름천. 싸구려만 남은 봇짐이 등에서 반으로 가벼워졌다.<br>안쪽에서 보니 문턱에 버린 거울이 등불을 받아 번쩍였다. 무엇이 그 앞에 한참 붙어 있었다. 비싼 것이 발을 묶는 건 사람만이 아니다.<br><br>값과 쓸모가 다른 물건이라는 걸 머리로는 알았다. 오늘 처음으로 손이 그 셈대로 움직였다.`,
      ng:`버리다가 비단 반 필에서 손이 멈췄다. 석 달 길품이 든 물건이다.<br><br>결국 바닥에 둘둘 말아 지고 들어갔다. 반나절 만에 가시덤불이 비단을 물었다. 당기는 소리가 어둠을 다 깨웠다.<br>비단을 찢어 버리고 뛰었다. 석 달 길품이 덤불에 깃발처럼 걸렸다. 이쪽 지나간 자리라고 광고하는 깃발이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 다 지고 간다 — 지는 법을 바꿔서.', k:'steady', dc:24,
      ok:`버리는 대신 다시 쌌다. 무거운 것은 등판에 바짝, 소리 나는 것은 천에 싸서 속으로, 끈은 두 번씩.<br><br>뛰어 봤다. 소리가 안 난다. 흔들어 봤다. 쏠리지 않는다.<br>짐이 몸이 되게 싸는 법은 길 삼십 년이 가르쳐 준 것이다. 느린 대신 온전하게 걸었다.`,
      ng:`다 지고 백 걸음 만에 숨이 찼다. 어깨끈이 살을 파고들었다.<br><br>쉬는 횟수가 늘었다. 쉴 때마다 어둠이 한 뼘씩 가까이 왔다.<br>결국 고개 하나를 못 넘고 절반을 부렸다. 버릴 걸 버리는 데 한나절과 어깨 살갗이 들었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'방울 — 소리 나는 짐',
  x:`봇짐 꼭대기에 방울이 달려 있다. 장이 서는 골목마다 이 소리로 손님을 불렀다.<br><br>
    걸음마다 딸랑, 딸랑. 여기서 그 소리는 손님이 아니라 다른 것을 부른다.<br>
    떼자니 삼십 년을 같이 걸은 물건이다.<br><br>
    어둠 저쪽에서 무엇이 걸음을 멈추고 귀를 세우는 기척이 났다.`,
  o:[
    { l:'① 방울을 떼어 미끼로 쓴다.', k:'luck', dc:24,
      ok:`방울을 떼어 손에 쥐었다. 가벼운 쇠붙이 하나가 이렇게 무겁다.<br><br>길목이 수상할 때마다 방울을 반대쪽으로 던졌다. 딸랑. 어둠이 그쪽으로 쏠리면 이쪽으로 지났다.<br>세 번째 길목에서 방울을 영영 잃었다. 던진 자리에서 소리가 두 번 나고 그쳤다. 무엇이 물고 간 것이다. 삼십 년 치 손님값을 한 번에 했다.`,
      ng:`던진 방울이 돌에 맞고 이쪽으로 굴러 돌아왔다. 딸랑딸랑, 발치까지.<br><br>어둠이 소리를 따라왔다. 방울을 주워 쥐고 소리를 죽인 채 뛰었다.<br>손바닥 안에서 방울이 자꾸 울려고 했다. 손에 땀이 나도록 쥐고 한 식경을 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 방울 혀를 뽑고 단다.', k:'fix', dc:23,
      ok:`방울을 열어 혀를 뽑았다. 소리 안 나는 방울을 도로 짐에 달았다.<br><br>삼십 년 물건은 그대로 있고 소리만 없다. 방울 혀는 주머니에 넣었다.<br>길이 끝나면 도로 끼울 것이다. 그때까지 이 방울은 눈 감은 손님맞이다. 걸음이 한결 가벼웠다.`,
      ng:`혀를 뽑는데 손이 미끄러져 방울이 바닥을 굴렀다. 딸랑딸랑딸랑. 평생 들은 중 제일 긴 소리였다.<br><br>어둠 여기저기서 돌 구르는 소리가 답했다.<br>방울을 낚아채 품에 넣고 벽에 붙었다. 더듬는 기척들이 바로 앞을 두 번 지나갔다. 혀 없는 방울이 품속에서 식은땀에 젖었다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S', t:'냄새 — 싸는 법',
  x:`밤에 짐 둘레로 긁는 소리가 돌았다. 아침에 보니 봇짐 겉천에 발톱 자국이 나 있다.<br><br>
    뜯긴 건 없다. 아직은. 말린 고기 냄새가 천을 뚫고 새는 것이다.<br>
    여기 것들 코에 이 봇짐은 걸어 다니는 찬장이다.<br><br>
    행상은 냄새나는 물건을 싸는 법을 안다. 국경 초소를 지나 본 행상이라면 더 잘 안다.`,
  o:[
    { l:'① 기름천과 재로 겹겹이 싼다.', k:'sense', dc:24,
      ok:`먹을 것을 전부 꺼내 기름천에 말고, 잿가루를 먹인 겉천으로 한 번 더 쌌다. 매듭은 밀랍으로 먹였다.<br><br>그날 밤은 긁는 소리가 없었다. 다음 밤도.<br>사흘째 밤, 무엇이 짐 곁에 와서 한참 코를 박고 섰다가 그냥 갔다. 코앞에서 찬장이 사라진 것이다. 셈이 안 맞는 얼굴로 갔을 것이다.`,
      ng:`쌌는데 기름천 냄새가 새 냄새를 만들었다. 기름 냄새를 아는 것이 있었다.<br><br>밤중에 짐이 통째로 끌려가기 시작했다. 매달려서 끈을 끊고 먹을 것 반을 떼어 던졌다.<br>그것이 던진 쪽으로 가는 사이 나머지를 안고 뛰었다. 반값에 목숨을 샀다고 치기로 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 냄새를 아예 밖에 건다.', k:'luck', dc:25,
      ok:`거꾸로 갔다. 고기 한 줄을 일부러 꺼내 쉰내 나는 늪풀에 비벼 상한 냄새를 입혔다. 그걸 짐 맨 바깥에 걸었다.<br><br>성한 냄새는 그 밑에 묻혔다. 여기 것들은 상한 것을 안 먹는다. 병을 아는 것이다.<br>그날부터 짐 둘레가 조용했다. 간판을 바꿔 단 가게는 손님도 바뀐다.`,
      ng:`상한 냄새를 입혔는데, 상한 것만 먹는 것이 따로 있었다.<br><br>밤에 그것들이 왔다. 작고, 여럿이고, 이빨이 바늘 같았다.<br>걸어 둔 미끼째 한 귀퉁이를 뜯겼다. 쫓느라 불붙은 막대를 밤새 휘둘렀다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'갈림길 — 장삿길 고르기',
  x:`길이 셋으로 갈린다.<br><br>
    가운데 길은 넓고 반반하다. 짐승이 다져 놓은 길이다. 왼쪽은 좁고 가시가 많다. 오른쪽은 돌아서 멀다.<br>
    행상은 길을 값으로 본다. 빠른 길은 길세가 비싸다. 누가 받는지가 문제일 뿐.<br><br>
    장사 다니던 시절, 산적 나오는 지름길과 멀어도 빈 길 중에 뭘 골랐더라.`,
  o:[
    { l:'① 제일 험하고 수지 안 맞는 길을 간다.', k:'luck', dc:25, wake:1,
      ok:`왼쪽 가시밭을 골랐다. 지나다니는 것 입장에서 셈을 해 봤다. 품은 들고 먹을 건 없는 길. 장사가 안 되는 길목에는 목 지키는 놈도 없다.<br><br>가시에 옷이 뜯기며 반나절을 갔다. 짐승 흔적이 하나도 없는 반나절이었다.<br>길이 끝날 때쯤 가시덤불에 산나물이 숨어 자라고 있었다. 아무도 안 오는 길의 덤이다.<br><br>길의 값을 매기는 저울에 추가 하나 늘었다. 이문이 아니라 목숨으로 다는 추다.`,
      ng:`가시밭 중간에 뼈가 있었다. 가시를 뒤집어쓴 채 죽은 큰 짐승 뼈.<br><br>가시밭도 다 막지는 못한다는 뜻이다. 뼈를 넘는데 덤불 저쪽이 출렁했다.<br>엎드려서 가시째 기었다. 얼굴이고 손이고 성한 데가 없이 빠져나왔다.`,
      win:{ exp:24, dream:3, item:'산나물' }, lose:{ hp:-29, mind:-14 } },
    { l:'② 넓은 길을 짐승 시간 피해 간다.', k:'sense', dc:24,
      ok:`다져진 길바닥 똥 무더기를 쑤셨다. 속까지 식었다. 다닌 지 오래된 시간이다.<br><br>짐승 길에도 장날이 있다. 지금은 파장이다. 빠르게 질렀다.<br>길가에 발린 뼈들이 줄줄이 누워 있었다. 장날에 온 것들이다. 파장 손님은 구경만 하고 지나갔다.`,
      ng:`반쯤 질렀을 때 길 양쪽 수풀이 같은 박자로 흔들렸다. 장이 선 것이다.<br><br>짐을 추스를 새도 없이 뛰었다. 뒤에서 몰고 앞에서 기다리는 판을 옆으로 뚫었다.<br>구르고 미끄러지며 벼랑 틈에 끼어 반나절을 숨었다. 넓은 길값을 몸으로 치렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'허물 장터 — 값 매기기',
  x:`길바닥에 그것들이 벗어 놓고 간 것이 널렸다. 허물, 빠진 이빨, 부러진 발톱.<br><br>
    뭍 장에 내가면 한밑천 하고도 남을 물건들이다. 손이 근질거린다.<br>
    행상의 눈은 물건부터 감정한다. 이건 얼마, 저건 얼마.<br><br>
    그러다 멈췄다. 감정이란 건 원래 물건이 언제 적 것인지부터 보는 일이다.`,
  o:[
    { l:'① 제일 새것이 어느 것인지부터 본다.', k:'luck', dc:25,
      ok:`이빨 하나가 아직 뿌리에 피가 비친다. 오늘 것이다. 발톱 부러진 단면도 희다. 싸운 지 얼마 안 됐다.<br><br>여기는 버린 물건 자리가 아니라 방금 싸움 난 자리다. 이긴 쪽이 근처에서 숨을 고르고 있을 것이다.<br>제일 오래된 허물 한 장만 말아 쥐고 소리 없이 떴다. 새것은 임자가 가깝고, 헌것은 임자가 멀다. 감정의 기본이다.`,
      ng:`새것 헌것을 가리는데 허물 더미 밑에서 김이 올라왔다.<br><br>더미가 들썩였다. 싸움에 진 쪽이 그 밑에서 피를 식히고 있었던 것이다.<br>다친 짐승이 제일 사납다. 물건이고 뭐고 다 두고 뛰었다. 뒤에서 허물 더미가 통째로 일어서는 소리가 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 한 점도 안 줍고 지나간다.', k:'steady', dc:23,
      ok:`눈으로만 값을 매기고 손은 뒷짐을 졌다. 임자 모르는 물건은 외상보다 나쁘다.<br><br>지나고 나서 보니 길 끝 바위에 무엇이 앉아 이쪽을 내려다보고 있었다. 제 물건 자리를 지키는 눈이었다.<br>빈손을 봤는지 따라오지 않았다. 집은 게 없으면 물릴 것도 없다.`,
      ng:`지나는데 일행 하나가 발톱 하나를 몰래 주머니에 넣는 걸 못 봤다.<br><br>밤부터 무엇이 야영지 둘레를 돌기 시작했다. 꼭 한 자리, 그 사람 쪽에서 오래 머물렀다.<br>이튿날 주머니를 뒤져 발톱을 꺼내 길에 되놓고서야 도는 것이 그쳤다. 물건마다 임자 있다는 걸 다들 몸으로 배웠다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S', t:'쉬는 자리 — 외상 장부',
  x:`먹을 것이 줄어든다. 일행 눈이 자꾸 자루 쪽으로 간다.<br><br>
    굶주림은 셈을 망가뜨린다. 한 번에 다 먹자는 사람, 몰래 집는 사람이 나오기 시작한다.<br>
    행상은 외상 장부를 평생 썼다. 누가 얼마나 가져갔고 얼마나 남았는지.<br><br>
    장부가 분명하면 싸움이 없다. 장부가 흐리면 식구끼리도 돌아선다.`,
  o:[
    { l:'① 끼니를 달아서 나눠 준다.', k:'fix', dc:24,
      ok:`됫박 대신 손저울을 꺼냈다. 한 끼 몫을 저울로 달아 똑같이 나눴다. 남는 것은 모두 보는 데서 자루에 넣고 매듭 수를 셌다.<br><br>눈앞에서 공평하면 사람은 참는다. 자루 쪽을 흘끔대는 눈이 없어졌다.<br>마지막 날 저녁까지 매듭 수가 맞았다. 장부 덕에 식구가 식구로 남았다.`,
      ng:`달아서 나눴는데 한 명이 제 몫을 숨겨 두고 안 먹었다. 나중을 겁낸 것이다.<br><br>숨긴 몫 냄새가 밤에 손님을 불렀다. 그 사람 머리맡 흙이 파헤쳐지고 몫은 사라졌다.<br>굶은 채 겁만 산 셈이다. 다음부터는 먹는 것까지 보고서야 자리를 파했다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 제 몫을 먼저 반으로 줄인다.', k:'bond', dc:24,
      ok:`나누기 전에 제 몫부터 반을 덜어 자루에 도로 넣었다. 말은 안 했다. 다들 봤다.<br><br>그날부터 한 사람씩 제 몫을 조금씩 덜기 시작했다. 자루가 거꾸로 불었다.<br>행상은 안다. 셈은 시키면 어겨도 보이면 따라 한다. 제일 오래 가는 장부는 남의 눈이다.`,
      ng:`반을 덜었더니 기운이 먼저 달렸다. 짐을 진 채 두 번 휘청했다.<br><br>이쪽이 흔들리니 나누는 손을 아무도 안 믿게 됐다. 결국 자루를 통째로 열고 의논하는 데 한나절이 갔다.<br>덜어 낸 반 몫보다 비싼 한나절이었다.`,
      win:{ exp:17, dream:2, hp:6 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'저울 — 흔들리는 눈금',
  x:`쉬는 참에 손저울을 꺼내 소금을 달았다. 눈금이 안 선다.<br><br>
    바늘이 가늘게 떤다. 손을 바꿔도 떤다. 저울을 바닥에 놓아도 떤다.<br>
    삼십 년 쓴 저울이다. 저울이 떠는 게 아니라 바닥이 떠는 것이다.<br><br>
    멀리서 아주 무거운 것이 걷고 있다. 발소리는 아직 귀에 안 닿는데, 저울 눈에는 닿는다.`,
  o:[
    { l:'① 저울을 길잡이로 쓴다.', k:'luck', dc:25, wake:1,
      ok:`저울을 손바닥에 올리고 떨림을 쟀다. 이쪽으로 돌면 떨림이 굵어지고, 저쪽으로 돌면 가늘어진다.<br><br>가늘어지는 쪽으로만 길을 잡았다. 반나절을 그렇게 걸었다.<br>저녁에 떨림이 멎었다. 그 큰 것의 걸음 밖으로 나온 것이다. 소금 달던 저울이 목숨을 달았다.<br><br>물건의 무게만 달던 눈금으로 땅의 무게를 읽었다. 저울 하나로 보는 세상이 두 배로 넓어졌다.`,
      ng:`떨림이 가늘어지는 쪽으로 갔는데 갑자기 뚝 멎었다.<br><br>멎은 게 멀어진 게 아니었다. 그것이 걸음을 멈춘 것이다. 선 채로 듣고 있는 것이다.<br>한참을 같이 서 있었다. 다시 울림이 시작됐을 때, 이쪽으로 세 걸음 굵어졌다가 방향을 틀었다. 그 세 걸음 동안 아무도 숨을 안 쉬었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 짐을 내리고 울림이 지날 때까지 엎드린다.', k:'steady', dc:23,
      ok:`짐을 내리고 다들 바닥에 몸을 붙였다. 선 것보다 누운 것이 울림을 빨리 읽는다.<br><br>울림이 왼쪽에서 와서 앞을 질러 멀어졌다. 뼈로 들었다.<br>지나간 자리로는 안 가기로 했다. 지나간 길이 그것의 길이다. 장사꾼은 남의 가게 앞에 좌판을 안 편다.`,
      ng:`엎드렸는데 울림이 자꾸 굵어졌다. 이쪽으로 오는 길이었다.<br><br>짐을 둘러메고 옆으로 뛰었다. 늦게 일어난 만큼 급하게 뛰었다.<br>덤불에 처박혀 그것이 지나는 걸 봤다. 다리 하나가 떠 있던 자리를 디뎠다. 내려놓고 온 짐 절반이 그 발밑에 있었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'길가 — 동업자의 짐',
  x:`길 한가운데 봇짐이 하나 놓여 있다. 행상의 짐이다. 묶음새만 봐도 안다.<br><br>
    주인은 없다. 끌린 자국도, 핏자국도 없다. 짐만 반듯하게, 길 복판에.<br>
    삼십 년 길에서 별 험한 꼴을 다 봤지만 짐을 두고 사라진 행상은 못 봤다.<br><br>
    행상은 죽어도 짐 위에서 죽는다.`,
  o:[
    { l:'① 짐째 들어 올린다.', k:'luck', dc:25,
      doom:{ title:'놓인 자리', what:'짐을 문 줄에 감겨 끌려갑니다', dc:19, sec:45,
        text:`들었다. 가볍다. 행상 짐이 가벼운 법이 없는데.<br><br>속이 비어 있었다. 그리고 짐 밑바닥에 끈적한 줄이 달려 있었다. 줄이 손목에 감긴다. 길가 어둠에서 줄이 팽팽해진다.<br>끌려간다. 길 복판에 짐을 놓고 줄을 걸어 두는 사냥을 하는 것이다. 먼저 간 동업자가 이 미끼를 어떻게 마련해 줬는지, 끌려가면서 알고 싶지 않았다.<br><br>빈 짐이 왜 반듯하게 놓였는지부터 셈했어야 했다. 좌판은 늘 파는 쪽이 차린다.`,
        dieText:`길 한가운데 봇짐이 둘 놓여 있다.<br><br>둘 다 반듯하다. 하나는 묶음새가 낯익다.<br>지나가는 사람을 기다린다.` },
      ok:`들기 전에 끈으로 고리를 만들어 멀리서 당겼다. 짐이 반 뼘 끌리다가, 길가 덤불이 왈칵 쏠렸다.<br><br>짐 밑에 끈적한 줄이 달려 있었다. 줄 임자가 덤불에서 성을 냈다.<br>짐은 포기했다. 다만 당기면서 쏟아진 것들 중 바깥에 떨어진 소금 주머니 하나는 막대로 끌어 챙겼다. 동업자 유품이다. 소금은 썩지 않으니 오래 기억하게 된다.`,
      win:{ exp:23, dream:3, item:'소금 덩이' } },
    { l:'② 짐을 두고 조의만 표하고 간다.', k:'steady', dc:23,
      ok:`짐 앞에 잠깐 서서 고개를 숙였다. 손은 대지 않았다.<br><br>길에서 죽은 행상한테는 길에서 하는 인사가 따로 있다. 아무 말 없이 반 걸음 비켜 지나는 것이다. 좌판을 가리지 않게.<br>다 지나서 돌아보니 짐이 아까보다 길 가운데로 조금 더 나와 있었다. 손님이 뜸한 좌판처럼. 못 본 척했다.`,
      ng:`지나치는데 일행 하나가 짐을 발로 톡 건드렸다.<br><br>짐이 픽 쓰러지며 속에서 마른 뼈가 쏟아졌다. 작게 조각난 뼈. 그리고 길가 어둠에서 무엇이 벌떡 일어서는 기척.<br>해 지기까지 쫓겼다. 죽은 동업자가 마지막으로 가르쳐 준 것이다. 남의 좌판에 발 대지 마라.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, spirit:-17 } }
  ] },

{ at:'S', t:'밤손님 — 바꿔 가는 것',
  x:`아침마다 짐이 축난다. 바늘 한 쌈, 끈 한 타래, 어제는 숟가락.<br><br>
    대신 자리에 딴것이 놓여 있다. 반들반들한 돌, 작은 뼈, 오늘은 금 간 구슬.<br>
    도둑이 아니다. 도둑은 값을 안 치른다. 이건 바꿔 가는 것이다.<br><br>
    셈을 할 줄 아는 무엇이 밤마다 다녀간다.`,
  o:[
    { l:'① 좌판을 차려 준다.', k:'luck', dc:24, wake:1,
      ok:`잘 자리 옆에 천을 펴고 물건을 몇 점 벌여 놓았다. 바늘, 끈, 쓸모 잃은 단추. 값나가는 건 안 올렸다.<br><br>아침에 보니 단추와 끈이 사라지고 마른 민물고기 두 마리가 가지런히 놓여 있었다. 후한 값이다.<br>사흘을 그렇게 장사했다. 사흘째 밤, 야영지 쪽으로 오던 큰 기척이 좌판 앞에서 멈칫하더니 돌아갔다. 밤손님이 길을 막아 준 건지, 큰 것이 좌판을 꺼린 건지. 단골은 어느 장에서나 울타리가 된다.<br><br>사람 아닌 것과 셈을 트고 장사를 텄다. 장터가 어디까지인지 다시 배웠다.`,
      ng:`좌판에 값나가는 거울을 올린 게 실수였다.<br><br>아침에 거울은 없고, 값은 안 놓여 있었다. 그 밤부터 바꿔 가는 대신 그냥 가져가기 시작했다.<br>공짜 맛을 들인 손님은 최악의 손님이다. 좌판을 접고 짐을 품에 안고 잤다.`,
      win:{ exp:24, dream:3, item:'민물고기' }, lose:{ mind:-15, spirit:-20 } },
    { l:'② 밤손님을 따라가 본다.', k:'hide', dc:25,
      doom:{ title:'단골의 집', what:'밤손님의 굴로 끌려 들어갑니다', dc:19, sec:40,
        text:`새벽녘에 짐 곁을 떠나는 작은 기척을 따라붙었다. 단골이 어디 사는지는 알아 둬야 한다.<br><br>바위 틈 굴 앞에서 그것이 돌아봤다. 놀라지도 않았다. 처음부터 알고 있던 걸음이었다.<br>굴 안에서 큰 손이 나와 발목을 감았다. 작은 것은 구경만 한다. 바꿔 가던 건 새끼고, 값을 치르던 건 어미였던 것이다. 굴속으로 끌려 들어가며 셈이 맞았다. 어미 쪽 장부에는 이쪽이 물건이었다.<br><br>단골의 집까지 쫓아가는 장사꾼은 없다. 기본을 잊었다.`,
        dieText:`아침 짐자리에 반들반들한 돌이 하나 놓여 있다.<br><br>어제까지 것보다 크고, 반듯하다.<br>후하게 쳐 준 값이다.` },
      ok:`멀찍이 따라가다 바위 틈 앞에서 멈췄다. 굴 어귀에 뼈가 쌓여 있었다. 큰 뼈.<br><br>작은 것 뒤에 큰 것이 산다. 거기까지만 보고 돌아섰다.<br>단골의 사정은 아는 데까지만 안다. 그게 오래 가는 거래의 요령이다. 다음 날부터 좌판 물건을 조금 더 후하게 얹었다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'핏방울 — 흘리는 장사',
  x:`일행 하나가 다쳤다. 걸을 수는 있는데 붕대 밑으로 피가 밴다.<br><br>
    걸음마다 한 방울씩. 바닥에 점선이 찍힌다.<br>
    행상은 안다. 길에 물건을 흘리고 다니는 장사꾼의 끝을. 흘린 물건에는 줍는 손이 따라붙는다.<br><br>
    여기서 피는 제일 비싼 물목이다. 그리고 지금 공짜로 뿌리며 가고 있다.`,
  o:[
    { l:'① 흘린 길을 거꾸로 꾸민다.', k:'luck', dc:25,
      ok:`붕대를 갈아 지혈부터 단단히 했다. 그리고 걷어 낸 헌 붕대를 들고 왔던 길을 백 걸음 되짚으며 샛길 쪽에 점점이 눌러 찍었다.<br><br>흘린 상품의 길을 딴 데로 그려 준 것이다. 진짜 길은 재를 뿌리며 걸었다.<br>밤에 샛길 쪽에서 무엇이 오래 서성이는 소리가 났다. 점선 끝 빈 덤불 앞에서. 재고 없는 가게 앞에 줄 세운 셈이다.`,
      ng:`헌 붕대로 가짜 길을 그리는데 코 밝은 것은 안 속았다.<br><br>새 피와 식은 피를 가리는 코였다. 진짜 점선을 따라 밤에 들이닥쳤다.<br>불붙은 장작을 던지며 물러났다. 다친 사람을 업고 뛰느라 등이 피로 다 젖었다. 이제 점선이 두 사람 몫이 됐다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 피를 소금으로 덮는다.', k:'heal', dc:24,
      ok:`상처를 씻고 소금을 아껴 치지 않았다. 피가 멎고 냄새가 죽었다.<br><br>지나온 핏자국에도 한 자밤씩 소금을 쳤다. 소금 먹은 피는 코에 다르게 읽힌다. 산 것 냄새가 아니라 절인 것 냄새다.<br>절인 것을 쫓는 코는 없다. 비싼 소금이 제값을 했다.`,
      ng:`소금을 치는데 상처가 소금에 놀라 그 사람이 소리를 질렀다.<br><br>짧은 비명 하나가 소금 한 자루보다 멀리 갔다.<br>그날은 길을 반만 가고 일찍 자리를 접었다. 번갈아 눈을 뜨고 밤을 났다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ mind:-16, spirit:-19 } }
  ] },

{ at:'S', t:'짐 — 무게가 늘었다',
  x:`아침에 봇짐을 메는데 등이 먼저 알았다. 무겁다.<br><br>
    행상은 제 짐 무게를 돈냥까지 안다. 어제보다 분명히 늘었다. 그런데 꾸러미 수는 그대로다.<br>
    밤새 뭐가 들어왔다는 소리다. 제 발로.<br><br>
    짐 속 어딘가에서, 아주 천천히, 무엇이 숨 쉬는 간격으로 부피가 변하고 있다.`,
  o:[
    { l:'① 무게로 자리를 짚어 낸다.', k:'luck', dc:25, wake:1,
      ok:`짐을 안 열었다. 대신 꾸러미째 하나씩 손바닥에 달아 봤다. 삼십 년 단 손이다. 소금 꾸러미가 두 냥 무겁다.<br><br>그 꾸러미만 막대 두 개로 집어 바위 위에 올리고 멀찍이서 끌러 봤다. 주먹만 한 것이 소금 속에 파고들어 있었다. 알인지 새끼인지. 소금에 반쯤 절어 꿈틀댔다.<br>꾸러미째 길 밖에 두고 떠났다. 소금 한 근 값에 큰 우환을 떨었으면 헐값이다.<br><br>눈 감고도 저울이 되는 손. 삼십 년 장사가 몸에 새긴 눈금이 목숨 보는 눈금이 됐다.`,
      ng:`무게를 짚는 손이 두 번 틀렸다. 조급하면 손눈금도 흐려진다.<br><br>세 번째 꾸러미를 여는 순간 안에서 그것이 튀었다. 손등을 긁고 어둠으로 사라졌다.<br>긁힌 자리가 밤새 욱신댔다. 짐을 다 쏟아 백 번을 턴 다음에야 다시 쌌다. 반나절이 들었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 짐을 통째로 물에 담근다.', k:'sense', dc:24,
      ok:`근처 웅덩이에 짐을 통째로 반쯤 담갔다. 숨 쉬는 것은 물을 싫어한다.<br><br>소금 꾸러미 쪽에서 거품이 올라오더니 주먹만 한 것이 튀어나와 달아났다.<br>젖은 건 소금 반 근과 끈 몇 타래. 널어 말리면 그만이다. 산 것만 골라 내쫓는 데 물만 한 게 없다.`,
      ng:`담갔는데 나온 게 하나가 아니었다. 셋이 각각 다른 꾸러미에서 튀어나왔다.<br><br>밤새 짐이 여인숙 노릇을 한 것이다. 그중 하나가 달아나며 발등을 물었다.<br>물린 자리를 소금물로 씻었다. 짐은 한나절 말려야 했고, 그 한나절 동안 자꾸 뒤를 돌아봤다. 어미가 찾으러 올까 봐.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'표본 선반 — 값나가는 병',
  x:`표본실 선반에 성한 병이 몇 남았다. 속에 잠긴 것들이 등불에 흐늘흐늘 비친다.<br><br>
    뭍에서라면 부르는 게 값일 물건이다. 학자들은 이런 데 재산을 턴다.<br>
    제일 큰 병은 선반 안쪽 깊숙이 있다. 유리도 두껍고 마개도 성하다.<br><br>
    행상 평생 이만한 물건을 그냥 지나친 적이 없다.`,
  o:[
    { l:'① 선반 안쪽으로 팔을 뻗는다.', k:'luck', dc:26,
      doom:{ title:'선반 안쪽', what:'선반 뒤의 것에게 팔을 잡혀 끌려 들어갑니다', dc:20, sec:40,
        text:`팔을 어깨까지 넣어 병목을 잡았다. 잡히는 순간 알았다. 병이 따뜻하다.<br><br>병 뒤에서 긴 손가락들이 이쪽 손목을 마주 잡았다. 선반 뒤가 벽이 아니었다. 뚫려 있고, 거기 사는 것이 있다.<br>선반째 끌려 들어간다. 병들이 줄줄이 넘어지며 깨진다. 제일 비싼 물건 곁에는 꼭 그걸 지키는 손이 있다. 뭍이나 여기나.<br><br>물건값만 셈하고 자릿세를 안 셈했다. 장사 밑천 다 까먹는 셈법이다.`,
        dieText:`표본 선반 안쪽, 제일 큰 병이 비어 있다.<br><br>아니, 비어 있지 않다. 새로 채워졌다.<br>마개가 안쪽에서 닫혔다.` },
      ok:`팔을 넣다 말고 멈췄다. 병 둘레 먼지가 닦여 있었다. 누가 자주 만지는 물건이라는 뜻이다.<br><br>여기서 병을 만질 사람은 없다. 사람은.<br>팔을 소리 없이 빼고 선반에서 물러났다. 물러난 자리에서 보니 선반 뒤 어둠에 숨구멍 같은 틈이 나 있었다. 먼지 없는 물건은 장물이다. 안 사는 게 맞다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 앞줄의 작은 병 하나만 고른다.', k:'sense', dc:24,
      ok:`손 닿는 앞줄에서 제일 작고 마개 단단한 병 하나만 골랐다. 속엔 엄지만 한 것이 잠겨 있다.<br><br>천에 싸고 또 싸서 짐 한가운데 넣었다. 깨지면 값이 아니라 빚이 되는 물건이다.<br>선반을 뜨며 큰 병들을 한 번 돌아봤다. 큰 이문은 큰 험을 끼고 있다. 작은 이문이 집까지 간다.`,
      ng:`집어 든 병 마개가 삭아 있었다. 손안에서 바스러지며 속엣것이 쏟아졌다.<br><br>엄지만 한 것이 바닥에서 꿈틀하더니 뛰었다. 죽은 게 아니었다. 절여진 채 잠든 것이었다.<br>튄 국물이 소매를 태웠다. 병값은커녕 옷값만 나갔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S1', t:'에어록 — 통행세',
  x:`에어록 문이 반뼘 열리다 만다. 홈에 뭐가 끼어 톱니가 헛돈다.<br><br>
    문틈 너머가 나가는 길이다. 톱니를 돌리려면 홈에 끼울 단단한 것이 필요하다.<br>
    짐을 뒤졌다. 놋숟가락 한 벌, 쇠자, 저울추.<br><br>
    길목마다 길세가 있다. 여기 길세는 쇠붙이로 받는 모양이다.`,
  o:[
    { l:'① 저울추를 끼워 돌린다.', k:'luck', dc:25, wake:1,
      ok:`저울추를 홈에 물렸다. 삼십 년 손때 묻은 추다. 톱니가 추를 씹으며 돌았다. 문이 열렸다.<br><br>추는 톱니 속에서 으스러졌다. 문이 열린 채 멎었다.<br>일행이 다 지나고 마지막으로 문을 봤다. 으깨진 추가 톱니 사이에 박혀 문을 잡고 있었다. 저울추가 마지막으로 단 것이 다섯 목숨이다. 수지가 맞아도 한참 맞는다.<br><br>아까운 것부터 내는 길세가 제일 싼 길세라는 걸 손이 배웠다. 셈이 빨라지니 아까움이 짧아진다.`,
      ng:`놋숟가락부터 아껴 끼운 게 잘못이었다. 톱니가 숟가락을 씹어 삼키고 도로 멎었다.<br><br>쇠자도 먹혔다. 결국 저울추까지 들어갔다. 문은 세 번째에야 열렸다.<br>문 너머에서 쇠 씹히는 소리를 다 듣고 있던 것이 있었다. 복도 끝에서 마주쳤다. 등짐이 반쯤 가벼워질 때까지 쫓겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 문을 수동 크랭크로 연다.', k:'break', dc:24,
      ok:`문 옆 덮개를 뜯으니 수동 크랭크가 나왔다. 녹이 슬었지만 돈다.<br><br>둘이 붙어 돌렸다. 문이 한 뼘씩 울며 열렸다. 소리가 컸다. 그래서 빨리 돌렸다.<br>다 지나고 크랭크를 반대로 돌려 문을 닫았다. 열어 준 길은 닫고 가는 게 길에 대한 예의다. 뒤따라오던 기척이 문에 막혀 긁는 소리를 냈다.`,
      ng:`크랭크가 반 바퀴 돌고 부러졌다. 녹이 속까지 먹어 있었다.<br><br>반뼘 열린 문틈으로 짐을 먼저 밀어 넣고 몸을 우겨 넣었다. 마지막 사람 외투가 찢겼다.<br>문틈에 낀 외투 자락이 밤새 바람에 펄럭였다. 누가 봐도 여기로 지나갔다는 표식이다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, spirit:-17 } }
  ] },

{ at:'S1', t:'녹은 자국 — 저울추 셈',
  x:`복도 바닥에 녹은 구멍이 점점이 나 있다. 그것들 피가 떨어진 자국이다.<br><br>
    자국이 아직 김을 올리는 데도 있다. 싸움이 가깝다는 뜻이다.<br>
    어느 쪽이 오래된 자국이고 어느 쪽이 새것인지. 눈으로는 다 똑같이 검다.<br><br>
    행상 주머니에 못 쓰는 엽전이 한 줌 있다. 셈은 몸에 배어 있다.`,
  o:[
    { l:'① 엽전을 던져 자국의 나이를 잰다.', k:'luck', dc:25,
      ok:`자국마다 엽전을 하나씩 던져 넣었다. 치익 소리가 나면 아직 산 자국, 조용하면 식은 자국.<br><br>치익 소리 나는 자국들이 한 방향으로 줄을 그었다. 그쪽이 싸움이 번지는 쪽이다.<br>식은 자국 쪽으로 길을 잡았다. 엽전 열두 닢으로 산 길이다. 이 동네 시세로는 거저다.`,
      ng:`엽전이 자국에 빠지며 생각보다 큰 소리를 냈다. 쨍그랑.<br><br>복도 저쪽에서 싸우던 소리가 뚝 그쳤다. 둘 다 이쪽을 듣는 정적이었다.<br>식은 자국이고 뭐고 왔던 길로 물러났다. 싸움 구경값은 원래 비싸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-21 } },
    { l:'② 녹다 만 쇠문짝을 방패로 쓴다.', k:'steady', dc:24,
      ok:`반쯤 녹은 쇠문짝이 벽에 기대 있었다. 성한 쪽을 골라 둘이 맞들었다.<br><br>김 오르는 구간을 문짝을 머리에 이고 건넜다. 위에서 두 방울이 떨어져 문짝에서 끓었다.<br>건너편에 문짝을 세워 두고 갔다. 다음 지나는 사람 몫이다. 길에 두고 가는 물건이 제일 남는 장사일 때가 있다.`,
      ng:`문짝의 녹은 쪽이 생각보다 깊었다. 들고 가는 중에 반으로 접혔다.<br><br>떨어지는 반쪽을 피하다 일행끼리 엉켰다. 넘어진 자리 옆이 김 오르는 자국이었다.<br>소매 끝이 자국에 닿아 타들어 갔다. 소매를 찢어 던지고 건넜다. 왼팔이 허전했다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'통풍구 — 길목 표식',
  x:`천장 통풍구 입구마다 긁힌 자국이 있다. 처음엔 발톱 자국인 줄 알았다.<br><br>
    아니다. 너무 가지런하다. 세 줄, 두 줄, 다섯 줄. 갈림마다 수가 다르다.<br>
    그것이 제 길에 단 표식이다. 장삿길 어귀마다 돌무더기 쌓는 행상들처럼.<br><br>
    표식을 다는 짐승은 길을 두고 다니는 짐승이다. 길이 있으면 시간표도 있다.`,
  o:[
    { l:'① 표식 수가 큰 길목을 피해 걷는다.', k:'sense', dc:24,
      ok:`다섯 줄 표식 밑은 큰길, 두 줄은 샛길이라고 셈을 세웠다. 큰길 밑을 피하고 샛길 밑으로만 걸었다.<br><br>맞는 셈이었다. 반나절 내내 머리 위 끌리는 소리는 늘 다섯 줄 쪽에서만 났다.<br>남의 길 표식을 읽을 줄 알면 남의 길을 피할 수 있다. 장돌뱅이 서로 간에 하던 일이다.`,
      ng:`샛길 밑을 걷는데 머리 위에서 소리가 났다. 표식이 낡은 것이었다.<br><br>길이 바뀐 지 오래인 것이다. 낡은 지도로 걷다가 장마당 복판에 선 꼴이다.<br>격자 하나가 덜컹이는 밑을 전력으로 빠져나왔다. 등 뒤 격자가 떨어져 바닥을 쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 표식에 줄을 하나 보탠다.', k:'luck', dc:25,
      ok:`두 줄 표식에 쇠자로 세 줄을 보태 다섯 줄로 만들었다. 샛길을 큰길로 바꿔 적은 것이다.<br><br>그것이 제 표식을 믿고 샛길로 다니기 시작했다. 진짜 큰길이 비었다.<br>빈 큰길 밑으로 이틀을 다녔다. 남의 장부에 숫자 하나 보태서 길을 통째로 세낸 셈이다.`,
      ng:`줄을 긋는 소리가 관을 타고 올라갔다. 긁는 소리는 저들 말이다. 모르는 말로 지껄인 셈이다.<br><br>머리 위가 사방에서 시끄러워졌다. 표식마다 돌아다니며 다시 긁는 소리가 밤새 났다.<br>장부를 건드린 건 들켰는데 누가 건드렸는지는 안 들킨 것 같았다. 그래도 이틀은 통풍구 없는 길로만 돌았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-20 } }
  ] },

{ at:'S1', t:'생존자 — 맞바꿀 것',
  x:`창고 문틈에서 사람이 손짓한다. 눈이 퀭한 생존자다.<br><br>
    문 너머 선반에 먹을 것이 보인다. 통조림, 밀봉된 상자. 그가 말한다. 먹을 것을 나눠 줄 테니 데리고 나가 달라고.<br>
    그런데 그는 문을 안 연다. 틈으로만 말한다. 품에 안은 자루를 꼭 끌어안고.<br><br>
    행상은 거래 전에 상대부터 본다. 물건보다 사람이 먼저다.`,
  o:[
    { l:'① 문틈으로 먼저 소거래를 튼다.', k:'luck', dc:25, wake:1,
      ok:`큰 약조 전에 작은 거래부터 했다. 문틈으로 마른 고기 한 점을 넣고 물 한 통을 받았다.<br><br>그가 고기를 받자마자 제 입에 넣었다. 허겁지겁. 씹고, 삼키고, 운다.<br>됐다. 제 입에 먹을 걸 넣는 사람은 아직 사람이다. 문을 열게 하고 같이 나왔다. 그가 안은 자루에는 죽은 동료의 신분패가 가득했다. 그것만은 못 놓겠다고 했다. 그 짐은 안 덜게 했다.<br><br>물건 보는 눈으로 평생을 살았는데, 거래 한 번으로 사람 속을 다는 저울이 손에 들어왔다.`,
      ng:`고기를 넣어 줬는데 그가 그걸 안 먹고 자루에 넣었다.<br><br>자루가 움직였다. 안에서 무엇이 받아먹는 소리가 났다.<br>문틈에서 물러났다. 그가 울면서 문을 긁었다. 거래는 깨졌다. 그날 밤 창고 쪽에서 문 열리는 소리가 났고, 다시는 손짓하는 사람을 못 봤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 조건 없이 문을 연다.', k:'bond', dc:24,
      ok:`지렛대로 문을 땄다. 그가 주저앉아 울었다. 사흘을 갇혀 있었다고 했다.<br><br>선반의 먹을 것을 같이 나눠 쌌다. 밀봉된 상자에서 말린 고기가 한 묶음 나왔다.<br>그는 길눈이 밝았다. 순찰 도는 것의 시간을 외우고 있었다. 갇혀서 사흘 내내 들은 것이다. 공짜로 연 문에서 제일 비싼 물건이 나왔다.`,
      ng:`문을 따는 소리가 복도에 울렸다. 그가 비명처럼 속삭였다. "온다!"<br><br>창고 안으로 다 같이 들어가 문을 도로 닫았다. 무엇이 문 앞을 서성이다 갔다.<br>한 식경을 갇혀 있다 나왔다. 구하러 왔다가 같이 갇힌 꼴이다. 그는 그 와중에도 이쪽 소매를 꼭 잡고 있었다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 자루 속부터 검사한다 — 바짝 다가서서.', k:'gaze', dc:25,
      doom:{ title:'자루 속', what:'자루에서 나온 것에게 감겨 끌려갑니다', dc:19, sec:40,
        text:`문틈에 바짝 붙어 자루를 열어 보라고 했다. 그가 떨며 자루를 틈에 댔다.<br><br>자루 주둥이가 틈에 닿는 순간 안엣것이 튀었다. 문틈이 좁아 사람은 못 지나도 그것은 지난다.<br>목에 감긴다. 차고 미끈하다. 문틈 안쪽으로 당긴다. 생존자가 비명을 지르며 미안하다고, 미안하다고 운다. 그는 그것의 손이 아니라 그것의 미끼였다. 제일 안 좋은 쪽으로.<br><br>검품은 거리가 생명이다. 초짜 때 배운 걸 급해서 잊었다.`,
        dieText:`창고 문틈으로 퀭한 눈이 내다본다.<br><br>살려 달라고, 데리고 나가 달라고 한다.<br>품에 안은 자루가 숨 쉬듯 부푼다.` },
      ok:`자루를 열라고 하되, 문틈에서 세 걸음 물러서서 막대 끝으로 자루를 벌렸다.<br><br>안에는 신분패 무더기뿐이었다. 죽은 동료들 것. 그가 떨면서 말했다. 두고 갈 수가 없었다고.<br>세 걸음의 값은 안 치러도 됐지만, 치를 뻔한 상황은 맞았다. 검품 거리는 상대가 누구든 지킨다. 문을 열고 그를 받았다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'깊은 방 어귀 — 제일 비싼 광',
  x:`아래로 내려가는 어귀 벽이 수지 같은 것으로 덮여 있다. 그 속에 물건들이 박혀 있다.<br><br>
    배낭, 장비, 쇠붙이, 금니까지. 먼저 온 사람들의 전 재산이 벽 한 면에 진열돼 있다.<br>
    행상 평생 이렇게 큰 광은 처음 본다.<br><br>
    광이 크면 광 주인도 크다. 어귀 안쪽에서 젖은 바람이 천천히 드나든다. 숨처럼.`,
  o:[
    { l:'① 벽에서 하나만 빼 본다.', k:'break', dc:26,
      doom:{ title:'광 주인', what:'수지 벽에 붙들려 안쪽으로 끌려갑니다', dc:20, sec:40,
        text:`제일 느슨해 보이는 배낭 하나를 당겼다. 수지가 엿처럼 늘어나며 따라왔다.<br><br>그리고 손이 안 떨어졌다. 수지가 손에서 팔로 기어 올라온다. 벽이 통째로 이쪽을 안는다.<br>안쪽 어둠에서 큰 것이 움직이는 소리가 났다. 광 주인이 재고 정리를 하러 온다. 벽째, 안쪽으로, 천천히 끌려 들어간다.<br><br>진열된 물건에 값표가 없으면 파는 물건이 아니다. 그 기본을 어겼다.`,
        dieText:`어귀 벽 진열이 한 점 늘었다.<br><br>봇짐째, 가지런히.<br>수지가 아직 마르지 않아 등불을 받아 번들거린다.` },
      ok:`당기다 말았다. 수지가 손가락에 닿는 순간 끈기가 심상치 않았다.<br><br>막대로 바꿔 당기니 막대가 통째로 벽에 붙어 버렸다. 손이었으면 손이 저랬다.<br>막대는 광에 기부했다. 광 구경값이다. 물러나며 보니 벽의 물건들이 다 당긴 자세로 굳어 있었다. 다들 마지막에 뭘 쥐려고 했던 것이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 광을 안 보고 지나간다.', k:'luck', dc:25, wake:1,
      ok:`눈을 광에서 떼고 발밑만 보며 어귀를 질렀다. 금니가 등불에 번쩍여도 안 봤다.<br><br>행상이 제일 늦게 배우는 기술이다. 안 사는 눈. 좋은 물건 앞에서 눈이 머물면 발도 머문다. 발이 머물면 여기서는 끝이다.<br>다 지나서 일행을 세어 보니 하나가 모자랐다. 금니 앞에 서 있었다. 소리 안 나게 돌아가 소매를 끌었다. 눈이 풀려 있었다. 광이 손님을 고르는 중이었던 것이다.<br><br>탐나는 것 앞에서 눈을 거두는 데 삼십 년이 걸렸다. 오늘 그 눈이 사람을 하나 건졌다.`,
      ng:`안 보고 걷는데 발이 수지 웅덩이를 밟았다. 바닥에도 깔려 있었던 것이다.<br><br>신발이 붙었다. 끈을 끊고 맨발을 뺐다. 신발은 광 바닥 진열품이 됐다.<br>절뚝이며 어귀를 빠져나왔다. 안쪽 숨소리가 한 박자 빨라진 것 같았다. 신발만으로 끝난 게 수지맞은 셈이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'냉동고 — 얼음 창고',
  x:`냉동고가 아직 돌아간다. 어디서 힘을 받는지 성에가 하얗다.<br><br>
    갈고리에 고깃덩이가 줄줄이 걸려 있다. 연구소 사람들 식량이었을 것이다.<br>
    문은 하나. 안은 좁고, 입김이 바로 언다.<br><br>
    그리고 성에 낀 바닥에 발자국이 있다. 사람 것이 아니고, 안쪽으로만 나 있다.`,
  o:[
    { l:'① 바깥쪽 갈고리만 빠르게 턴다.', k:'luck', dc:25,
      ok:`문을 연 채 고정하고, 문에서 손 닿는 갈고리 두 개만 쳤다. 안쪽 깊은 데는 눈도 안 줬다.<br><br>얼어서 돌덩이 같은 고기 두 덩이. 자루에 받는 데 스무 숨.<br>스물한 숨째에 안쪽 성에 더미가 부스럭했다. 문을 놓고 물러났다. 문이 닫히며 안쪽 소리도 닫혔다. 빠른 손이 밑천인 건 장이나 여기나 같다.`,
      ng:`고기가 갈고리에 얼어붙어 있었다. 당기는 사이 안쪽 성에가 일어섰다.<br><br>하얗게 성에를 뒤집어쓴 것이 갈고리 사이로 걸어 나왔다. 추위에 느렸다. 그게 전부였다.<br>고기 한 덩이만 안고 구르듯 나왔다. 문이 닫히기 직전까지 하얀 손가락이 따라 나왔다.`,
      win:{ exp:22, dream:3, item:'짐승 고기' }, lose:{ hp:-27, mind:-16 } },
    { l:'② 문을 괴고 안을 끝까지 확인부터 한다.', k:'sense', dc:24,
      ok:`쇠막대로 문을 괴고 등불로 안을 구석까지 비췄다. 안쪽 발자국은 성에 더미 뒤에서 끊겼고, 더미는 숨을 쉬고 있었다. 느리게.<br><br>자는 것이다. 추위가 재운 것이다.<br>깨지 않을 만큼만 바깥 고기를 내리고 소리 없이 닫았다. 재고 확인 먼저, 거래는 다음. 순서가 목숨을 지켰다.`,
      ng:`등불 열기가 실수였다. 가까운 성에가 녹으며 물방울이 똑, 소리를 냈다.<br><br>더미의 숨이 바뀌었다. 깨는 숨이다.<br>고기고 뭐고 문부터 닫고 쇠막대를 빗장에 질렀다. 안에서 문을 미는 힘에 복도까지 울렸다. 빈손에 식은땀만 벌었다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S2', t:'울타리 문 — 흥정',
  x:`울타리 문을 지나야 한다. 문 너머 풀숲에 그것들이 있다. 셋. 나란히 앉아 기다린다.<br><br>
    쫓아올 수 있는데 안 온다. 문이 열리기를 기다리는 것이다. 목 좋은 자리를 아는 것들이다.<br>
    짐에 말린 고기가 석 줄 남았다.<br><br>
    행상은 흥정으로 평생을 살았다. 흥정의 첫 법칙. 가진 걸 다 보이지 마라.`,
  o:[
    { l:'① 한 줄씩, 멀리, 세 번에 나눠 던진다.', k:'luck', dc:25, wake:1,
      ok:`첫 줄을 왼쪽 멀리 던졌다. 하나가 떴다. 둘째 줄은 더 멀리. 둘째가 떴다.<br><br>셋째 줄은 던지는 시늉만 했다. 남은 하나가 시늉을 따라 고개를 돌린 사이 문을 지나 잠갔다.<br>고기 두 줄로 문 하나를 샀다. 셋째 줄은 도로 짐에 들어갔다. 흥정 끝에 한 줄 남으면 그 장사는 이긴 장사다.<br><br>말이 안 통하는 상대와 값을 주고받았다. 흥정이 혀가 아니라 셈으로 하는 일이라는 걸 여기서 다시 배웠다.`,
      ng:`첫 줄을 너무 가까이 던졌다. 하나가 고기를 물고 제자리로 돌아왔다.<br><br>가까운 미끼는 자리를 안 바꾼다. 둘째 줄도, 셋째 줄도 그 자리 간식이 됐다.<br>빈손이 되자 그것들이 일어섰다. 문이 아니라 울타리 무너진 데로 돌아서 한참을 뛰었다. 공짜로 먹인 손님은 가게를 안 떠난다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 문 말고 바람 아래 개구멍으로 돈다.', k:'hide', dc:24,
      ok:`문은 저쪽 눈이 박힌 데다. 울타리를 따라 바람 아래로 돌았다. 관리인들이 쓰던 쪽문이 덤불에 묻혀 있었다.<br><br>기어서 지났다. 그것들은 아직 큰 문만 보고 앉아 있었다.<br>목 좋은 자리의 약점은 목만 지킨다는 것이다. 뒷골목은 언제나 행상 몫이다.`,
      ng:`쪽문이 녹슬어 안 열렸다. 비집는 소리에 셋 중 하나가 고개를 돌렸다.<br><br>남은 둘이 문을 지키는 사이 하나가 울타리를 따라왔다.<br>쪽문을 억지로 비틀어 빠졌다. 마지막 사람 뒤꿈치를 이빨이 스쳤다. 신발 뒤축이 한 입 뜯겨 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'물 양치밭 — 멜빵',
  x:`물에 잠긴 양치밭을 건너야 한다. 가슴까지 온다.<br><br>
    봇짐을 머리에 이면 두 손이 묶이고, 등에 지면 물을 먹어 천근이 된다.<br>
    물밑에서 가끔 긴 것이 종아리를 스치고 간다. 풀인지 아닌지.<br><br>
    행상과 짐은 한 몸이다. 한 몸인 게 늘 좋은 것만은 아니다.`,
  o:[
    { l:'① 멜빵을 미리 끊어 쥐고 건넌다.', k:'luck', dc:25,
      doom:{ title:'물밑 임자', what:'짐을 문 것에게 멜빵째 끌려 가라앉습니다', dc:20, sec:40,
        text:`멜빵을 어깨에 걸고 반쯤 건넜을 때 짐이 뒤에서 홱 당겨졌다.<br><br>물밑 것이 짐을 물었다. 끊어 쥔 멜빵이 손에 감겨 있었다. 쥔 손이 안 펴진다. 삼십 년 짐을 놓지 않던 손이다. 손이 먼저 거부한다.<br>짐과 함께 끌려 들어간다. 양치잎이 머리 위에서 닫히고, 녹색 물빛이 깜깜해질 때까지 손은 멜빵을 쥐고 있었다.<br><br>짐과 한 몸인 행상의 끝은 둘 중 하나다. 짐 위에서 죽거나, 짐 밑에서 죽거나.`,
        dieText:`양치밭 수면에 봇짐이 하나 떠올랐다 가라앉는다.<br><br>세 번 떠오르고 안 올라온다.<br>멜빵이 물밑으로 팽팽하다.` },
      ok:`건너기 전에 멜빵을 칼로 반쯤 켜 두었다. 당겨지면 끊어지게.<br><br>복판에서 짐이 물렸다. 멜빵이 설계대로 끊어졌다. 몸이 풀려났다.<br>짐은 세 번 떠올랐다 가라앉았다. 뭍에 올라 빈 어깨를 한참 내려다봤다. 삼십 년 만에 처음으로, 몸이 짐보다 비쌌다. 그게 맞는 셈이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 갈대 뗏목에 짐만 띄워 민다.', k:'fix', dc:24,
      ok:`마른 양치 줄기와 갈대를 걷어 작은 뗏목을 얽었다. 짐만 올리고 끈으로 끌며 건넜다.<br><br>물밑 것이 한 번 뗏목을 쳤다. 뗏목은 출렁하고 말았다. 문 데가 없으니 물 것도 없다.<br>건너편에서 짐은 보송했다. 젖은 건 사람뿐이다. 사람은 마른다.`,
      ng:`뗏목이 복판에서 풀렸다. 급하게 얽은 매듭이 물을 먹고 늘어난 것이다.<br><br>흩어지는 꾸러미를 허우적대며 건졌다. 소금 반, 기름천 하나는 가라앉았다.<br>물밑에서 긴 것이 다리를 두 번 스쳤다. 세 번째 전에 뭍에 닿았다. 잃은 물목을 셈하는 건 다 마르고 나서 했다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'큰 것의 길 — 한길',
  x:`숲을 가로질러 큰 것의 길이 나 있다. 나무가 양쪽으로 부러져 눕고 바닥이 다져진, 넓은 한길.<br><br>
    잔것들 흔적이 길 양옆까지만 있다. 아무것도 그 길을 안 밟는다. 사냥하는 것들도.<br>
    임자 무서운 줄 아는 것이다.<br><br>
    행상은 평생 큰길과 샛길을 저울질했다. 제일 무서운 임자의 길이 제일 빈 길이다.`,
  o:[
    { l:'① 한길을 당당히 걷는다 — 울림에 귀를 걸고.', k:'luck', dc:25, wake:1,
      ok:`한길 복판으로 걸었다. 빠르게, 그러나 발바닥은 늘 땅울림에 걸어 두고.<br><br>반나절 거리를 한나절에 질렀다. 양옆 수풀에서 눈들이 따라왔지만 길로는 안 들어왔다.<br>울림이 오기 시작했을 때 길을 벗어나 바위 뒤에 들었다. 그것이 제 길로 지나갔다. 세 든 가게는 주인 올 때 비켜 주면 된다.<br><br>제일 무서운 이름을 지붕으로 쓰는 법. 길세는 눈치, 그 셈이 몸에 붙었다.`,
      ng:`한길 복판에서 울림이 왔다. 생각보다 빨랐다. 그것의 걸음은 울림보다 늦게 오지 않는다.<br><br>수풀로 뛰어드는데 양옆에서 기다리던 눈들과 부딪쳤다. 길 밖은 저들 구역이다.<br>이빨과 발톱 사이를 구르며 도로 한길로 나왔다. 그것이 오는 쪽만 피해 길을 거슬러 뛰었다. 짐이 반이 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 한길과 나란한 수풀 가로 걷는다.', k:'sense', dc:24,
      ok:`한길에서 열 걸음 떨어진 수풀 가를 나란히 걸었다. 길의 덕은 보고 길의 임자는 피하는 거리다.<br><br>잔것들은 한길 가까이 오지 않았고, 큰 것이 지날 때는 열 걸음이면 수풀에 눕기 충분했다.<br>장사 서른 해의 요령이 다 그렇다. 붙지도 말고 떨어지지도 말 것.`,
      ng:`열 걸음이 모자랐다. 큰 것이 길을 벗어나 수풀로 목을 디밀었다. 길가 열매를 훑는 것이었다.<br><br>엎드린 머리 위로 그 목이 지나갔다. 집채만 한 그림자가 숨을 쉬었다.<br>훑고 지나간 자리에 다들 한참 엎드려 있었다. 일어났을 때 무릎이 다 젖어 있었다. 물웅덩이도 없었는데.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S2', t:'급이대 — 도르래 배달',
  x:`급이대 도르래 줄이 숲 너머 둔덕까지 걸려 있다. 먹이를 멀리 보내던 줄이다.<br><br>
    고리에 녹슨 통이 하나 달려 아직 구른다.<br>
    쟁여 둔 고기 반 토막이 짐에 있다. 상하기 시작해 어차피 버릴 참이었다.<br><br>
    썩어 가는 재고도 쓸 데가 있는 법이다. 행상은 재고 처리로 먹고산다.`,
  o:[
    { l:'① 상한 고기를 통에 실어 멀리 보낸다.', k:'fix', dc:24,
      ok:`상한 고기를 통에 담고 도르래를 돌렸다. 통이 끼익끼익 숲 너머로 갔다.<br><br>둔덕에 닿자 냄새가 퍼졌는지 그 일대 수풀이 들썩이기 시작했다. 사냥하는 것들이 그쪽으로 몰렸다.<br>빈 급이대 밑을 유유히 지났다. 버릴 재고로 길을 샀다. 이문으로 치면 올해 최고다.`,
      ng:`도르래가 반쯤 가다 녹슨 데서 멈췄다. 상한 냄새가 머리 위에 걸린 채 퍼졌다.<br><br>냄새를 따라온 것들이 급이대 밑으로 모여들었다. 하필 이쪽 길목으로.<br>덤불로 꺾어 크게 돌았다. 배달 사고는 어디서나 치명적이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 통 속 묵은 것부터 꺼내 본다.', k:'sense', dc:23,
      ok:`통 바닥에 기름종이 꾸러미가 눌어붙어 있었다. 사육사들이 제 참거리를 숨겨 둔 자리다.<br><br>밀랍 봉인이 성했다. 뜯으니 소금에 전 고기와 마른 꿀 한 줌이 나왔다.<br>일하는 사람들 숨긴 간식 자리는 어딜 가나 같다. 행상은 그 자리를 안다. 팔러 다니던 쪽이니까.`,
      ng:`통을 기울이는데 바닥에 고인 빗물이 왈칵 쏟아졌다. 썩은 물이 바지에 뱄다.<br><br>냄새가 지독했다. 씻어도 가시지 않았다.<br>그날 하루 종일 잔것들이 바지 냄새를 따라붙었다. 작은 이빨들이 바짓단을 두 번 물었다.`,
      win:{ exp:17, dream:2, item:'꿀 한 줌' }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S2', t:'관리인 오두막 — 재고 장부',
  x:`숲 가장자리에 관리인 오두막이 섰다. 문이 반쯤 열린 채 굳었다.<br><br>
    안에 사육 장부가 펴져 있다. 「들여온 것 열둘. 큰 것 하나. 무리 일곱. 흩어진 것 넷.」<br>
    마지막 장 글씨가 급하다. 「무리가 수를 센다. 우리가 몇인지 세고 있다.」<br><br>
    행상은 장부를 믿는다. 장부는 쓴 사람이 죽어도 거짓말을 안 한다.`,
  o:[
    { l:'① 장부로 저쪽 재고를 다 센다.', k:'luck', dc:25,
      ok:`들여온 수에서 뼈로 본 수를 뺐다. 무리 일곱에서 울타리 밑 뼈 둘. 다섯. 어제 본 그림자 셋에 둘이 빈다.<br><br>빈 둘은 늘 안 보이는 데 있다는 뜻이다. 몰이의 옆잡이들.<br>그날부터 셋이 보이면 다섯을 셈했다. 두 번, 그 셈이 맞아서 옆에서 오던 것을 미리 피했다. 남의 재고를 내 장부에 옮겨 적으면 그게 바로 밑천이다.`,
      ng:`장부 셈에 빠진 게 있었다. 맨 밑에 흐린 글씨. 「알을 깐 것 같다」.<br><br>재고가 는다는 소리다. 센 수가 다 헛수가 됐다.<br>숲에서 작은 울음들이 여럿 답했을 때에야 그 줄이 떠올랐다. 낡은 장부는 반만 믿는 것이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-20 } },
    { l:'② 오두막 세간을 챙긴다.', k:'sense', dc:23,
      ok:`선반 밑, 침상 밑, 문 뒤. 사람 사는 곳의 물건 자리는 어디나 같다.<br><br>가축용 소금 덩이 반 토막과 기름 한 병, 성한 밧줄이 나왔다.<br>나오며 문을 반쯤 열린 그대로 뒀다. 들어올 때 모양 그대로. 빈집에도 예절이 있고, 예절은 공짜다.`,
      ng:`침상 밑을 더듬는데 손끝에 둥근 것이 닿았다. 알이다. 따뜻했다.<br><br>오두막이 빈집이 아니라 둥지였던 것이다. 손을 빼고 뒷걸음으로 나왔다.<br>문간에서 돌아보니 지붕 그늘에서 두 눈이 이쪽을 내려다보고 있었다. 세간이고 뭐고 빈손으로 나온 게 다행이었다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ mind:-16, spirit:-21 } }
  ] },

{ at:'S2', t:'알 더미 — 깨진 것만',
  x:`모래 둔덕에 알이 묻혀 있다. 성한 것 여남은, 깨진 껍데기가 그 곱절.<br><br>
    성한 알은 솥만 하다. 뭍에 가져가면 값을 못 매길 물건이다.<br>
    깨진 껍데기도 물건은 물건이다. 그릇이 되고, 바가지가 되고, 물을 담는다.<br><br>
    행상의 눈이 성한 알과 깨진 껍데기 사이를 오간다. 값과 목숨값 사이를.`,
  o:[
    { l:'① 깨진 껍데기만 추려 담는다.', k:'luck', dc:24,
      ok:`성한 알에는 손도 안 댔다. 깨진 껍데기 중 큰 조각만 셋 골라 짐에 얹었다.<br><br>어미 눈에 깨진 껍데기는 쓰레기다. 세지도 않는다. 임자 없는 물건만 거두는 게 장물 안 지는 요령이다.<br>그날 저녁 껍데기 바가지로 빗물을 받아 다 같이 마셨다. 솥만 한 알값은 못 돼도, 목숨값보다는 싼 물건들이다.`,
      ng:`껍데기를 빼내다 밑에 괸 성한 알 하나가 기우뚱했다.<br><br>알이 구르다 돌에 닿아 금이 갔다. 속에서 우는 소리가 났다. 가늘고 높게.<br>그 소리에 숲이 통째로 대답했다. 껍데기고 뭐고 던져 두고 뛰었다. 어미 울음이 한나절 숲을 덮었다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-27, mind:-16 } },
    { l:'② 성한 알 하나만 짐에 넣는다.', k:'steady', dc:26,
      doom:{ title:'센 알', what:'어미에게 물려 알 둔덕으로 끌려갑니다', dc:20, sec:45,
        text:`제일 작은 성한 알 하나를 천에 싸서 짐 깊이 넣었다. 평생 한 번 올까 말까 한 물건이다.<br><br>둔덕을 벗어나기도 전에 등 뒤 숲이 조용해졌다. 새소리까지 끊긴 조용함.<br>어미는 울지도 않았다. 뒤에서 와서 짐째 물었다. 들려서 둔덕으로 돌아간다. 알은 제자리에 내려놓아지고, 이쪽은 알 옆에 나란히 놓인다. 어미의 장부는 두 줄이 늘었다. 돌아온 알 하나, 새 먹이 하나.<br><br>값을 못 매길 물건에는 이유가 있다. 값이 없는 게 아니라 셈이 다른 것이다.`,
        dieText:`모래 둔덕 알자리가 가지런하다.<br><br>성한 알 여남은 개. 수가 맞다.<br>알들 곁에 길쭉하게 눌린 자리가 하나 새로 생겼다.` },
      ok:`제일 작은 알 하나를 쌌다. 그리고 셈을 다시 했다. 지고 뛸 수 있나. 못 뛴다. 알을 도로 제자리에 뉘었다.<br><br>모래까지 원래대로 덮고 물러났다.<br>둔덕 밖에서 뒤돌아보니 어미가 돌아와 알자리에 코를 대고 있었다. 하나하나, 세고 있었다. 짐에 든 게 없는데도 등에서 식은땀이 났다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 삯 달기',
  x:`낡은 승강기 균형추가 비어 있다. 추 바구니에 무게를 채워야 움직이는 물건이다.<br><br>
    바구니 옆에 녹슨 분동 몇 개와, 사육사들이 쓰던 모래 자루가 흩어져 있다.<br>
    너무 가벼우면 안 오르고, 너무 무거우면 줄이 상한다.<br><br>
    행상은 평생 저울을 맞췄다. 이건 그냥 큰 저울이다.`,
  o:[
    { l:'① 사람 무게를 달아 추를 맞춘다.', k:'luck', dc:25, wake:1,
      ok:`일행을 하나씩 승강기 판에 세우고 판이 가라앉는 눈금을 봤다. 눈대중 삼십 년이면 사람도 달 수 있다.<br><br>모래 자루로 그 무게에 꼭 맞춰 추를 채웠다. 한 줌 모자라게. 모자란 쪽이 줄에 순하다.<br>승강기가 신음 한 번 없이 올랐다. 내릴 때 추도 곱게 내려앉았다. 저울 맞추는 손은 어디서나 먹고산다.<br><br>물건 달던 눈금에 사람을 달았다. 저울 눈이 커질수록 떨림은 없어진다는 걸 알았다.`,
      ng:`모래 자루 하나가 삭아 있었다. 오르는 중에 터지며 추가 가벼워졌다.<br><br>승강기가 반 층에서 멈췄다 미끄러졌다. 매달린 채 다들 소리를 삼켰다.<br>밑에서 추 바구니에 돌을 던져 넣어 겨우 맞췄다. 올라갔을 때는 다들 손바닥이 땀으로 번들거렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 분동부터 줄과 도르래를 점검한다.', k:'fix', dc:24,
      ok:`타기 전에 분동으로 줄을 당겨 보고 도르래 홈을 더듬었다. 홈 하나에 돌이 끼어 있었다.<br><br>돌을 빼고 기름을 먹였다. 그다음에 탔다.<br>점검 안 한 저울로 거래 안 하는 건 행상의 밑바닥 규칙이다. 목숨을 다는 저울이면 더 말할 것 없다.`,
      ng:`점검에 해가 기울었다. 어두워지자 승강기 밑으로 기척들이 모였다.<br><br>소리에 모이는 것들이다. 도르래 삐걱임이 저녁 종이었던 것이다.<br>결국 한밤에 등불을 끄고 탔다. 어둠 속에서 오르는 내내 밑에서 긁는 소리가 따라 올라왔다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-20 } }
  ] }

]);

// ==========================================
// 🔮 점술가 (fortune) · 마력
// ==========================================
kJob('fortune', 'S', [

{ at:'S', t:'문턱 — 흩어지는 괘',
  x:`들어가기 전에 산가지를 던졌다. 문턱 넘기 전 한 괘. 버릇이고 일이다.<br><br>
    다섯 개가 떨어지다 말고 바닥에서 저희끼리 굴러 흩어졌다. 사방으로, 제각각.<br>
    이런 괘는 책에 없다. 괘가 아니라 꼴이다. 몰이를 만난 들쥐 떼가 흩어지는 꼴.<br><br>
    산가지도 여기서는 쫓기는 쪽이다.`,
  o:[
    { l:'① 흩어진 꼴을 괘로 읽는다.', k:'luck', dc:25, wake:1,
      ok:`책에 없으면 눈으로 새로 읽는 수밖에 없다. 다섯 개가 흩어진 방향을 다 그어 봤다.<br><br>겹치는 데가 한 곳 있다. 다들 거기서부터 달아났다. 그 자리를 등지고 길을 잡았다.<br>반 시진 뒤, 등진 쪽에서 긴 울음이 났다. 괘는 맞았다. 책이 모자랐을 뿐이다.<br><br>책에 없는 괘를 처음으로 지어 읽었다. 점이 글이 아니라 눈이라는 걸 여기서 배운다.`,
      ng:`방향을 긋는데 산가지 하나가 또 굴렀다. 제 발로. 문턱 바깥쪽으로.<br><br>나가라는 것이다. 문은 이미 등 뒤에서 닫혔는데.<br>도망칠 데 없는 데서 도망치라는 괘만큼 나쁜 괘가 없다. 남은 네 개를 주워 품에 넣었다. 손이 떨려 두 번 떨어뜨렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 괘를 접고 귀로 듣는다.', k:'sense', dc:24,
      ok:`산가지를 거두고 눈을 감았다. 점이 소란하면 귀가 점이다.<br><br>왼쪽 어둠은 소리가 둥글게 울리고, 오른쪽은 울림이 빨리 죽는다. 오른쪽에 뭔가 가득 차 있다는 소리다.<br>왼쪽으로 들었다. 빈 울림이 길을 내줬다.`,
      ng:`귀를 세우는데 숨소리가 들렸다. 이쪽 숨에 반 박자 늦게 따라오는 숨.<br><br>숨을 멈췄다. 저쪽도 멈췄다. 흉내다. 귀로 사냥하는 것에게 귀를 세운 꼴이다.<br>등불을 흔들며 소리 나는 반대쪽으로 빠졌다. 한참을 제 숨소리가 무서웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'향 — 눕는 연기',
  x:`갈림 앞에서 향에 불을 붙였다. 연기 점은 바람 없는 데서 치는 점이다.<br><br>
    연기가 곧게 오르다가, 어느 높이에서 옆으로 꺾여 눕는다. 왼쪽 길 쪽으로.<br>
    바람이 아니다. 숨이다. 크고 느린 들숨이 어디선가 연기를 당기고 있다.<br><br>
    연기는 거짓말을 못 한다. 향 한 대가 다 탈 때까지가 점칠 시간이다.`,
  o:[
    { l:'① 연기가 눕는 쪽을 버리고 간다.', k:'sense', dc:24,
      ok:`연기 끝이 가리키는 왼쪽은 들숨의 길이다. 오른쪽으로 들었다.<br><br>반 식경 뒤 왼쪽 멀리서 재채기 같은 소리가 터졌다. 향 연기가 콧속까지 갔던 모양이다.<br>향 한 대로 콧구멍의 위치까지 알았다. 싼 점이었다.`,
      ng:`오른쪽으로 드는데 연기가 따라 꺾였다. 들숨이 방향을 바꾼 것이다.<br><br>연기가 아니라 이쪽 냄새를 들이켜고 있었다.<br>향을 끄고 물웅덩이를 첨벙여 냄새를 끊었다. 한참을 돌아서 갔다. 젖은 신발이 밤새 안 말랐다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 마력을 먹여 연기를 무겁게 깐다.', k:'hide', dc:24, cost:{ mana:30 },
      ok:`향 연기에 마력을 실었다. 연기가 안개처럼 무거워져 바닥에 깔렸다.<br><br>일행의 냄새가 향 밑에 묻혔다. 깔린 연기를 치마처럼 끌며 갈림을 지났다.<br>들숨이 두어 번 연기만 들이켜고 그쳤다. 향내 나는 빈 어둠만 삼킨 것이다.`,
      ng:`마력을 먹인 연기가 너무 짙었다. 이쪽 눈이 먼저 매웠다.<br><br>기침이 터졌다. 한 번. 연기 밖까지 들리는 한 번.<br>연기 속에서 뒤엉켜 뛰었다. 매운 눈물 반, 식은땀 반으로 갈림을 벗어났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-19 } }
  ] },

{ at:'S', t:'핏자국 — 뿌려진 방향',
  x:`바닥에 핏자국이 뿌려져 있다. 사람 것이다.<br><br>
    점술가는 찻잎을 읽듯 뿌려진 것을 읽는다. 핏방울은 길쭉한 쪽이 날아간 방향이다.<br>
    방울들이 다 한쪽으로 길다. 끌려간 방향이다.<br>
    그리고 자국 끝이 아직 안 말랐다.<br><br>
    방금이다.`,
  o:[
    { l:'① 핏점을 끝까지 읽는다.', k:'luck', dc:25,
      ok:`방울의 크기를 봤다. 처음엔 굵고 갈수록 잘다. 피가 멎어 가며 끌려갔다는 것이다. 산 채로.<br><br>그리고 방울 사이 간격이 일정하다. 허둥대는 걸음이 아니다. 무거운 것이 느긋하게 걷는 박자다. 급할 것 없는 사냥꾼. 배가 부른 사냥꾼이다.<br>배부른 것의 길은 당분간 빈다. 그 길을 거슬러, 그것이 왔던 쪽의 빈자리로 빠졌다.`,
      ng:`읽는 데 너무 오래 쪼그려 앉아 있었다.<br><br>자국 끝 어둠에서 무엇이 되돌아오는 기척이 났다. 흘린 것을 챙기러 오는 걸음.<br>읽다 만 핏점 위로 등불을 엎고 뛰었다. 피와 기름 타는 냄새가 뒤를 막아 줬다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 자국 위에 재를 덮고 지나간다.', k:'steady', dc:23,
      ok:`읽을 만큼 읽고, 자국에 재를 덮었다. 끌려간 사람한테 해 줄 수 있는 게 그것뿐이었다.<br><br>재 덮인 피는 점도 못 치고 코도 못 읽는다. 뒤따라올 다른 것들에게 이 길의 일을 지운 것이다.<br>지나고 나서 짧게 빌었다. 점술가의 기도는 짧다. 길면 듣는 게 생긴다.`,
      ng:`재를 덮는데 자국 끝에서 소리가 났다. 사람 소리. 끊어질 듯한.<br><br>살아 있는 것이다. 달려가 볼 수도, 두고 갈 수도 없는 소리가 두 번 나고 그쳤다.<br>그 뒤로는 아무 소리도 없었다. 덮다 만 재를 마저 덮었다. 손이 무거웠다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'S', t:'쉬는 자리 — 낯빛 보기',
  x:`쉬는 자리에서 일행의 낯을 하나씩 봤다. 관상은 점술가의 기본기다.<br><br>
    한 사람 낯에 그늘이 앉았다. 사색이 아니다. 죽을상도 아니다. 뭐라 부를 수 없는, 짐승 우리에 들어간 사람의 상이다.<br>
    자세히 보니 그늘이 아니라 자국이다. 목덜미에서 뺨까지, 기름 같은 것이 엷게 발려 있다.<br><br>
    언제 발렸는지 본인도 모른다. 여기 것들은 먹을 것에 표시를 해 두는 모양이다.`,
  o:[
    { l:'① 자국을 읽고 지워 낸다.', k:'luck', dc:25, wake:1,
      ok:`자국의 결을 봤다. 위에서 아래로, 혀나 촉수가 쓸고 간 결이다. 잴 때 묻은 것이다. 재 두고 간 것이다.<br><br>잿물을 풀어 목덜미부터 뺨까지 씻겼다. 세 번. 기름기가 다 빠질 때까지.<br>그날 밤 어둠이 야영지를 두 바퀴 돌았다. 찜해 둔 것을 찾는 걸음이었다. 못 찾고 갔다. 장부에서 한 줄을 지운 것이다.<br><br>낯에서 명운만 읽던 눈이 남이 적어 둔 표식까지 읽는다. 관상 너머를 보기 시작했다.`,
      ng:`씻기는데 자국이 안 빠진다. 기름이 아니라 살에 밴 것이다.<br><br>문지를수록 그 사람이 아프다고 했다. 자국 밑 살이 열이 올랐다.<br>밤새 번갈아 찬 물수건을 댔다. 새벽에야 열이 내렸다. 자국은 옅어졌지만 다 안 지워졌다. 다들 그 사람 곁에 바짝 붙어 걷게 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-21 } },
    { l:'② 그 사람을 한가운데 세우고 움직인다.', k:'bond', dc:24,
      ok:`아무 말 없이 걷는 차례만 바꿨다. 표식 있는 사람을 가운데로, 앞뒤로 둘씩.<br><br>표시해 둔 먹이를 찾으러 온 것이 대열을 몇 바퀴 돌았다. 가운데 것만 빼 갈 수가 없는 짜임이다.<br>포기하는 기척이 멀어졌다. 왜 자리를 바꿨는지는 끝까지 말 안 했다. 모르는 게 잠에 낫다.`,
      ng:`가운데 세웠는데 그 사람이 눈치챘다. 왜 자기만 가운데냐고.<br><br>숨기려다 더 겁을 줬다. 사실대로 말하자 그 사람 다리가 풀렸다.<br>업고 걸었다. 아는 것이 힘이 아닐 때도 있다. 그날 밤 그 사람은 눈을 한 번도 안 감았다.`,
      win:{ exp:17, dream:2, mind:6 }, lose:{ mind:-17, spirit:-23 } },
    { l:'③ 자국에 딴 냄새를 덧바른다.', k:'heal', dc:24,
      ok:`지워지지 않으면 덮는 수다. 약초를 짓이겨 자국 위에 발랐다. 쓰고 독한 풀 냄새.<br><br>먹을 것에 쓴 약 냄새가 배면 입맛이 돈다. 사람이나 짐승이나.<br>그날 밤 코 고는 소리 사이로 무엇이 왔다가, 코를 두 번 킁킁대고, 돌아갔다. 상한 물건 취급이다. 서운할 일이 아니다.`,
      ng:`약초 냄새가 너무 셌다. 딴것이 꼬였다. 쓴 풀만 골라 먹는 작은 것들이다.<br><br>밤새 그 사람 둘레에서 바스락거렸다. 물지는 않는데 잠을 다 깨웠다.<br>새벽에 보니 바른 약초만 싹 핥아 가고 자국이 도로 드러나 있었다. 처음부터 다시였다.`,
      win:{ exp:17, dream:2, item:'약초 뭉치' }, lose:{ mind:-15, spirit:-18 } }
  ] },

{ at:'S', t:'촛불 — 숨을 세는 불',
  x:`잠자리에 초를 켰다. 불꽃점은 밤의 점이다.<br><br>
    불꽃이 가끔 납작 엎드린다. 바람이 아니다. 숨이다. 어둠 속 큰 숨이 들이쉴 때마다 불이 눕는다.<br>
    눕는 간격을 쟀다. 느리고 고르다. 자는 숨이다.<br><br>
    문제는 이 불꽃이 얼마나 가까운 숨까지 읽는가다.`,
  o:[
    { l:'① 불꽃으로 숨의 거리를 잰다.', k:'luck', dc:24,
      ok:`초를 들고 야영지 둘레를 천천히 돌았다. 북쪽에서 불꽃이 제일 깊게 눕는다. 그쪽이 가깝다.<br><br>잠자리를 남쪽 바위 밑으로 옮겼다. 불꽃이 겨우 떨 만큼의 거리로.<br>밤새 불꽃은 가늘게 떨기만 했다. 떨림이 자장가였다. 숨 쉬는 걸 아는 채로 자는 잠이 모르고 자는 잠보다 깊었다.`,
      ng:`재는 중에 불꽃이 똑바로 섰다. 숨이 멎은 것이다.<br><br>자다 깬 것은 숨부터 죽인다. 초를 끄고 어둠에 엎드렸다.<br>한참 뒤 다시 큰 숨이 돌아왔다. 깼다가 다시 잔 것이다. 그 사이가 얼마나 길었는지는 꺼진 초의 심지만 안다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 불을 끄고 몸으로 잔다.', k:'steady', dc:23,
      ok:`점은 접었다. 불빛 자체가 표적이다. 초를 끄고 바위 틈에 등을 맞대고 잤다.<br><br>점술가가 점을 접는 것도 점이다. 오늘 밤 패는 어둠이 셌다.<br>새벽에 보니 바위 바깥 흙에 큰 발자국이 하나 찍혀 있었다. 불 꺼진 야영지를 못 보고 지나간 것이다.`,
      ng:`껐는데 어둠이 눈에 설어 잠이 안 왔다. 뒤척이는 소리가 바위 틈에 울렸다.<br><br>무엇이 그 소리를 듣고 바위 겉을 긁어 봤다. 손톱 가는 소리가 머리맡에서 났다.<br>아무도 안 잤다. 날이 샐 때 다들 눈이 빨갰다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'S', t:'알 — 태점',
  x:`길가 움푹한 데에 알이 세 개 묻혀 있다. 따뜻하다.<br><br>
    태점이라는 게 있다. 뱃속 아이의 수와 때를 짚는 점. 손바닥을 대고 맥을 읽는다.<br>
    알의 때를 알면 이 길의 때를 안다. 깨기 전이면 어미가 멀고, 깰 때면 어미가 곁이다.<br><br>
    손바닥이 근질거린다. 아는 것이 힘인 곳이다. 대개는.`,
  o:[
    { l:'① 알에 손을 얹고 태점을 친다.', k:'gaze', dc:25,
      doom:{ title:'깰 때', what:'알 임자에게 물려 둥지로 끌려갑니다', dc:19, sec:45,
        text:`손바닥을 얹었다. 맥이 읽힌다. 빠르다. 너무 빠르다.<br><br>깰 때가 아니라 깨는 중이었다. 껍질이 손바닥 밑에서 금 갔다. 속엣것이 첫 울음을 울었다.<br>첫 울음은 어미를 부르는 소리다. 어미는 늘 들리는 데 있다. 뒷덜미가 물렸다. 끌려간다. 둥지 쪽으로. 품에 안긴 점괘첩이 길에 떨어졌다.<br><br>태점은 맞았다. 셋 다 건강하다. 오늘 깬다. 다 맞혔는데 마지막 줄을 늦게 읽었다.`,
        dieText:`길가 움푹한 데에 알이 세 개 있다.<br><br>하나는 깨어 비었다.<br>알자리 옆에 점괘첩이 떨어져 있다. 마지막 장이 펴진 채다.` },
      ok:`손바닥을 얹고 맥을 읽었다. 느리다. 아직 멀었다. 이레는 더 품어야 할 맥이다.<br><br>이레짜리 알을 두고 다니는 어미는 순찰이 길다. 이 길은 당분간 빈다.<br>손을 떼고 알 위에 흙을 도로 덮었다. 태점 쳐 준 값이다. 따뜻한 맥 셋이 손바닥에 한참 남아 있었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 알자리 둘레의 자국만 읽는다.', k:'sense', dc:24,
      ok:`알에는 손 안 댔다. 둘레 흙의 자국을 읽었다. 드나든 발자국이 다 한 방향, 자국 위에 마른 정도가 세 켜.<br><br>하루 세 번 도는 어미다. 마지막 자국이 반쯤 말랐으니 다음 순찰까지 반나절.<br>반나절 안에 이 길을 벗어나면 된다. 알 맥은 몰라도 어미 시간표는 얻었다.`,
      ng:`자국을 읽는데 셈이 안 맞았다. 드나든 발이 두 종류였다.<br><br>어미가 둘이거나, 어미와 딴것이거나. 딴것 쪽 자국이 더 새것이었다.<br>알 도둑이 먼저 와 있다는 소리다. 알자리가 곧 싸움터가 된다. 서둘러 벗어나는데 등 뒤에서 벌써 울음 두 가지가 맞붙었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'꿈 — 내일의 비명',
  x:`새벽에 깼다. 꿈에서 비명을 들었다.<br><br>
    점술가의 꿈은 가끔 하루를 앞질러 온다. 비명은 일행 목소리였다. 누구인지는 흐렸다. 물소리, 미끄러지는 돌, 그리고 아래에서 올라오는 비린 숨.<br>
    물가 벼랑. 오늘 길에 그런 데가 있는지는 모른다.<br><br>
    미리 꾼 꿈은 고칠 수 있는 꿈이다. 그러라고 먼저 오는 것이다.`,
  o:[
    { l:'① 마력으로 꿈을 되감아 자리를 본다.', k:'luck', dc:25, wake:1, cost:{ mana:32 },
      ok:`눈을 감고 마력을 심지 삼아 꿈을 되감았다. 물소리. 이끼 낀 돌. 돌에 희게 긁힌 자국. 벼랑 끝 두 갈래 뿌리.<br><br>한낮에 그 자리가 나왔다. 두 갈래 뿌리까지 똑같았다. 일행을 세우고 벼랑 쪽 길을 버리게 했다.<br>아래를 내려다보니 물가에 그것이 입을 벌리고 떠 있었다. 미끄러지는 것을 받아먹는 자리였다.<br><br>꿈을 담벼락 너머 구경하듯 보던 눈이, 꿈속을 걸어 다니며 조사하는 눈이 됐다.`,
      ng:`되감는데 꿈이 바뀌었다. 비명 지르는 얼굴이 이쪽을 봤다. 이쪽 얼굴이었다.<br><br>마력을 끊고 눈을 떴다. 식은땀이 흥건했다.<br>그날 하루 물소리가 날 때마다 걸음이 굳었다. 벼랑은 안 나왔다. 아직은. 꿈 셈이 하루짜리가 아닐 수도 있다는 게 제일 나빴다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 꿈값만 받고 길을 바꾼다.', k:'fix', dc:24,
      ok:`꿈의 세간을 믿기로 했다. 물소리 나는 길을 다 피해 짰다. 멀어도 마른 길로만.<br><br>한나절을 돌았다. 돌던 중에 물길 쪽에서 무엇이 첨벙이는 소리를 멀리 들었다.<br>비명은 그날 안 났다. 꿈이 틀린 건지 피해서 안 난 건지는 알 수 없다. 점은 원래 맞춘 티가 안 난다. 그게 점의 서러움이고, 오늘은 그 서러움이 달았다.`,
      ng:`마른 길로 돌았는데 마른 길이 더 험했다. 돌밭에서 일행 하나가 발목을 접질렸다.<br><br>꿈 피하려다 생돈을 낸 셈이다.<br>업고 걷는데 멀리서 물소리가 비웃듯 졸졸거렸다. 꿈값이 쌌는지 비쌌는지는 끝까지 셈이 안 됐다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'산가지 — 서는 수',
  x:`어둠이 깊은 데서 산가지를 던졌다. 몇이 보고 있는지 알고 싶었다.<br><br>
    눕는 것은 빈 어둠, 서는 것은 눈이라고 치는 셈법이 있다. 스승이 장난처럼 가르친 것이다.<br>
    던졌다. 다섯 중 셋이 섰다. 모랫바닥에, 거짓말처럼 꼿꼿이.<br><br>
    장난이 아니었던 모양이다. 셋이 보고 있다.`,
  o:[
    { l:'① 선 산가지가 기운 쪽을 등진다.', k:'luck', dc:25,
      ok:`선 셋이 다 같은 쪽으로 아주 조금 기울어 있다. 머리 숙여 절하는 쪽. 그쪽에 눈들이 있다.<br><br>그쪽을 등지지 않았다. 등지면 덮친다. 마주 보지도 않았다. 마주 보면 싸움이다.<br>옆으로, 게처럼, 눈들을 시야 가장자리에 걸어 둔 채 벗어났다. 산가지 셋은 그 자리에 세워 두고 왔다. 저쪽 셈에는 그게 이쪽 눈 셋으로 보일 것이다.`,
      ng:`옆걸음으로 벗어나는데 산가지 하나가 툭 쓰러지는 소리가 났다.<br><br>눈 하나가 움직였다는 뜻이다. 어느 쪽으로인지 모른다는 게 문제다.<br>걸음을 늘리다 돌부리에 걸려 소리를 냈다. 어둠 속 셋이 일제히 움직이는 기척. 등불을 던지고 그 빛을 등져 내달렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 불을 키워 수를 눈으로 맞춘다.', k:'fix', dc:24,
      ok:`등불 심지를 다 올렸다. 빛 가장자리에 눈 세 쌍이 걸렸다. 산가지 셈과 수가 맞다.<br><br>수를 아는 포위는 포위가 아니다. 셋의 사이가 제일 넓은 틈으로 천천히 걸어 나갔다.<br>쫓아오지 않았다. 세는 걸 들킨 사냥은 접는 모양이다. 저쪽도 셈꾼이다.`,
      ng:`심지를 올리자 눈이 다섯으로 늘었다. 빛이 닿자 둘이 더 깬 것이다.<br><br>산가지 셈보다 수가 많아졌다. 점이 뒤처지는 속도로 상황이 나빠졌다.<br>불을 확 던져 마른 덤불에 불을 놓고 그 틈에 빠졌다. 뒤에서 덤불 타는 빛에 다섯 그림자가 길게 흔들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S', t:'길 — 죽은 점술가의 손',
  x:`길가에 사람이 엎드려 있다. 오래됐다. 마른 지 오래된 몸.<br><br>
    한 손이 앞으로 뻗어 있고, 손가락 둘레에 산가지가 흩어져 있다. 같은 업이다. 마지막까지 점을 치다 갔다.<br>
    괘는 다 못 떨어졌다. 두 개는 손안에 쥔 채다.<br><br>
    마저 떨어뜨리면 괘가 완성된다. 죽은 사람이 마지막으로 묻던 것이 나온다.`,
  o:[
    { l:'① 쥔 손을 펴고 괘를 마저 떨군다.', k:'gaze', dc:26,
      doom:{ title:'마지막 손님', what:'죽은 몸에 걸린 줄에 감겨 끌려갑니다', dc:20, sec:40,
        text:`굳은 손가락을 하나씩 폈다. 산가지 두 개가 손바닥에서 굴러떨어졌다.<br><br>그리고 몸이 통째로 움직였다. 죽은 몸 밑으로 가늘고 질긴 줄이 지나가고 있었다. 길가 어둠까지.<br>줄이 당겨진다. 죽은 점술가가 미끼였다. 같은 업을 부르는 미끼. 발목에 줄이 감겨 끌려간다. 떨어진 두 산가지가 마지막 괘를 완성한 채 멀어진다.<br><br>그 괘는 읽었다. 떨어지는 꼴이 또렷했다. 「묻지 마라」였다.`,
        dieText:`길가에 사람이 둘 엎드려 있다.<br><br>하나는 오래됐고 하나는 아직 새것이다.<br>새것의 손에도 산가지가 두 개 쥐여 있다.` },
      ok:`손을 펴기 전에 몸 둘레부터 봤다. 버릇이 아니라 이번엔 겁이 시킨 일이다.<br><br>몸 밑으로 가는 줄이 지나가고 있었다. 팽팽하게, 어둠까지.<br>손은 안 폈다. 대신 흩어진 괘만 눈으로 읽었다. 떨어진 세 개가 가리키는 곳이 다 한 방향이었다. 그쪽만 피해서 갔다. 죽은 동업자의 마지막 점괘는 미끼 위에서도 일을 했다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 괘를 마저 묻지 않고 산가지만 거둬 준다.', k:'luck', dc:25, wake:1,
      ok:`죽은 사람의 물음은 죽은 사람 것이다. 마저 묻지 않았다.<br><br>흩어진 산가지만 막대로 끌어모아 그 손 곁에 가지런히 놓았다. 쥔 두 개는 그대로 뒀다. 괘를 반만 쥐고 가는 것도 그 사람 몫이다.<br>일어서는데 바람도 없이 산가지들이 또르르 한 번 구르고 멎었다. 고맙다는 소리로 듣기로 했다.<br><br>모든 물음에 답을 받아 내는 게 점인 줄 알았다. 안 묻고 덮는 것도 점의 일이라는 걸 죽은 동업자가 가르쳤다.`,
      ng:`거둬 주려 다가서다 그 몸 밑의 줄을 밟았다.<br><br>줄이 울렸다. 어둠 저쪽에서 줄을 쥔 것이 당겨 봤다. 두 번.<br>발을 빼고 뛰었다. 등 뒤에서 죽은 몸이 줄에 끌려 어둠으로 들어가는 소리가 났다. 미끼를 거두는 소리다. 허탕 친 낚시꾼은 자리를 옮긴다. 어디로 옮겼는지 몰라 그날 내내 발밑만 봤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-23 } }
  ] },

{ at:'S', t:'이름 없는 것 — 짐승 괘',
  x:`사흘을 쫓기며 세 번 점을 쳤다. 세 번 다 괘가 비었다.<br><br>
    귀신 괘로 치면 빈다. 저주 괘로 쳐도 빈다. 이름을 모르는 것은 괘에 안 걸린다고 배웠다.<br>
    나흘째 아침, 그것이 먹다 남긴 자리를 봤다. 먹고, 자고, 새끼를 먹인 자리.<br><br>
    귀신이 아니다. 짐승이다. 짐승이면 짐승 괘가 있다. 사냥꾼들이 쓰는 제일 오래된 점이.`,
  o:[
    { l:'① 짐승 괘로 바꿔 친다.', k:'luck', dc:25, wake:1,
      ok:`귀신 묻는 괘를 접고 사냥 괘를 폈다. 어디서 자는가. 언제 먹는가. 어느 길로 물을 마시러 가는가.<br><br>괘가 차기 시작했다. 셋 다 답이 나왔다. 이름은 끝까지 안 나왔지만, 이름 없이도 피할 수 있는 답들이었다.<br>물 마시는 시간에 그것의 길을 등지고 걸었다. 나흘 만에 처음으로 쫓기지 않은 하루였다.<br><br>무서운 것에 이름부터 붙이려던 버릇을 접었다. 모르는 채로 재는 법. 점이 한 뼘 넓어졌다.`,
      ng:`사냥 괘로 바꿨는데 손이 옛 버릇대로 귀신 괘를 섞었다.<br><br>반반으로 친 괘는 반반으로 빈다. 자는 곳은 나왔는데 때가 안 나왔다.<br>자는 곳을 피해 돌다가 깨어 있는 그것과 마주칠 뻔했다. 바위 하나를 사이에 두고 숨을 죽였다. 괘는 섞으면 안 섞느니만 못하다. 알면서 또 섞었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-21 } },
    { l:'② 점을 접고 자국만 따라 배운다.', k:'sense', dc:24,
      ok:`점술 도구를 다 집어넣었다. 발자국, 똥, 긁은 자국. 짐승은 몸으로 제 점괘를 흘리고 다닌다.<br><br>한나절을 따라 읽으니 하루 치 길이 그려졌다. 아침에 물가, 한낮에 그늘, 밤에 사냥.<br>점술가가 점 없이 하루를 읽었다. 스승이 봤으면 혀를 찼을지 웃었을지 모르겠다.`,
      ng:`자국을 따라 읽다가 너무 깊이 들어갔다. 자국이 제일 짙은 데는 그것의 안방이다.<br><br>그늘에서 자던 숨이 바뀌는 소리에 정신이 들었다.<br>발끝으로 반 시진을 물러 나왔다. 읽는 데 취하면 책 속에 들어가 앉는 꼴이 된다. 책이 이빨이 있는데도.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-17 } }
  ] },

{ at:'S', t:'손금 — 옮은 자국',
  x:`아침에 제 손바닥을 봤다. 버릇이다. 그리고 굳었다.<br><br>
    생명선 옆에 없던 금이 하나 생겼다. 가늘고, 번들거리고, 살짝 부풀었다.<br>
    남의 낯에서 본 것과 같은 자국이다. 먹을 것에 해 두는 표시.<br><br>
    언제 묻었는지 모른다. 남의 표식을 지워 주던 손에, 표식이 옮아 있다.`,
  o:[
    { l:'① 자국 위에 제 금을 덧긋는다.', k:'gaze', dc:25,
      ok:`지워지지 않는 표식이면 못 읽게 만들면 된다. 숯과 잿물로 손바닥 가득 가짜 금을 그렸다. 표식과 같은 결, 같은 굵기로 수십 줄.<br><br>표식 하나가 표식 무더기에 묻혔다. 어느 줄이 제 것인지 저쪽도 못 찾을 것이다.<br>그날 밤 무엇이 야영지 가장자리서 코를 오래 킁킁댔다. 장부를 못 읽는 코였다. 그냥 갔다. 점술가 손은 원래 금이 많아야 장사가 된다. 웃음이 나왔다.`,
      ng:`가짜 금을 긋는데 진짜 자국이 열을 냈다. 잉크를 거부하듯 잿물이 그 줄만 비켜 흘렀다.<br><br>자국이 살아 있다는 뜻이다. 소름이 손목까지 올라왔다.<br>잿물 대신 흙을 쥐고 다녔다. 밤마다 자국이 미지근해지는 게 느껴졌다. 누가 장부를 펼 때마다 그러는 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마력을 모아 자국을 태워 낸다.', k:'heal', dc:25, cost:{ mana:34 },
      ok:`손바닥에 마력을 모았다. 뜸을 뜨듯, 자국 줄만 따라 천천히 지졌다.<br><br>자국이 끓으며 엷어졌다. 마지막 한 마디가 유독 버텼다. 이를 물고 마저 지졌다.<br>손바닥에 가는 흉이 남았다. 흉은 표식이 아니다. 흉은 이쪽 글씨다. 남의 장부에서 제 이름을 제 손으로 지웠다.`,
      ng:`지지는데 자국이 마력을 마셨다. 뜨거워지라고 넣은 힘이 자국을 살찌웠다.<br><br>자국이 반 마디 길어졌다. 황급히 마력을 끊었다.<br>마력 쓸 때마다 자국이 반응한다는 걸 알았다. 점을 칠 때마다 저쪽 장부가 두꺼워진다는 소리다. 당분간 맨눈으로 살기로 했다. 점술가한테 그건 반쯤 눈 감고 사는 일이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-25 } }
  ] },

{ at:'S1', t:'표본실 — 빈 병의 괘',
  x:`표본 선반 앞에서 산가지를 던졌다. 어느 길이 비었는지 물었다.<br><br>
    다섯 개가 다 한 병을 가리켰다. 길이 아니라 병을.<br>
    선반 셋째 줄, 마개가 안에서 뚫린 빈 병. 금 간 유리에 마른 자국만 남았다.<br><br>
    괘가 길을 안 가리키고 병을 가리키는 건 처음이다. 비었다는 게 답인 것이다. 나온 것이 지금 길에 있다고.`,
  o:[
    { l:'① 빈 병 안을 들여다본다.', k:'gaze', dc:26,
      doom:{ title:'병의 임자', what:'병에서 나온 것에게 천장으로 끌려 올라갑니다', dc:20, sec:40,
        text:`병 안에 답이 더 있을 것 같았다. 등불을 들이대고 들여다봤다.<br><br>마른 자국, 뚫린 마개, 그리고 병 안쪽 유리에 비친 천장. 천장에 그것이 붙어 있었다.<br>제 병을 들여다보는 것을 그것도 내려다보고 있었다. 떨어진다. 어깨에 내려앉는다. 가볍다. 가벼운 것이 힘은 무쇠다. 천장 배관 사이로 끌려 올라간다. 제가 살던 병이 저 아래 작아진다.<br><br>괘는 병이 비었다고 세 번 말했다. 빈 집을 또 들여다본 건 이쪽 고집이다.`,
        dieText:`표본 선반 셋째 줄, 빈 병이 하나 있다.<br><br>병 안에 등불이 하나 켜진 채 서 있다.<br>천장 배관에서 마른 것이 한 방울 떨어져 병 어깨를 타고 흘렀다.` },
      ok:`들여다보기 전에 병 유리에 비치는 것부터 봤다. 점술가는 거울을 똑바로 안 본다. 비스듬히 본다.<br><br>유리 곡면에 천장이 비쳤다. 배관 사이, 숨처럼 부푸는 어두운 덩어리.<br>고개는 안 들었다. 들면 눈이 마주친다. 등불을 선반에 놓아 둔 채 그 빛을 미끼로 소리 없이 물러났다. 병이 가리킨 답은 다 받았다. 나온 것은 위에 있다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 빈 병의 마른 자국으로 크기를 잰다.', k:'luck', dc:25,
      ok:`병에 남은 자국의 둘레를 쟀다. 웅크렸던 크기. 뚫린 마개 구멍 지름. 빠져나간 몸통 굵기.<br><br>팔뚝만 하다. 팔뚝만 한 것이 다닐 틈을 셈하면 길이 나온다. 배관 밑과 격자 밑만 피하면 된다.<br>넓고 천장 높은 길만 골라 지났다. 좁은 틈에서 두 번, 무엇이 아쉬워하는 기척이 났다.`,
      ng:`자국을 재는데 옆 병들이 흔들리기 시작했다. 산 병들이 빈 병 쪽을 두드리는 것이다.<br><br>경고인지 인사인지 모를 소리가 커졌다. 유리 하나에 새 금이 갔다.<br>잰 것만 들고 서둘러 떴다. 등 뒤에서 두드림이 박자를 맞춰 갔다. 배웅치고는 고약했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S1', t:'통풍구 — 바람 점',
  x:`갈림마다 천장에 통풍구다. 어느 관이 비었고 어느 관에 그것이 사는지.<br><br>
    향을 꺼냈다. 연기는 드나드는 숨을 그린다.<br>
    첫 격자 밑에서 연기가 곧게 빨려 올라간다. 둘째 격자 밑에서는 연기가 밀려 내려온다.<br><br>
    빨아들이는 관과 내쉬는 관. 기계가 죽은 지 오래인데 숨이 남아 있다.`,
  o:[
    { l:'① 내쉬는 관 밑으로만 걷는다.', k:'luck', dc:25, wake:1,
      ok:`숨이 나오는 관은 그 속에 코가 있다는 뜻이다. 대신 내쉬는 숨은 냄새를 못 맡는다. 내쉴 때 그 밑을 지나면 코앞을 지나도 안 읽힌다.<br><br>연기로 내쉬는 박자를 재고, 내쉬는 동안만 격자 밑을 건넜다. 여섯 격자를 그렇게 끊어 지났다.<br>마지막 격자 위에서 그것이 숨을 들이켰을 때, 일행은 이미 다 지나 있었다. 들이켠 건 저희 숨이 데운 빈 공기뿐이다.<br><br>바람 점이 숨 점이 됐다. 보이지 않는 것의 코앞을 재는 점. 쓸 데가 많을 것이다.`,
      ng:`박자를 재는데 향이 다 탔다. 마지막 격자는 눈대중으로 건넜다.<br><br>눈대중이 반 박자 늦었다. 들이켜는 숨에 일행 끝 사람의 냄새가 걸렸다.<br>격자가 안에서 들썩였다. 떨어지는 격자를 등 뒤로 들으며 복도 끝까지 내달렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 마력 실은 연기를 관에 올려 보낸다.', k:'hide', dc:25, cost:{ mana:32 },
      ok:`향 연기에 마력을 실어 빨아들이는 관으로 올려 보냈다. 연기가 관을 타고 멀리, 다른 구역까지 흘러가도록.<br><br>관 속의 것이 그 냄새를 따라갔다. 긴 몸이 관을 긁으며 멀어지는 소리가 머리 위를 지나갔다.<br>빈 관 밑을 느긋하게 걸었다. 점술가의 연기가 오늘은 거짓 손님 노릇을 했다.`,
      ng:`마력 실은 연기가 너무 진했다. 관 속의 것이 되레 수상히 여겼다.<br><br>연기를 거슬러 내려왔다. 격자 틈으로 긴 것이 머리를 내밀고 연기 피운 자리를 노려봤다.<br>등불을 끄고 벽에 붙어 버텼다. 그것이 향로를 끌어 올려 가져갔다. 아끼던 향로였다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S1', t:'생존자 — 두 개의 맥',
  x:`구석에 웅크린 생존자를 찾았다. 숨은 붙어 있다. 열이 높다.<br><br>
    손목을 잡고 맥을 짚었다. 점술가의 맥 짚기는 의원과 다르다. 명을 읽는다.<br>
    맥이 둘이다. 하나는 사람 맥. 겁에 질려 빠르다. 하나는 그 밑에서, 느리고 고르게.<br><br>
    둘째 맥에는 명이 안 읽힌다. 명이 없는 것이 사람 속에서 제 박자로 살고 있다.`,
  o:[
    { l:'① 맥으로 둘째 것의 때를 읽는다.', k:'luck', dc:25, wake:1,
      ok:`둘째 맥을 오래 짚었다. 느리지만 조금씩 빨라지고 있다. 깰 때가 다가오는 맥이다. 이틀. 길어야 사흘.<br><br>사실대로 말했다. 그 사람은 오래 울고, 그리고 물었다. 이틀이면 걸어서 어디까지 가느냐고.<br>출구 쪽으로 가는 이틀 길을 같이 걸었다. 짐을 들어 주고, 밤에는 가장자리를 내주지 않았다. 이틀째 저녁, 그 사람은 제 발로 멀어졌다. 등이 꼿꼿했다.<br><br>명을 읽기만 하던 맥 짚기가, 남은 시간을 쥐여 주는 일이 됐다. 점술가가 줄 수 있는 제일 큰 것일지 모른다.`,
      ng:`때를 읽는데 둘째 맥이 짚는 손가락을 느꼈다. 맥이 멈칫, 하고 숨었다.<br><br>읽히는 걸 아는 것이다. 숨은 맥은 못 읽는다. 남은 때를 모르게 됐다.<br>그 사람에게는 열이 심하다고만 했다. 거짓말이 아닌 거짓말. 그날 밤 내내 그 사람 숨소리에 귀를 걸어 두고 설잠을 잤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-23 } },
    { l:'② 의원 맥으로 바꿔 열부터 내린다.', k:'heal', dc:24,
      ok:`명 읽기를 접고 열부터 잡았다. 물수건, 약초 달인 물, 조이는 옷 풀기.<br><br>열이 내리자 사람 맥이 힘을 찾았다. 둘째 맥이 상대적으로 묽어졌다.<br>숙주가 튼튼하면 속엣것이 서두르지 못한다는 말이 있다. 믿거나 말거나지만, 그 사람은 제 발로 걸을 만큼 기운을 차렸다. 시간은 벌었다.`,
      ng:`약초 달인 물을 넘기는데 그 사람이 왈칵 게웠다.<br><br>속엣것이 약을 거부하는 것이다. 두 번째도 게웠다.<br>약은 접고 미음만 끓여 먹였다. 속엣것 눈치를 보며 하는 간호는 간호가 아니라 흥정이었다. 밤이 길었다.`,
      win:{ exp:17, dream:2, hp:6 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 마력을 찔러 둘째 맥을 끊는다.', k:'break', dc:26, cost:{ mana:36 },
      doom:{ title:'깨어난 박자', what:'튀어나온 것에게 감겨 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`손끝에 마력을 바늘처럼 모아 둘째 맥의 박자 사이를 찔렀다.<br><br>맥이 끊기는 대신 뛰었다. 박자가 두 배로. 잠을 찔러 깨운 것이다.<br>그 사람 몸이 활처럼 꺾이고, 속엣것이 밖으로 나왔다. 예정보다 일찍, 화가 난 채로. 제일 가까운 것부터 감았다. 마력 냄새가 나는 이쪽부터. 감긴 채 어둠으로 끌려간다. 뒤에서 그 사람의 울음이 들렸다. 살아 있다. 그것만 셈에 넣기로 했다.<br><br>명 없는 것의 맥은 끊는 게 아니라 비켜 가는 것이다. 수업료가 너무 비쌌다.`,
        dieText:`구석에 생존자가 웅크려 있다. 숨이 붙어 있다.<br><br>열이 내렸다. 맥도 하나뿐이다.<br>다만 그 사람은 어둠 쪽을 보며 자꾸 미안하다고 한다.` },
      ok:`마력 바늘을 맥 사이에 넣고, 끊는 대신 아주 느리게 식혔다. 겨울잠을 재우듯.<br><br>둘째 맥이 반 박자, 또 반 박자 느려졌다. 깰 때가 그만큼 밀렸다.<br>이틀이 이레가 됐다. 이레면 출구까지 데려다줄 수 있다. 바늘을 뽑은 손끝이 밤새 시렸다. 남의 겨울을 손끝에 옮겨 온 것처럼.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S1', t:'산성 — 녹는 산가지',
  x:`바닥 핏자국이 아직 김을 올린다. 그것들의 피는 쇠도 돌도 먹는다.<br><br>
    언제 적 피인지 알면 싸움이 얼마나 가까운지 안다.<br>
    산가지 하나를 꺼냈다. 점치는 막대로 할 일은 아니지만, 여기서는 이것도 점이다.<br><br>
    담가 본다. 끓는 꼴이 곧 괘다.`,
  o:[
    { l:'① 녹는 빠르기로 피의 나이를 잰다.', k:'luck', dc:25,
      ok:`산가지 끝을 자국에 댔다. 치익, 연기 한 줄. 끝이 뭉툭해지는 데 열 숨.<br><br>갓 흘린 피는 세 숨이면 먹는다. 열 숨이면 반나절 묵은 피다. 싸움은 반나절 밖이다.<br>녹다 만 산가지는 이가 빠진 채로도 괘를 던질 수 있다. 오늘부터 이 녀석 이름은 약점이다. 녹은 자리가 가리키는 괘만 유독 잘 맞았다.`,
      ng:`담근 산가지가 생각보다 빨리 먹혔다. 세 숨 만에 반 토막.<br><br>새 피다. 싸움이 골목 하나 밖이라는 뜻이다. 그리고 반 토막 나며 튄 방울이 소매에 앉았다.<br>소매를 찢어 던지는 사이 골목 저쪽에서 싸움 소리가 이쪽으로 굴러왔다. 토막 난 산가지를 쥐고 반대로 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-17 } },
    { l:'② 김의 방향으로 바람길을 읽는다.', k:'sense', dc:24,
      ok:`자국마다 오르는 김이 다 같은 쪽으로 기운다. 공기가 흐르는 쪽. 숨통이 있는 쪽이다.<br><br>김이 가리키는 길로 잡았다. 반 시진 뒤 무너진 벽 틈에서 바깥 공기 냄새가 났다.<br>피 끓는 김으로 숨길을 읽었다. 궂은 재료로 좋은 점을 쳤다. 스승 말이 맞았다. 점쟁이한테 궂은 재료란 없다.`,
      ng:`김을 좇아 갔는데 김이 모이는 데는 숨통이 아니라 싸움터 한복판이었다.<br><br>두 그것이 서로 물고 뒹군 자리. 피가 사방에서 끓고 있었다.<br>김이 눈을 가리는 사이를 더듬어 물러났다. 신발 밑창이 반쯤 녹아 걸음마다 쩍쩍 소리가 났다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'에어록 — 열릴 때를 센다',
  x:`에어록이 저 혼자 여닫힌다. 남은 동력이 도는 대로, 제멋대로의 간격으로.<br><br>
    열린 틈에 끼면 반으로 접힌다. 문턱에 눌린 자국들이 그 끝을 보여 준다.<br>
    시계는 없다. 간격은 눈과 맥으로 재는 수밖에.<br><br>
    문 너머에서 가끔 긴 것이 지나가는 그림자가 비친다. 문만 재서 될 일이 아니다.`,
  o:[
    { l:'① 마력을 문 너머로 흘려 기척을 짚는다.', k:'gaze', dc:25, cost:{ mana:35 },
      ok:`손바닥을 문에 대고 마력을 실처럼 흘려 넣었다. 문 너머 공기의 결이 손에 돌아온다.<br><br>너머는 비었다. 긴 것은 방금 지나갔고, 걸음 결이 멀어지는 쪽이다.<br>문이 열린 숨에 다 같이 건넜다. 문이 등 뒤에서 닫히며 바람을 밀어냈다. 마력 한 줌으로 산 확신이다. 싸게 샀다.`,
      ng:`마력 실이 문 너머에서 툭 끊겼다. 무엇이 물었다는 뜻이다.<br><br>너머의 것이 문에 바짝 붙었다. 유리에 김이 서렸다 걷혔다 했다.<br>마력을 끊고 물러나 다음 들숨까지 한참을 기다렸다. 그것이 흥미를 잃고 떠난 뒤에야 건넜다. 물린 마력 자리가 하루 종일 저릿했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 제 맥으로 여닫는 간격을 센다.', k:'steady', dc:24,
      ok:`손목을 쥐고 맥으로 쟀다. 열림이 맥 마흔, 닫힘이 맥 백이십. 세 번을 재니 셈이 섰다.<br><br>마흔 안에 둘씩. 세 번에 나눠 다 건넜다.<br>마지막 조가 건널 때 간격이 흔들렸지만 여유를 둔 셈이라 닿지 않았다. 몸이 시계가 되는 법을 다들 하나씩 배웠다.`,
      ng:`맥이 겁을 먹어 빨라졌다. 빠른 맥으로 잰 마흔은 실제보다 짧다.<br><br>둘째 조가 건널 때 문이 예상보다 일찍 울었다. 마지막 사람이 몸을 날려 굴렀다.<br>문짝이 뒤꿈치를 스치고 닫혔다. 신발 뒤축이 문턱에 남았다. 셈은 침착을 먹고 자란다. 배웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S1', t:'깊은 방 — 같은 꿈',
  x:`아래층으로 내려온 첫 밤, 일행이 다 같은 꿈을 꿨다.<br><br>
    따뜻하고 어둡고 젖은 방. 돌아가고 싶은 데 없이 편안한. 깨고 나서 서로 말을 맞춰 보고 다들 질렸다.<br>
    꿈이 같다는 건 꿈이 밖에서 왔다는 것이다. 아래 깊은 데서 무엇이 꿈을 내쉬고 있다.<br><br>
    부르는 꿈이다. 점술가는 꿈의 결을 안다. 이건 그물의 결이다.`,
  o:[
    { l:'① 꿈에 표를 심어 둔다.', k:'luck', dc:25, wake:1,
      ok:`자기 전에 일행마다 손바닥에 매운 재를 쥐여 줬다. 꿈이 너무 편안해지면 손을 쥐라고. 아픔은 이쪽 것이다. 꿈은 남의 것이고.<br><br>밤중에 하나둘 제 손에 깼다. 깬 사람이 옆 사람을 깨웠다.<br>새벽에 보니 다들 잠자리가 아래층 쪽으로 반 뼘씩 끌려 있었다. 자면서 기어간 것이다. 재 한 줌이 그 반 뼘에서 다들 멈춰 세웠다.<br><br>남의 꿈에 이쪽 물건을 심는 법을 익혔다. 꿈을 읽는 것과 꿈에서 지는 것은 다른 일이다.`,
      ng:`재를 쥐여 줬는데 꿈이 더 영리했다. 꿈속에서 재가 꽃가루가 됐다.<br><br>아무도 제 손에 안 깼다. 보초 선 이쪽이 하나씩 흔들어 깨웠다.<br>마지막 사람은 벌써 일어나 걷고 있었다. 눈을 감은 채. 붙들어 눕히는 데 셋이 들었다. 그날 밤부터 잠은 교대로, 반씩만 잤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 꿈을 따라 들어가 그물을 본다.', k:'gaze', dc:26,
      doom:{ title:'젖은 방', what:'잠든 채 걸어 아래로 끌려 내려갑니다', dc:20, sec:45,
        text:`알고 당하는 건 당하는 게 아니라고 생각했다. 일부러 그 꿈에 들어갔다. 그물을 보려고.<br><br>따뜻하고 어둡고 젖은 방이 열렸다. 결을 더듬어 안쪽으로. 방 한가운데에 숨 쉬는 큰 어둠이 있고, 그 둘레에 사람들이 누워 있었다. 편안한 얼굴로. 아는 얼굴도 있었다.<br>그쪽으로 한 걸음 가는데 몸이 무거웠다. 꿈 밖의 몸이 벌써 걷고 있어서였다. 눈 감은 채, 아래층 계단을. 꿈 안에서는 알면서도 발이 돌아서지 않았다.<br><br>그물을 보려면 그물에 앉아야 한다. 그 값을 셈에 안 넣었다.`,
        dieText:`잠자리 하나가 비었다.<br><br>이불이 걷힌 결이 곱다. 급하게 나간 자리가 아니다.<br>맨발 자국이 아래층 계단 쪽으로 가지런히 이어진다.` },
      ok:`들어가되 끈을 맸다. 제 발목과 바위에, 진짜 밧줄로. 꿈은 몸을 끌지만 밧줄은 꿈을 모른다.<br><br>꿈속 젖은 방의 결을 읽었다. 그물코가 성긴 데가 있다. 숨을 내쉬는 박자. 내쉴 때는 부르는 힘이 준다.<br>깨서 그 박자를 적었다. 내쉬는 박자에만 자고, 들이쉬는 박자에는 깨어 있기로 짰다. 발목의 밧줄 자국이 벌겋게 남았다. 싼 값이다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S1', t:'수조 — 수면에 비친 것',
  x:`방 한가운데 큰 수조가 금 간 채 서 있다. 물이 반쯤 남았다.<br><br>
    수면이 거울처럼 고요하다. 점술가에게 고인 물은 수경이다. 물에 비친 것을 읽는 점.<br>
    수면에 천장이 비친다. 배관, 등불 그림자, 그리고 배관 사이의 긴 어둠.<br><br>
    그 어둠에 결이 있다. 비늘의 결이.`,
  o:[
    { l:'① 수면을 비스듬히 읽는다.', k:'luck', dc:25,
      ok:`수조에 다가가지 않고 비낀 각도에서 수면을 읽었다. 배관 사이 어둠이 숨 박자로 부푼다. 꼬리 끝이 등불 그림자에 반 뼘 걸렸다.<br><br>길이를 셈하니 방을 가로지르고 남는다. 천장 밑은 전부 그것의 손안이다.<br>벽에 붙어, 책장 밑으로, 수조 그늘로. 천장에서 먼 길만 이어 밟았다. 나가는 문턱에서 수면이 한 번 일렁였다. 그것이 자리를 옮긴 것이다. 이미 늦었다. 이쪽이 먼저 나왔다.`,
      ng:`비스듬히 읽는데 수면에 이쪽 등불이 같이 비쳤다. 빛이 천장까지 어른거렸다.<br><br>배관 사이 어둠이 빛을 따라 고개를 틀었다. 읽는 걸 읽힌 것이다.<br>등불을 끄고 수조 뒤에 숨었다. 천장에서 물방울 떨어지는 소리가 수조를 세 바퀴 돌고 멀어졌다. 침이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 수조에 바짝 붙어 들여다본다.', k:'gaze', dc:26,
      doom:{ title:'수경 너머', what:'천장의 것에게 낚여 끌려 올라갑니다', dc:20, sec:40,
        text:`더 자세히 읽으려고 수조에 붙었다. 수면 가득 천장이 비친다. 배관, 어둠, 결.<br><br>결이 또렷해질수록 뭔가 이상했다. 비친 어둠이 커지고 있었다. 수면 가득, 점점.<br>비친 것이 커지는 건 내려오고 있다는 것이다. 수경 점의 기본인데, 읽는 데 취해 늦었다. 등짝을 집혀 올라간다. 수면에 제 얼굴이 멀어지는 게 비쳤다. 그것도 읽었다. 겁에 질린 상이었다.<br><br>점괘에 취하지 말 것. 첫 스승의 첫 가르침이 마지막에 떠올랐다.`,
        dieText:`금 간 수조에 물이 반쯤 남아 있다.<br><br>수면이 거울처럼 고요하다.<br>천장 배관에 등불 하나가 걸려 아직 흔들린다.` },
      ok:`붙어 읽다가 수면의 어둠이 부푸는 걸 봤다. 커진다. 내려온다.<br><br>읽던 것을 끝까지 안 읽고 수조 밑으로 굴렀다. 머리 위에서 무엇이 수조 테를 치는 소리.<br>수조가 울고 물이 쏟아졌다. 젖은 채 문까지 기었다. 수경 점은 반만 읽어도 산다. 끝까지 읽으면 못 산다. 여기 점은 다 그렇다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'울타리 — 눈을 세는 괘',
  x:`울타리 안쪽에서 산가지를 던졌다. 바깥 수풀에 몇이 와 있는지.<br><br>
    다섯 중 넷이 섰다. 넷. 어제는 둘이었다.<br>
    서는 산가지가 늘어 간다. 구경꾼이 느는 것이다. 울타리 너머에서, 참을성 있게.<br><br>
    괘는 수만 준다. 때는 안 준다. 때는 저쪽이 정한다.`,
  o:[
    { l:'① 산가지 수가 주는 쪽으로 움직인다.', k:'luck', dc:25, wake:1,
      ok:`울타리를 따라 걸으며 백 걸음마다 던졌다. 넷, 넷, 셋, 둘. 수가 주는 쪽으로 계속.<br><br>하나가 선 자리에서 울타리를 넘었다. 하나는 셋보다 수가 보인다. 눈 하나는 늙은 것이었다. 이빨이 닳아 무리에서 밀려난. 서로 못 본 척하고 지나쳤다.<br>넘고 나서 뒤를 보니 넷 선 쪽 수풀이 그제야 흔들리고 있었다. 늦게 온 소식에 허탕 친 것이다.<br><br>괘로 포위의 숨은 결을 그렸다. 수를 세는 점이 자리를 고르는 점이 됐다.`,
      ng:`수가 주는 쪽으로 가는데 마지막 백 걸음에서 다섯이 다 섰다.<br><br>주는 게 아니라 몰리는 것이었다. 이쪽 걸음을 따라 옮겨 온 것이다.<br>괘고 뭐고 왔던 길을 되짚어 뛰었다. 산가지 다섯을 그 자리에 쏟은 채였다. 주우러 못 갔다. 이틀 뒤 지나며 보니 다섯 다 누군가의 발에 밟혀 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 선 산가지 앞에 미끼 괘를 차린다.', k:'hide', dc:24,
      ok:`넷이 선 쪽 울타리 안에 등불 하나와 외투 한 벌을 세워 뒀다. 사람 꼴로.<br><br>구경꾼들의 눈을 그 자리에 묶어 두고, 반대쪽으로 다 빠졌다.<br>멀리서 보니 수풀 넷이 밤새 그 등불만 보고 있었다. 괘를 저쪽에게도 던져 준 셈이다. 가짜 괘를.`,
      ng:`외투 허수아비가 바람에 쓰러졌다. 쓰러지는 꼴이 너무 사람 같았다.<br><br>넷이 일제히 울타리를 밀었다. 낡은 칸 하나가 넘어갔다.<br>쓰러진 가짜에 코를 박는 넷을 뒤로하고 내달렸다. 등불과 외투 값으로 샛길 하나를 샀다. 비싼 샛길이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'물 양치밭 — 숨거품 점',
  x:`잠긴 양치밭을 건너야 한다. 수면 군데군데 거품이 올라와 터진다.<br><br>
    바닥에 엎드린 것들의 숨이다. 거품 하나에 숨 하나.<br>
    거품 사이 간격이 그것들의 숨 간격이다. 내쉬고 다시 내쉬기까지, 그 사이가 길의 틈이다.<br><br>
    물점 치던 눈으로 거품을 센다. 오늘 수경은 발밑에 깔려 있다.`,
  o:[
    { l:'① 거품 간격을 세어 틈으로 건넌다.', k:'luck', dc:26,
      doom:{ title:'참은 숨', what:'물밑의 것에게 끌려 가라앉습니다', dc:20, sec:40,
        text:`거품 자리 셋을 피해 길을 긋고, 숨 간격마다 끊어 건넜다.<br><br>복판에서 거품 하나가 셈에서 사라졌다. 숨이 끊긴 게 아니다. 참은 것이다.<br>숨을 참는 건 듣고 있다는 것이다. 다음 걸음에 발목이 잡혔다. 물이 뒤집히고, 양치잎이 머리 위에서 닫힌다. 마지막으로 뱉은 숨이 거품이 되어 올라갔다. 저 거품은 누가 세어 줄까, 그런 생각이 났다.<br><br>거품은 다 셌다. 거품을 안 내는 수까지는 못 셌다.`,
        dieText:`양치밭 수면에 거품이 하나 올라와 터졌다.<br><br>간격을 두고 또 하나.<br>세던 사람이 없어 간격은 아무도 모른다.` },
      ok:`거품 셋의 간격을 다 외우고, 셋이 다 내쉰 직후의 겹치는 틈만 골라 건넜다.<br><br>세 번 끊고 네 번째에 뭍이었다. 마지막 걸음에서 등 뒤 거품 하나가 길게, 화난 듯 끓었다.<br>늦게 눈치챈 것이다. 수경 점 삼십 년에 제일 큰 판이었다. 발이 마른 땅을 밟자 무릎이 한 번 꺾였다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 마력으로 수면을 재워 바닥을 비춘다.', k:'gaze', dc:25, cost:{ mana:34 },
      ok:`손바닥을 수면에 펴고 마력을 깔았다. 물결이 죽고 수면이 유리가 됐다.<br><br>바닥이 비쳤다. 엎드린 것 셋. 긴 것 하나는 거품 자리에서 멀리, 양치 뿌리 사이에 따로 있었다. 거품 셈에 안 잡히던 놈이다.<br>넷을 다 피하는 길을 그어 단숨에 건넜다. 유리 같던 수면이 등 뒤에서 도로 일렁이기 시작했다.`,
      ng:`마력 깐 수면이 너무 고요해졌다. 물밑 것들이 그 고요를 수상해했다.<br><br>셋이 동시에 고개를 들었다. 수면 밑에서 올려다보는 여섯 눈과 눈이 마주쳤다.<br>마력을 걷고 물가를 따라 먼 길로 돌았다. 한나절이 더 들었다. 물은 끝까지 안 믿는 눈으로 등 뒤에서 출렁였다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-23 } }
  ] },

{ at:'S2', t:'큰 것 — 물잔 괘',
  x:`물을 떠 놓은 잔이 운다. 가늘게, 동그란 무늬를 그리며.<br><br>
    큰 것이 걷고 있다. 멀리서. 잔의 무늬는 가장 오래된 점괘다. 울림은 거짓말을 못 한다.<br>
    무늬가 굵어지면 가까워지는 것이고, 한쪽이 먼저 일그러지면 그쪽에서 오는 것이다.<br><br>
    잔을 바닥에 놓고 다들 그 둘레에 모였다. 점집 차린 꼴이 됐다.`,
  o:[
    { l:'① 무늬의 결로 길과 때를 뽑는다.', k:'luck', dc:25,
      ok:`무늬를 읽었다. 왼쪽이 먼저 일그러진다. 왼쪽에서 온다. 굵어지는 빠르기로 치면 밥 한 끼 지을 시간.<br><br>오른쪽 바위 등성이로 피했다. 한 끼 시간이 지나자 왼쪽 숲이 통째로 휘며 그것이 지나갔다.<br>잔의 물이 반이나 튀어 오르는 울림이었다. 잔 하나로 산 한 채만 한 것을 피했다. 점값 치고 이보다 싼 적이 없었다.`,
      ng:`무늬가 갑자기 사방에서 일그러졌다. 방향이 안 잡힌다.<br><br>메아리다. 골짜기가 울림을 되던지고 있었다.<br>잔을 버리고 높은 바위로 붙었다. 그것은 생각보다 가까운 데를 지나갔다. 잔이 있던 자리가 그 발에 밟혀 사라졌다. 무늬 탓이 아니다. 자리 탓이다. 골짜기에서는 점도 메아리를 탄다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-21 } },
    { l:'② 울림이 멎는 자리를 찾아 숨는다.', k:'steady', dc:24,
      ok:`잔을 들고 걸으며 무늬가 제일 잔잔해지는 자리를 찾았다. 바위 뿌리가 깊은 곳. 울림이 땅속으로 빠지는 자리다.<br><br>거기 엎드렸다. 그것이 지나는 동안 잔의 물은 가늘게만 떨렸다.<br>울림의 그늘이라는 게 있다. 잔이 가르쳐 줬다. 다음에도 쓸 수 있는 자리다. 잊지 않게 돌 세 개를 포개 두었다.`,
      ng:`잔잔한 자리를 찾아 도는 사이 울림이 너무 커졌다. 잔이 통째로 넘어졌다.<br><br>점괘가 엎질러졌다. 맨몸으로 울림 속에 섰다.<br>제일 가까운 바위 틈에 다들 끼어 들어갔다. 그것이 지나가며 문 나무 하나가 바위 위로 쓰러졌다. 부러진 가지 사이로 하늘이 조각나 보였다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'알 무덤 — 둥지 태점',
  x:`김 오르는 알 무덤을 지나야 한다. 어미의 순찰 간격이 문제다.<br><br>
    태점은 알의 맥만 읽는 게 아니다. 품은 쪽의 정성도 읽는다.<br>
    무덤 흙이 뒤집힌 결을 봤다. 알을 굴려 뒤집어 준 자국. 겉이 마른 정도가 세 켜.<br><br>
    품는 데는 시간표가 있다. 시간표가 있으면 틈도 있다.`,
  o:[
    { l:'① 뒤집은 자국으로 순찰 틈을 잰다.', k:'luck', dc:25,
      ok:`맨 위 자국은 촉촉하고, 그 밑은 꾸덕하고, 맨 밑은 말랐다. 반나절에 한 번 도는 어미다. 맨 위가 마르기 시작했으니 지금이 틈의 한복판이다.<br><br>무덤에서 제일 먼 가장자리로, 바람 아래로, 틈의 반만 쓰고 건넜다. 남은 반은 여유분이다.<br>다 건너고 반 식경 뒤 어미가 돌아오는 울림이 왔다. 여유분까지 쓰고도 남는 셈이었다. 태점은 알만 보는 점이 아니다. 어미를 보는 점이다.`,
      ng:`자국 켜를 재는데 위에서 그늘이 덮였다. 구름이 아니었다.<br><br>순찰이 아니라 마중이었다. 알 곁에 바짝 붙은 낯선 냄새를 맡고 일찍 돌아온 것이다.<br>무덤을 등지고 가시덤불로 뛰어들었다. 어미는 덤불까지는 안 쫓았다. 알 곁을 오래 못 비우는 것이다. 그 셈 하나로 살았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 무덤 둘레에 제 냄새를 안 남기고 돈다.', k:'hide', dc:24,
      ok:`신발을 벗어 목에 걸고, 발에 진흙을 발랐다. 걸음마다 젖은 흙이 냄새를 덮는다.<br><br>무덤 가장자리를 짐승 발자국 위로만 밟아 돌았다. 남의 자국에 얹힌 자국은 자국이 아니다.<br>다 돌고 물가에서 발을 씻었다. 어미의 저녁 순찰은 아무것도 모른 채 지나갔을 것이다. 모르게 하는 것이 제일 깊은 점이다.`,
      ng:`진흙이 마르며 발바닥이 텄다. 갈라진 데로 피가 한 방울 흙에 닿았다.<br><br>한 방울이면 충분한 코가 있다. 저녁에 무덤 쪽에서 낮게 으르는 소리가 바람을 타고 왔다.<br>밤새 두 번 자리를 옮겼다. 피 한 방울 값이 잠 한 밤이었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'S2', t:'급이대 — 거짓 징조',
  x:`빈터의 급이대 종이 저 혼자 울렸다. 뎅. 바람은 없다.<br><br>
    일행이 수군댄다. 징조라고. 죽은 사육사들이 알려 주는 거라고.<br>
    점술가는 종 줄을 봤다. 줄 끝이 수풀로 이어져 있고, 수풀 그늘에서 그 줄을 쥔 것의 눈이 반짝인다.<br><br>
    징조가 아니다. 미끼다. 종을 치면 뭐가 오는지 아는 것이 치고 있다.`,
  o:[
    { l:'① 거짓 징조를 거짓으로 되받는다.', k:'luck', dc:25, wake:1,
      ok:`종이 또 울렸다. 이쪽은 가지 않았다. 대신 돌을 들어 빈터 건너 바위를 쳤다. 깡. 종과 다른 소리를, 다른 자리에서.<br><br>줄 쥔 것이 혼란에 빠졌다. 미끼를 무는 쪽이 딴 미끼를 던진 것이다.<br>그것이 바위 쪽을 살피러 수풀을 나선 사이, 빈터를 반대로 질렀다. 지나며 보니 종 밑에 뼈가 수북했다. 징조를 믿은 것들의 뼈다.<br><br>징조와 미끼를 가르는 눈. 점술가가 여기서 벌어 가는 것 중 제일 비싼 것이다.`,
      ng:`돌 소리를 냈는데 그것이 안 속았다. 종만 다시 울렸다. 뎅. 뎅. 재촉하듯.<br><br>소리 싸움에서 밀린 것이다. 저쪽 종이 더 크고 멀리 간다.<br>종소리에 몰려드는 것들이 빈터를 채우기 전에 가장자리 덤불로 돌았다. 가시에 뜯기며 반 바퀴. 종은 등 뒤에서 오래 울렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 줄 쥔 것의 눈을 마주 본다.', k:'gaze', dc:25,
      ok:`수풀 그늘의 눈을 정면으로 봤다. 봤다는 걸 알게끔, 오래.<br><br>미끼는 들키면 끝이다. 줄이 스르륵 놓였다. 눈이 그늘 깊이 물러났다.<br>종은 더 안 울렸다. 낚시꾼은 낚시터를 옮긴다. 옮긴 자리가 어디인지는 모르지만, 적어도 이 빈터는 오늘 비었다.`,
      ng:`마주 본 게 셈 밖의 수를 불렀다. 그것이 줄을 놓는 대신 종을 미친 듯이 흔들었다.<br><br>들킨 낚시꾼이 판을 엎은 것이다. 사방에서 몰려드는 소리.<br>빈터를 포기하고 왔던 길로 물러났다. 한나절을 돌았다. 눈싸움에 이기고 길을 잃었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S2', t:'관리인 일지 — 마지막 장',
  x:`오두막 일지의 마지막 장이 비어 있다. 쓰다 만 문장 하나뿐.<br><br>
    「놈들이 울타리를 넘으면 나는 」<br>
    그 뒤가 없다. 관리인이 어디로 갔는지, 어디로 가려 했는지.<br><br>
    점술가는 물건에 남은 손길을 읽는 법을 안다. 마지막으로 쥔 사람의 마지막 마음이 밴 물건이면 더.`,
  o:[
    { l:'① 일지에 마력을 얹어 마지막 손길을 읽는다.', k:'gaze', dc:25, cost:{ mana:34 },
      ok:`일지 위에 손바닥을 얹고 마력을 스몄다. 마지막 장을 쓰던 손의 결이 올라온다.<br><br>펜을 놓고, 벽의 지도를 뜯고, 남쪽 바위 수로 쪽으로 달려 나간 결. 수로. 물이 마른 낡은 수로가 남쪽 벽까지 이어져 있다는 것이다.<br>지도 뜯긴 자리에 남은 압흔을 베꼈다. 관리인이 마지막에 건 길이면, 여기서 제일 믿을 만한 길이다. 그가 거기 닿았기를. 베낀 손이 잠깐 기도가 됐다.`,
      ng:`마력을 스미는데 손길의 결이 중간에 뚝 끊겼다. 끊긴 자리에 남은 건 공포뿐이었다.<br><br>쓰다가 창밖의 무엇을 본 것이다. 그 뒤의 결은 없다. 문장이 비었듯이.<br>읽다 만 공포가 이쪽 손에 옮아 한참 떨렸다. 일지를 덮고 오두막을 나왔다. 창밖 그 자리에 서 보지는 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 일지의 앞장들에서 버릇을 읽는다.', k:'sense', dc:24,
      ok:`마지막 장은 접고 앞장들을 읽었다. 관리인은 꼼꼼했다. 비 오는 날은 무리가 울타리 서쪽을 민다. 더운 날은 물가에서 안 떠난다. 큰 것이 지나면 하루는 다들 조용하다.<br><br>남의 삼 년 치 눈을 하루에 얻었다.<br>그날부터 일지의 버릇대로 길을 짰다. 죽은 사람의 꼼꼼함이 산 사람들의 지도가 됐다.`,
      ng:`앞장을 읽는 데 해가 졌다. 오두막에서 등불을 켠 게 실수였다.<br><br>창에 비친 불빛을 보고 무엇이 왔다. 창틀에 코 미는 소리.<br>등불을 끄고 바닥에 엎드려 일지를 품었다. 그것이 문을 두 번 밀고 갔다. 일지값으로 하룻밤 간이 졸아들었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 오르내림 괘',
  x:`낡은 승강기 앞에서 마지막 괘를 던졌다. 오르느냐, 기다리느냐.<br><br>
    산가지 다섯이 다 가로로 누웠다. 오르라는 꼴도, 내리라는 꼴도 아니다. 누워서 기다리는 꼴.<br>
    지금 말고. 그렇게 읽힌다.<br><br>
    일행은 당장 타고 싶어 한다. 승강기 통로가 크게 비어 있고, 빈 것이 수상하다.`,
  o:[
    { l:'① 괘대로 엎드려 때를 기다린다.', k:'luck', dc:25, wake:1,
      ok:`일행을 눌러 앉히고 바위 뒤에 엎드렸다. 괘가 눕자면 눕는 것이다.<br><br>반 식경 뒤 땅이 울렸다. 큰 것이 승강기 통로 곁을 지나갔다. 통로의 빈 바람이 그것의 길목이었던 것이다. 타고 오르던 중이었으면 흔들리는 쇠 상자 속에서 그 발소리를 들었을 것이다.<br>울림이 다 멀어진 뒤에 탔다. 승강기는 낡은 소리를 내며, 그러나 아무 일 없이 올랐다.<br><br>점술가의 마지막 공부는 기다림이라던 스승 말이 괘 하나로 끝났다. 눕는 괘를 읽는 눈이 아니라 따르는 무릎이 생겼다.`,
      ng:`기다리는데 일행 하나가 참지 못하고 승강기 격자문을 먼저 열었다. 쇳소리가 통로를 타고 위아래로 울렸다.<br><br>빈 통로가 갑자기 바빠졌다. 위에서 긁는 소리, 아래에서 치받는 울림.<br>문을 도로 닫고 다들 바위 뒤로 물러났다. 때는 두 식경 뒤에야 다시 왔다. 누운 괘를 반만 믿은 값이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 통로에 돌을 떨어뜨려 아래를 묻는다.', k:'sense', dc:24,
      ok:`격자 틈으로 돌을 떨어뜨렸다. 소리가 한참 만에 바닥을 쳤다. 그리고 조용했다. 되받는 기척이 없다.<br><br>아래는 비었다. 위만 재면 된다. 줄을 흔들어 보고 도르래를 살폈다.<br>괘와 돌이 같은 답을 줬다. 점과 눈이 겹치면 그건 그냥 사실이다. 탔다.`,
      ng:`돌이 바닥을 치자 아래에서 되받는 소리가 올라왔다. 돌 구르는 소리. 이쪽이 던진 돌을 굴려 보는 소리.<br><br>아래에 줍는 것이 산다.<br>승강기가 오르는 내내 바닥 틈으로 아래만 봤다. 어둠이 따라 올라오는 것 같아서. 다 오르고 격자문을 잠그고서야 숨을 돌렸다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] }

]);

// ==========================================
// 📦 수집가 (collector) · 자원 없음
// ==========================================
kJob('collector', 'S', [

{ at:'S', t:'입구 — 처음 보는 깃',
  x:`문턱 안쪽 바닥에 깃 같은 것이 떨어져 있다. 깃이라기엔 억세고, 비늘이라기엔 결이 있다.<br><br>
    수집가의 머릿속 서랍을 다 뒤졌다. 없다. 어느 칸에도 없는 물건.<br>
    처음 보는 깃은 처음 보는 임자가 있다는 뜻이다.<br><br>
    집어 들기 전에, 버릇대로, 감정부터 시작한다.`,
  o:[
    { l:'① 결과 닳음새로 임자를 그려 본다.', k:'luck', dc:25, wake:1,
      ok:`뿌리 쪽이 무르고 끝이 성하다. 갓 돋았다 빠진 것. 어린것의 깃이다.<br><br>어린것이 다닌다는 건 둥지가 가깝고 어미가 돈다는 것이다. 깃이 떨어진 결은 문에서 안쪽으로. 어린것이 들어간 방향이다.<br>그 방향만 피해 길을 잡았다. 밤에 안쪽 멀리서 어미가 새끼를 부르는 소리를 들었다. 피한 길이 맞는 길이었다.<br><br>모르는 물건에서 임자의 나이와 집까지 읽었다. 수집이 사냥 공부가 되는 데는 반나절이면 족했다.`,
      ng:`감정에 너무 몰두했다. 쪼그려 앉은 등 뒤로 그림자가 지나갔다.<br><br>어린것이었다. 제 깃을 들고 있는 이쪽을 한참 보다가 어둠으로 들어갔다.<br>본 것은 말을 한다. 제 어미에게. 깃을 내려놓고 서둘러 떴다. 그날 내내 등 뒤에서 작은 발소리가 따라오다 말다 했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-21 } },
    { l:'② 챙겨 넣고 길을 서두른다.', k:'evade', dc:24,
      ok:`천에 싸서 품에 넣었다. 감정은 걸으면서도 한다.<br><br>걸으며 만져 본 결로 두 가지는 알았다. 어린것의 것이고, 빠진 지 하루 안쪽이다.<br>하루 안쪽 물건의 임자는 하루 안쪽에 있다. 걸음을 배로 늘려 그 하루 밖으로 나갔다.`,
      ng:`품에 넣은 깃이 걸을 때마다 가슴을 찔렀다. 억센 깃이다.<br><br>찔린 자리가 가렵더니 부어올랐다. 깃 뿌리에 뭐가 묻어 있던 모양이다.<br>깃은 결국 버렸다. 부은 자리는 사흘 갔다. 수집의 첫 규칙을 어긴 값이다. 모르는 것은 맨살에 안 댄다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'이빨 — 빠진 이 줍기',
  x:`길바닥에 이빨이 떨어져 있다. 손가락만 하다. 열 걸음 가서 또 하나. 또 하나.<br><br>
    주워 모아 손바닥에 놓고 봤다. 같은 짐승 것이다. 다만 나이가 다르다. 젖니, 갈이 난 이, 다 자란 이.<br>
    한 마리가 평생 이 길에 이를 빠뜨리며 다녔다는 것이다.<br><br>
    평생 다닌 길이면 지금도 다니는 길이다.`,
  o:[
    { l:'① 이빨 나이 순으로 길의 방향을 읽는다.', k:'luck', dc:25,
      ok:`젖니가 떨어진 쪽이 옛날 길, 다 자란 이가 떨어진 쪽이 요즘 길이다. 요즘 길 쪽 이가 점점 굵어진다.<br><br>굵어지는 방향이 그놈의 집 쪽이다. 반대로 걸었다.<br>이빨 셋은 챙겼다. 젖니부터 셋, 한 짐승의 평생이 주머니에 들었다. 임자를 안 만나는 조건으로만 값진 수집품이다.`,
      ng:`나이 순을 맞추는데 마지막 이빨이 이상했다. 다 자란 이인데 금이 가 있다.<br><br>늙어서 이가 상하기 시작한 것이다. 이 상한 포식자는 사냥이 서툴러진다. 서툰 것이 제일 아무거나 문다.<br>걸음을 서두르는데 길 저쪽에서 쩝쩝대는 소리가 났다. 돌아서 크게 둘렀다. 서두른 반나절이 들었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 이빨을 하나 골라 날붙이로 벼린다.', k:'fix', dc:24,
      ok:`제일 성한 이빨을 골라 자루에 묶었다. 끝이 송곳 같다.<br><br>쓸모로 치면 칼보다 못하지만, 여기 것들 가죽에는 여기 것 이빨이 제일 잘 든다는 셈이 섰다.<br>나중에 덤불에 막혔을 때 그 이빨 송곳이 길을 텄다. 수집품이 연장이 되는 순간은 수집가만 아는 기쁨이다.`,
      ng:`벼리는 소리가 돌에 울렸다. 사각, 사각.<br><br>이 가는 소리와 닮은 소리다. 길 저쪽에서 진짜 이 가는 소리가 대답했다.<br>벼리다 만 이빨을 쥐고 자리를 떴다. 대답한 것이 제 이빨인 걸 알았는지는 모르겠다. 모르는 채이기를 빌었다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-15, spirit:-20 } }
  ] },

{ at:'S', t:'허물 — 연작 정리',
  x:`복도를 따라 허물이 널렸다. 아무렇게나 널린 것 같지만 수집가 눈에는 아니다.<br><br>
    연작이다. 같은 것이 벗은 가죽들. 순서가 흐트러졌을 뿐.<br>
    수집가는 연작을 보면 순서부터 맞춘다. 버릇이다.<br><br>
    순서가 맞으면 이야기가 나온다. 물건은 늘 이야기를 품고 있다.`,
  o:[
    { l:'① 벗은 순서대로 늘어세워 본다.', k:'luck', dc:25, wake:1,
      ok:`닳음새와 빛바램으로 순서를 세웠다. 첫째에서 넷째까지는 몸통이 곱절씩 늘었다. 그런데 다섯째가 이상하다. 넷째보다 작다.<br><br>자란 게 아니라 줄어든 것이다. 굶고 있다는 뜻이다. 여기 사냥감이 바닥났다는 뜻이고, 굶은 것이 못 먹던 것까지 먹기 시작할 때라는 뜻이다.<br>사람까지도. 일행을 재촉해 이 구역을 하루 만에 벗어났다.<br><br>연작의 순서에서 이야기를 읽는 눈이, 물건의 이야기에서 내일을 읽는 눈이 됐다.`,
      ng:`순서를 맞추느라 허물들을 끌어 옮겼다. 마른 가죽 끌리는 소리가 복도를 울렸다.<br><br>제 허물 끌리는 소리를 임자가 알아들었다.<br>복도 끝에서 되돌아오는 기척에 정리하던 연작을 그대로 두고 물러났다. 다섯 점 연작의 결말은 못 읽었다. 결말 쪽에서 이쪽을 읽으러 오고 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 제일 새 허물만 뒤집어 살핀다.', k:'sense', dc:24,
      ok:`맨 새것 안쪽을 봤다. 가죽 안벽에 돋은 결이 아직 축축하다. 벗은 지 한나절.<br><br>그리고 안벽 어깨 자리에 깊은 흉이 떠 있다. 다른 것에게 물린 자국. 이놈 위에 더 큰 놈이 있다는 수집품이다.<br>작은 것의 허물에서 큰 것의 존재를 읽었다. 공짜 정보치고 무거웠다.`,
      ng:`뒤집는데 허물 안쪽에 작은 것들이 붙어 있었다. 허물을 파먹는 벌레들.<br><br>놀라 턴다는 게 그만 허물을 찢었다. 벌레들이 손등으로 옮겨 붙었다.<br>물리지는 않았는데 가려움이 이틀 갔다. 수집가가 벌레 꼬인 물건을 맨손으로 뒤집다니. 초심을 잃은 벌이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } }
  ] },

{ at:'S', t:'쉬는 자리 — 목록 점호',
  x:`수집가는 잠들기 전에 일행 짐까지 머릿속 목록으로 점호한다. 버릇이다.<br><br>
    사흘째 밤, 목록이 안 맞는다. 첫날은 가죽끈 하나. 둘째 날은 가죽 물주머니. 오늘은 가죽 장갑 한 짝.<br>
    도둑이 드는데, 가죽만 집어 간다.<br><br>
    목록이 말해 준다. 이건 도둑이 아니라 식성이다.`,
  o:[
    { l:'① 가죽을 다 걷어 따로 묶어 둔다.', k:'fix', dc:24,
      ok:`일행의 가죽붙이를 다 걷었다. 끈, 칼집, 장갑. 한 자루에 몰아 야영지 밖 바위 위에 뒀다.<br><br>밤에 바위 쪽에서 바스락 소리가 한참 났다. 아침에 보니 자루째 사라졌다.<br>그 뒤로 야영지 안으로는 아무것도 안 들어왔다. 식당을 밖에 차려 준 것이다. 목록은 그날부터 다시 맞았다.`,
      ng:`걷는다고 걷었는데 한 사람이 신발을 안 내놨다. 가죽 신발인 걸 밤에야 알았다.<br><br>새벽에 그 사람 비명에 다 깼다. 신은 채로 벗겨 가려는 것과 발버둥 중이었다.<br>다 같이 매달려 되찾았다. 신발 콧등에 이빨 자국이 송송했다. 목록에서 빠진 한 줄이 제일 비쌌다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 어둠 쪽에 헌 가죽을 값으로 내놓는다.', k:'bond', dc:24,
      ok:`닳은 허리끈 하나를 야영지 가장자리에 미리 내놨다. 가져갈 것은 이쪽이 정한다.<br><br>아침에 끈은 없고, 그 자리에 반들반들한 돌이 하나 놓여 있었다. 값을 치르고 간 것이다.<br>며칠을 그렇게 거래했다. 머릿속 목록에 새 칸이 생겼다. 「나간 것 — 헌 가죽. 들어온 것 — 돌 셋, 평온한 밤 넷.」`,
      ng:`내놓은 끈이 아침까지 그대로였다. 대신 자루 밑바닥이 뚫려 있었다.<br><br>내놓은 것 말고 숨긴 것을 집어 간 것이다. 고르는 식성이다.<br>뚫린 자루를 기우며 목록을 다시 썼다. 저쪽 목록이 이쪽 목록보다 정확했다. 자존심이 상했다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-20 } },
    { l:'③ 밤새 지켜 식성의 임자를 본다.', k:'sense', dc:25,
      ok:`불침번을 자청하고 어둠에 눈을 익혔다. 자정 넘어 그것이 왔다. 손바닥만 하고, 눈이 없고, 코가 몸의 반이다.<br><br>가죽 냄새만 좇는 작은 것. 그 뒤 어둠에 큰 윤곽이 서 있었다. 작은 것을 따라다니며 남는 것을 먹는 큰 것.<br>작은 도둑은 큰 것의 앞잡이였다. 목록에 제일 중요한 한 줄이 추가됐다. 「작은 것이 오면 큰 것이 온다.」`,
      ng:`지키다 깜빡 조는 사이 그것이 다녀갔다. 이번엔 이쪽 소매의 가죽 단추 두 개.<br><br>잘린 실밥이 어찌나 깔끔한지 감탄이 먼저 나왔다.<br>감탄은 짧았다. 단추를 문 작은 것 발자국 옆에 큰 발자국이 겹쳐 있었다. 야영지 바로 옆까지. 그날부터 조는 불침번은 없어졌다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S', t:'위석 — 반질한 돌무더기',
  x:`길가에 돌무더기가 있다. 주먹만 한 돌들이 하나같이 반질반질하다.<br><br>
    강돌이 아니다. 물에 닳은 결이 아니라 살에 닳은 결이다. 수집가는 돌 보는 눈이 있다.<br>
    짐승 뱃속에서 구르던 돌. 큰 것들이 삼켜 밥을 가는 돌이다.<br><br>
    뱃돌을 게워 놓는 자리는 정해져 있다. 그놈이 쉬는 자리다.`,
  o:[
    { l:'① 돌의 수와 크기로 임자를 센다.', k:'luck', dc:25, wake:1,
      ok:`무더기를 눈으로 갈랐다. 크기가 세 무리다. 주먹만 한 것, 머리만 한 것, 그리고 안쪽에 묻힌 맷돌만 한 것.<br><br>셋이 이 자리를 같이 쓴다. 제일 큰 돌의 임자는 생각하고 싶지 않은 크기다.<br>쉬는 자리는 해 질 녘에 붐빈다. 해가 있을 때 서둘러 지났다. 멀리서 보니 저녁 어스름에 큰 그림자 셋이 그 자리로 모여들고 있었다.<br><br>돌만 보고 임자 셋의 크기와 시간표까지 셌다. 수집가의 감정이 정찰이 되는 순간이다.`,
      ng:`세는 데 열중해 무더기에 너무 가까이 갔다. 발밑에서 돌 하나가 굴렀다.<br><br>반질한 돌끼리 부딪는 소리는 맑고 멀리 간다. 익숙한 소리를 들은 무엇이 자리를 보러 왔다.<br>무더기 뒤에 엎드려 그것이 제 돌을 헤아리고 갈 때까지 기다렸다. 그것도 세고 있었다. 수집가가 둘인 자리였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 제일 반질한 돌 하나만 챙긴다.', k:'hide', dc:24,
      ok:`맨 가장자리, 제일 작고 반질한 놈으로 하나만 집었다. 무더기 모양이 안 바뀌게.<br><br>뱃속에서 십 년은 구른 결이다. 숫돌로도, 찜질돌로도 쓸 물건.<br>그날 밤 그 돌을 불에 데워 품고 잤다. 어느 큰 짐승의 뱃속 온기를 빌려 자는 셈이었다. 잠이 깊었다.`,
      ng:`집은 돌 밑에 다른 돌이 괴어 있었다. 무더기 귀퉁이가 와르르 흘렀다.<br><br>맑은 돌 소리가 길게 울렸다. 수풀 저쪽에서 큰 숨이 한 번 들렸다.<br>돌은 쥔 채 뛰었다. 챙긴 돌이 주머니에서 무릎을 때릴 때마다 죄책감 비슷한 게 올라왔다. 남의 살림을 무너뜨리고 가져온 물건은 처음이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'어둠 — 짝 맞추기',
  x:`등불 가장자리에 눈빛이 떠 있다. 수집가는 짝 있는 물건을 다룬다. 눈도 짝이다.<br><br>
    짝의 간격은 머리 크기다. 손가락으로 재 봤다. 왼쪽 무리는 한 뼘. 고만고만한 것들.<br>
    그런데 오른쪽 한 쌍은 간격이 넉 자다.<br><br>
    눈 사이가 넉 자면 머리가 넉 자다. 아니면, 둘이 바짝 붙어 한 쌍인 척하는 것이거나.`,
  o:[
    { l:'① 넉 자 간격이 어느 쪽인지 소리로 가린다.', k:'sense', dc:25,
      ok:`돌을 하나 던져 봤다. 넉 자짜리 두 눈 사이로.<br><br>머리 하나면 눈이 같이 움직이고, 둘이면 따로 움직인다. 눈이 따로 움직였다. 둘이다. 붙어 서서 큰 척하는 어린 것들.<br>큰 척하는 건 저희도 무섭다는 것이다. 등불을 높이 들고 당당히 지나갔다. 어린 것들이 먼저 길을 비켰다.`,
      ng:`돌을 던졌는데 두 눈이 정확히 같이 움직였다. 머리 하나다. 넉 자짜리.<br><br>그리고 그 머리가 돌 던진 쪽을 봤다. 이쪽을.<br>등불을 끄고 바위 뒤로 굴렀다. 넉 자 머리가 지나가는 바람이 바위 위를 쓸었다. 숨을 쉰 건 한참 뒤였다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 가까이 가서 짝을 확인한다.', k:'gaze', dc:26,
      doom:{ title:'넉 자 머리', what:'큰 턱에 물려 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`눈대중으로는 못 믿겠어서 한 걸음씩 다가갔다. 감정은 가까이서 하는 것이다.<br><br>다섯 걸음에서 알았다. 두 눈 사이에 콧김이 있다. 머리 하나다.<br>여섯 걸음째는 이쪽 걸음이 아니었다. 그 머리가 온 걸음이다. 턱이 허리를 물고 들어 올린다. 어둠 속으로 성큼성큼. 등불이 저 뒤에서 작아진다. 수집가 평생 가장 큰 표본을 가장 가까이서 감정하는 중이다.<br><br>감정 거리라는 게 있다. 물건은 가까울수록 좋고, 임자 있는 것은 멀수록 좋다.`,
        dieText:`어둠 가장자리에 등불이 하나 떨어져 타고 있다.<br><br>그 곁에 손가락 재기를 하던 손 모양대로 장갑 한 짝이 놓였다.<br>넉 자 간격의 눈빛이 등불을 한참 내려다보다 꺼졌다.` },
      ok:`다가가다 세 걸음에서 멈췄다. 두 눈 사이 어둠이 숨에 맞춰 부푸는 게 보였다. 콧등이다. 머리 하나.<br><br>뒷걸음으로 세 걸음, 옆으로 열 걸음. 눈을 마주 보지도 등지지도 않는 수집가 걸음으로.<br>넉 자 머리는 따라오지 않았다. 배가 부른 눈이었다. 감정 결과는 확실했고, 표본은 포기했다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'배설물 — 내용물 조사',
  x:`길 한복판에 배설물 더미가 있다. 크고, 아직 김이 돈다.<br><br>
    다들 코를 막고 돌아간다. 수집가만 쪼그려 앉는다. 뱃속을 보여 주는 물건이다. 이만한 자료가 없다.<br>
    막대로 헤쳐 봤다. 털, 뼛조각, 그리고 쇠 단추.<br><br>
    쇠 단추. 가죽옷에 다는 종류다.`,
  o:[
    { l:'① 끝까지 헤쳐 목록을 만든다.', k:'luck', dc:25,
      ok:`막대 둘로 더미를 다 헤쳤다. 단추 넷, 혁대 고리 하나, 부싯돌 하나. 사람 하나 치 세간이다.<br><br>그리고 뼛조각이 하나도 사람 것이 아니다. 삼킨 건 세간뿐, 사람은 씹지 않고 삼키지도 않았다는 것이다. 산 채로 데려가는 종류다. 어디론가.<br>세간의 녹 상태로 보아 보름 전 일. 보름 전에 지나간 사람들이 어디로 끌려갔는지, 이 더미가 길의 방향까지 알려 줬다. 그 방향을 피해 돌았다.`,
      ng:`헤치는 중에 더미 속에서 쉭 소리가 났다. 김이 아니라 숨이었다.<br><br>배설물 속에 작은 것이 파묻혀 살고 있었다. 더운 데만 찾는 종류.<br>튀어나와 막대를 타고 올라오는 걸 던져 버렸다. 막대째. 목록은 반만 만들었고, 손은 한나절 씻었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 김의 온기로 지나간 때만 잰다.', k:'sense', dc:23,
      ok:`손등을 가까이 대 온기를 쟀다. 속까지 덥다. 한 시진 안쪽이다.<br><br>한 시진 거리에 그 큰 것이 있다. 바람 방향을 재고 바람 아래로 붙어 걸었다.<br>더미 하나로 거리와 방향을 다 얻었다. 더러운 자료가 깨끗한 자료보다 정확할 때가 많다.`,
      ng:`온기를 재는데 더미가 둘인 걸 늦게 봤다. 열 걸음 앞에 하나 더. 그쪽은 김이 더 세다.<br><br>두 번 눈 것이 아니라 둘이 지나간 것이다. 짝으로 다니는 종류.<br>짝은 대개 한 놈이 뒤를 돈다. 돌아보니 과연 수풀 저쪽에서 가지 하나가 내려앉았다. 서둘러 길을 꺾었다. 식은땀이 밴 하루였다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'둥지 — 모으는 것',
  x:`바위 틈 둥지를 들여다봤다. 알 자리인 줄 알았는데 아니다.<br><br>
    반짝이는 것들이 쌓여 있다. 쇠붙이, 유리 조각, 물빛 도는 돌. 크기순으로, 빛깔끼리, 가지런히.<br>
    수집가는 한눈에 알아봤다. 이건 저장이 아니라 수집이다. 배열에 취향이 있다.<br><br>
    여기, 같은 업을 하는 것이 산다.`,
  o:[
    { l:'① 한 점 보태고 간다.', k:'luck', dc:25, wake:1,
      ok:`주머니에서 놋단추 하나를 꺼냈다. 반들반들 닳은 놈. 둥지 배열의 빈 구석, 빛깔이 이어지는 자리에 놓았다.<br><br>배열을 아는 솜씨로. 같은 업끼리는 솜씨로 인사한다.<br>이튿날 그 길을 되지나는데 둥지 앞 바위에 물빛 도는 돌 하나가 나와 있었다. 이쪽 몫으로 내놓은 답례다. 받았다. 평생 수집품 중 유일하게, 받은 물건이다.<br><br>모으는 마음이 사람만의 것이 아니라는 걸 알았다. 수집가의 세상이 한 칸 넓어졌다.`,
      ng:`단추를 놓는 자리가 틀렸던 모양이다. 배열의 결을 거슬렀다.<br><br>밤에 야영지까지 와서 단추를 돌려놓고 갔다. 이쪽 이마 옆에. 거절의 뜻치고는 정중했고, 여기까지 왔다 간 발소리를 아무도 못 들었다는 게 무서웠다.<br>단추를 도로 주머니에 넣었다. 솜씨를 더 닦고 와야 하는 모양이다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 제일 좋은 한 점을 슬쩍한다.', k:'hide', dc:26,
      doom:{ title:'둥지 임자', what:'둥지 임자에게 잡혀 바위 틈으로 끌려 들어갑니다', dc:20, sec:40,
        text:`물빛 도는 돌이 자꾸 눈에 밟혔다. 배열 가장자리 것 하나쯤이야.<br><br>집는 순간 바위 틈 안쪽에서 손이 나왔다. 길고 마디 많은 손. 수집가의 손목을 수집했다.<br>틈 안으로 끌려 들어간다. 안쪽 벽에도 선반처럼 턱이 파여 있고, 뭔가 줄줄이 배열돼 있다. 어두워서 다행이다. 뭘 크기순으로 모아 뒀는지 안 보여서.<br><br>남의 수집품에 손대는 자의 말로는 업계가 다 안다. 여기 업계도 같았다.`,
        dieText:`바위 틈 둥지의 배열이 한 점 늘었다.<br><br>반들반들 닳은 놋단추가 빛깔 이어지는 자리에 놓였다.<br>배열이 아주 흡족한 모양새다.` },
      ok:`물빛 돌로 손을 뻗다가, 배열 한구석의 빈자리를 봤다. 딱 그 돌 크기의 빈자리.<br><br>옮기는 중이었던 것이다. 즉, 임자가 지금 작업 중이고, 작업 중인 수집가는 둥지 곁을 안 떠난다.<br>손을 거두고 물러났다. 바위 틈 안쪽에서 마디 꺾이는 소리가 났다. 지켜보고 있었다. 손을 거둔 것까지 다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'발톱 자국 — 금 간 발톱',
  x:`벽과 나무에 발톱 자국이 줄줄이 나 있다. 다들 같은 자국으로 보는 것을 수집가는 가른다.<br><br>
    넷째 발톱이 금 간 놈. 둘째가 닳은 놈. 다 성한 놈. 세 마리다.<br>
    자국은 수집하면 개체가 된다. 개체가 되면 버릇이 보인다.<br><br>
    금 간 발톱의 자국이 제일 새것이고, 제일 낮은 데를 긁었고, 제일 자주 나온다.`,
  o:[
    { l:'① 금 간 발톱의 버릇을 좇는다.', k:'luck', dc:25, wake:1,
      ok:`금 간 발톱 자국만 이어 봤다. 낮게 긁고, 왼쪽으로 돌고, 물가 쪽에만 난다.<br><br>발톱이 금 간 건 어디가 아프다는 것이다. 아픈 놈은 쉬운 길만 돈다. 물가의 왼쪽 도는 길. 그 길만 피하면 이놈은 안 만난다.<br>이틀 동안 과연 안 만났다. 남은 둘은 자국이 늙었다. 요즘 안 다니는 것들이다. 셋을 다 피하는 데 자국 수집 반나절이면 됐다.<br><br>자국을 모으면 짐승이 그려진다. 그려진 짐승은 절반쯤 피한 짐승이다. 목록이 무기가 되는 걸 봤다.`,
      ng:`버릇을 좇아 물가를 피했는데, 아픈 놈 생각만 한 게 패착이었다.<br><br>성한 놈이 마른 쪽 길에 새 자국을 내기 시작한 것이다. 요즘 안 다니던 놈이 다시 다닌다.<br>새 자국과 이쪽 발자국이 겹치기 전에 알아챈 게 그나마 다행이었다. 목록은 산 것이라 매일 고쳐 적어야 한다. 하루 묵은 목록에 발을 걸 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 자국 높이로 키를 재서 길을 고른다.', k:'sense', dc:24,
      ok:`제일 높은 자국이 어깨 높이의 곱절이다. 그 키가 못 들어오는 데를 골랐다. 천장 낮은 바위 틈 길.<br><br>허리를 굽히고 걷는 반나절. 허리값으로 안전을 샀다.<br>틈 밖에서 큰 것이 따라 걸으며 바위를 긁는 소리가 두 번 났다. 못 들어오는 걸 저도 알고 내는 화풀이 소리였다.`,
      ng:`낮은 틈을 골랐는데 낮은 데는 낮은 것들의 길이었다.<br><br>무릎 높이 어둠에서 작은 것들이 발목을 스치고 다녔다. 수가 많았다.<br>물리기 전에 틈을 빠져나와 큰길로 돌았다. 키 큰 것과 키 작은 것들 사이, 중간 높이의 길을 찾는 데 한나절이 들었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'일행 — 상한 데 감정',
  x:`일행 하나가 긁힌 자리를 보여 줬다. 어제는 벌겋더니 오늘은 거무스름하다.<br><br>
    수집가는 의원이 아니다. 하지만 상한 물건은 평생 봤다. 녹, 곰팡이, 벌레 먹은 자리.<br>
    상처 가장자리가 녹슨 쇠 결로 번진다. 가운데는 벌레 먹은 나무 결이다.<br><br>
    본 적 있는 결이다. 사흘 전 지나친 가시덤불의 가시 끝이 꼭 이 빛깔이었다.`,
  o:[
    { l:'① 같은 결을 목록에서 찾아 맞춘다.', k:'luck', dc:25,
      ok:`머릿속 목록을 넘겼다. 그 가시덤불 아래 넓은 잎 풀이 같이 자랐다. 가시 있는 독초 곁에는 해독초가 같이 산다는 건 약초꾼들 말이지만, 수집가 목록에도 그 짝은 늘 같이 적힌다.<br><br>반나절을 되짚어 그 잎을 뜯어 왔다. 짓이겨 붙이자 거무스름한 결이 하루 만에 옅어졌다.<br>목록은 틀리지 않았다. 짝으로 적어 둔 것이 짝으로 일했다.`,
      ng:`목록의 잎을 찾아 되짚었는데 그 자리가 뜯겨 있었다. 짐승이 먼저 다 먹었다.<br><br>빈손으로 돌아오는 길이 멀었다. 상처는 그 사이 더 번졌다.<br>결국 상한 자리를 째고 짜내는 수밖에 없었다. 그 사람이 이를 물고 버텼다. 목록이 맞아도 재고가 없으면 소용없다. 뼈아픈 줄을 하나 적었다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ hp:-27, mind:-15 } },
    { l:'② 상한 결 그대로 본을 떠 둔다.', k:'fix', dc:23,
      ok:`천에 숯으로 상처의 결을 그대로 베꼈다. 날짜와 번진 빠르기도 적었다.<br><br>흉한 수집이지만 이게 있으면 다음 사람 것과 비교가 된다. 번지는 빠르기가 어제보다 줄었다. 몸이 이기고 있다는 뜻이다.<br>그 말을 해 주자 그 사람 낯빛이 살아났다. 숫자는 가끔 약보다 잘 듣는다.`,
      ng:`본을 뜨는 걸 그 사람이 보고 겁에 질렸다. 죽은 뒤 기록으로 남길 셈이냐고.<br><br>그게 아니라고 설명하는 데 한참 걸렸다. 반쯤은 그 뜻이 맞아서였다.<br>본은 떴지만 신뢰를 좀 잃었다. 수집가의 버릇이 늘 위로가 되지는 않는다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S', t:'반짝이 — 가짜 광채',
  x:`어둠 속에 뭔가 반짝인다. 물빛 도는, 수집가 평생 못 본 광채.<br><br>
    심장이 먼저 뛰고 다리가 따라간다. 그러다 멈췄다.<br>
    너무 좋은 자리에 있다. 딱 눈높이. 딱 손 뻗을 거리의 바위 턱. 먼지 하나 없이.<br><br>
    수집가는 가짜를 안다. 가짜의 특징은 완벽한 자리다. 진짜는 아무 데나 굴러다닌다.`,
  o:[
    { l:'① 광채에 손을 뻗는다.', k:'gaze', dc:26,
      doom:{ title:'낚싯바늘', what:'광채를 문 채 어둠 속으로 끌려 들어갑니다', dc:20, sec:40,
        text:`가짜래도 눈으로 확인은 해야 한다. 그게 수집가다. 한 발, 또 한 발.<br><br>광채가 살짝 물러났다. 따라갔다. 또 물러났다. 눈치챘을 때는 어둠이 등 뒤까지 닫혀 있었다.<br>광채는 그것의 몸끝에 달린 미끼였다. 불을 머금는 살 한 점. 손목이 잡힌다. 끌려 들어가며 보니 어둠 안쪽에 반짝이는 것들이 줄줄이 걸려 있었다. 단추, 반지, 버클. 먼저 온 수집가들의 것.<br><br>미끼를 수집하는 사냥꾼과 사냥감을 수집하는 수집가. 업계가 겹쳤고, 저쪽이 선배였다.`,
        dieText:`어둠 속에 뭔가 반짝인다. 물빛 도는 광채.<br><br>그 옆에 하나 더 늘었다. 놋쇠 허리띠 고리.<br>둘 다 딱 눈높이, 딱 손 뻗을 거리에 있다.` },
      ok:`뻗던 손을 멈추고 등불을 광채 옆 벽으로 비췄다. 광채 뒤로 가늘고 긴 것이 이어져 있었다. 힘줄처럼.<br><br>미끼다. 산 미끼.<br>등불을 받은 힘줄이 천천히 광채를 거둬들였다. 어둠 안쪽으로, 아쉬운 듯이. 낚시꾼의 얼굴은 끝까지 안 보였다. 목록에 적었다. 「물빛 광채 — 위조품. 임자 있음.」`,
      win:{ exp:24, dream:3 } },
    { l:'② 돌을 던져 진가품 감정부터 한다.', k:'luck', dc:25, wake:1,
      ok:`광채 옆 바위에 돌을 던졌다. 진짜 보석은 소리에 안 움직인다.<br><br>광채가 움찔 꺼졌다 켜졌다. 눈꺼풀이 있는 보석은 없다.<br>가짜 판정. 돌아서는데 어둠 안쪽에서 실망한 듯한 긴 숨이 들렸다. 못 판 장사꾼의 한숨 같아서 조금 우스웠다.<br><br>탐나는 것 앞에서 감정 절차를 지키는 손. 평생 장물에 안 속던 눈이 목숨을 속이려는 것도 걸러 냈다.`,
      ng:`돌이 빗나가 광채를 직접 맞혔다. 광채가 꺼지고, 어둠 전체가 성을 냈다.<br><br>미끼를 때린 건 낚싯대를 때린 것이다. 긴 것이 채찍처럼 휘둘러졌다.<br>구르고 기며 물러났다. 바위에 어깨를 찧었다. 감정은 맞았는데 감정 방법이 거칠었다. 다음부터는 더 먼 데서 던지기로 했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'표본실 — 빈 자리 찾기',
  x:`표본 선반의 병마다 번호가 적혀 있다. 7, 8, 9, 그리고 빈자리, 11.<br><br>
    수집가는 연번에서 빠진 수부터 본다. 직업병이다.<br>
    방을 다 돌며 세었다. 빠진 번호가 넷. 10, 23, 31, 40.<br><br>
    깨진 병은 바닥에 유리라도 남는다. 빈자리 넷은 유리가 없다. 누가 꺼내 간 게 아니면, 제 발로 나간 것이다.`,
  o:[
    { l:'① 빠진 번호의 명찰을 찾아 읽는다.', k:'luck', dc:25, wake:1,
      ok:`선반 밑 서랍에서 명부를 찾았다. 10번 — 굴 파는 것. 23번 — 물에 사는 것. 31번 — 천장에 붙는 것. 40번 — 글씨가 뭉개졌다. 다만 사육 칸 크기가 적혀 있다. 방만 하다.<br><br>나간 넷의 식성과 사는 데를 알았으니 바닥, 물가, 천장을 다 피하는 길을 짰다.<br>방만 한 40번만은 피하는 법을 못 짰다. 대신 마주치면 피할 수 없다는 걸 아는 채로 걷는 것과 모르는 채로 걷는 것은 다르다.<br><br>빠진 번호를 세는 버릇이 이 건물 전체의 재고 조사가 됐다. 없는 것의 목록이 제일 중요한 목록이다.`,
      ng:`명부를 찾아 읽는 데 반 시진을 썼다. 읽는 동안 등 뒤 선반 위 칸에서 병 하나가 비었다.<br><br>마개가 안쪽에서 뚫려 바닥에 떨어져 있었다. 방금. 빠진 번호가 다섯이 됐다.<br>새로 빈 병의 번호를 명부에서 찾아보는 손이 떨렸다. 「주의 — 소리에 모임」. 명부를 덮고 발소리를 죽여 나왔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 남은 병들의 자리만 지나간다.', k:'evade', dc:24,
      ok:`찬 병이 있는 줄은 안전한 줄이다. 적어도 그 안엣것은 안 나온 것이니까.<br><br>찬 병들 사이로만 길을 그어 방을 가로질렀다.<br>빈자리 옆을 지날 때마다 걸음을 늘렸다. 빈 칸이 뿜는 서늘함은 수집가가 제일 잘 안다. 도둑맞은 진열장 앞에 서 본 사람의 감각이다.`,
      ng:`찬 병 사이로 걷는데 병 하나가 안에서 두드렸다. 지나는 박자에 맞춰.<br><br>마개를 보니 반쯤 뚫리다 말았다. 작업 중인 것이다.<br>그 병 번호를 외워 두고 서둘러 지났다. 다음에 이 방을 지나는 자를 위해 문에 숯으로 적었다. 「12번 곧 빈다」.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S1', t:'명부 — 마지막 번호',
  x:`당직실에서 반입 명부를 찾았다. 수집가에게 명부는 보물 지도다.<br><br>
    1번부터 40번까지. 크기, 먹이, 우는 소리까지 꼼꼼하다.<br>
    마지막 장에 한 줄이 더 있다. 번호가 없다. 「—번. 착륙 때 같이 온 것. 크기 미상. 알을 낳는다.」<br><br>
    번호 없는 수집품. 명부를 쓴 사람도 그것만은 셈에 못 넣은 것이다.`,
  o:[
    { l:'① 명부 전체에서 번호 없는 것의 자리를 추린다.', k:'luck', dc:25,
      ok:`명부를 거꾸로 읽었다. 먹이 소비가 어느 날부터 곱절로 뛴다. 아래층 사육동만. 알을 낳는 것이 아래층에 자리 잡은 날이다.<br><br>그날 이후 기록된 사육사 이름이 하나씩 줄어드는 것도 보였다.<br>아래층 사육동 방향을 머리에 새겼다. 가지 않기 위한 지도다. 번호 없는 것의 주소를 번호들 틈에서 찾아냈다. 명부는 쓴 사람보다 많이 안다.`,
      ng:`명부에 빠져 있는 사이 등불이 반으로 줄었다. 기름을 깜빡했다.<br><br>어두워진 당직실 구석에서 뭔가 부스럭댔다. 명부만 품고 더듬더듬 나왔다.<br>복도에서 펴 보니 급하게 집은 쪽이 앞장 몇 장뿐이었다. 알짜인 마지막 장은 당직실에 남았다. 다시 들어갈 엄두는 안 났다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 명부째 챙겨 짐에 넣는다.', k:'steady', dc:23,
      ok:`읽는 건 나중이다. 명부째 기름천에 싸서 짐 맨 위에 넣었다.<br><br>쉴 때마다 한 장씩 읽었다. 사흘 치 길잡이가 됐다.<br>다 읽은 뒤에도 안 버렸다. 이 건물에서 나간다면, 이 명부는 바깥에 전할 가장 중요한 수집품이다. 여기 뭐가 사는지 적힌 유일한 종이니까.`,
      ng:`명부를 빼자 밑에 눌려 있던 서류들이 와르르 쏟아졌다. 종이 쏟아지는 소리가 복도까지 갔다.<br><br>복도의 무엇이 당직실 문을 긁기 시작했다.<br>창구멍으로 다들 겨우 빠져나왔다. 명부는 품에 있었다. 종이 한 뭉치 값으로는 비싼 소동이었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S1', t:'선반 — 짝 없는 뚜껑',
  x:`깨진 병 바닥과 뚜껑들이 바닥에 널렸다. 수집가는 짝부터 센다. 버릇이다.<br><br>
    병 바닥이 열하나, 뚜껑이 열둘.<br>
    뚜껑 하나가 남는다. 짝 없는 뚜껑은 없다. 어딘가에 뚜껑 없이 서 있는 병이 하나 있거나—<br><br>
    선반 맨 끝, 어둑한 자리에 병 하나가 서 있다. 유리 빛이 다른 병과 미묘하게 다르다.`,
  o:[
    { l:'① 등불을 비춰 유리 결부터 감정한다.', k:'luck', dc:25,
      ok:`멀찍이서 등불을 비췄다. 유리는 빛을 통과시킨다. 그 병은 빛을 머금었다.<br><br>유리가 아니다. 유리인 척하는 살가죽이다. 병 모양으로 웅크려 선반에 끼어 있는 것.<br>못 본 척 등불을 거두고 반대쪽으로 돌았다. 선반 끝에서 병 하나가 소리 없이 선반을 내려와 어둠으로 흘러가는 걸 곁눈으로만 봤다. 감정 결과는 입 밖에 안 냈다. 다 나와서야 말해 줬다.`,
      ng:`등불을 비추자 그 병이 아주 천천히 숨을 쉬었다. 들킨 걸 아는 숨.<br><br>병인 척을 그만둔 것이 선반에서 흘러내렸다.<br>선반을 사이에 두고 반대로 돌았다. 그것은 쫓는 대신 깨진 병 바닥 사이에서 다시 병 모양으로 굳었다. 이번엔 어느 자리인지 아무도 못 봤다. 그게 제일 나빴다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-23 } },
    { l:'② 다가가 뚜껑을 맞춰 본다.', k:'gaze', dc:26,
      doom:{ title:'짝 맞추기', what:'병인 척하던 것에게 안겨 끌려갑니다', dc:20, sec:40,
        text:`짝 없는 뚜껑을 들고 그 병에 다가갔다. 맞으면 그냥 병. 안 맞으면 수상한 병. 완벽한 감정법이라고 생각했다.<br><br>뚜껑이 병 주둥이에 닿는 순간, 주둥이가 뚜껑을 물었다.<br>병이 펴진다. 길게. 병 모양이던 것이 이쪽을 감싸 안는다. 차고 매끈한 유리의 감촉 그대로. 선반 뒤 벽 틈으로 끌려 들어가며 생각했다. 뚜껑은 맞았다. 저것의 입 크기에 꼭 맞았다.<br><br>감정은 맞댐이 아니라 눈으로 하는 것이다. 기본 중의 기본인데.`,
        dieText:`바닥에 병 바닥이 열하나, 뚜껑이 열하나.<br><br>짝이 다 맞는다.<br>선반 끝 어둑한 자리는 비어 있다. 당분간은.` },
      ok:`뚜껑을 들고 다가가다 멈췄다. 병 주둥이에 먼지가 없다. 선반의 다른 모든 것에는 먼지가 앉았는데.<br><br>숨 쉬는 물건에는 먼지가 못 앉는다.<br>뚜껑을 제자리에 내려놓고 뒷걸음으로 물러났다. 병이 아주 조금, 아쉬운 쪽으로 기울었다 돌아왔다. 짝 없는 뚜껑은 짝 없는 채로 두는 게 맞는 날도 있다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'냉동 표본 — 온전한 하나',
  x:`냉동실 안쪽에 그것이 통째로 얼어 있다. 온전한 한 마리.<br><br>
    이빨 하나, 비늘 한 장도 아니고 전신이다. 수집가 평생의 꿈이 성에 뒤에 서 있다.<br>
    들고 나가면 역사에 남는다. 들 수나 있다면. 녹지만 않는다면.<br><br>
    녹으면 어떻게 되는지는, 생각을 멈췄다.`,
  o:[
    { l:'① 비늘 석 장과 발톱 하나만 떼어 간다.', k:'luck', dc:25, wake:1,
      ok:`전신은 포기했다. 대신 감정가의 눈으로 골랐다. 종을 증명할 수 있는 최소 부위. 비늘 석 장, 발톱 하나, 그리고 이빨의 본.<br><br>얼어 있어 깨끗하게 떨어졌다. 기름천에 싸 품 깊이 넣었다.<br>나오며 전신을 한 번 더 봤다. 눈꺼풀에 성에가 꼈는데도 눈알이 이쪽을 따라오는 것 같았다. 그건 착각이고, 착각이 아니어도 이미 문밖이다.<br><br>평생의 꿈을 눈앞에 두고 최소만 떼는 손. 수집가가 아니라 증인이 되기로 한 손이다. 그 차이를 여기서 배웠다.`,
      ng:`비늘을 떼는데 성에 밑 살이 꿈틀했다. 완전히 죽어 언 게 아니라, 얼어서 멈춰 있는 것이다.<br><br>손이 굳었다. 냉동실 기계가 언제 죽을지 모른다는 데 생각이 미쳤다.<br>비늘 한 장만 쥐고 물러났다. 문을 닫으며 온도계를 봤다. 바늘이 아주 조금씩 오르고 있었다. 그 바늘 생각이 그 뒤로 밤마다 났다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 성에 낀 기계부터 살핀다.', k:'fix', dc:24,
      ok:`표본보다 기계를 먼저 봤다. 배관이 반쯤 얼음에 묻혀 돌아간다. 얼음이 배관을 조이고 있다.<br><br>조이는 얼음을 깨서 숨통을 틔웠다. 기계 소리가 한결 순해졌다.<br>이 안의 것이 깨는 날을 뒤로 미룬 것이다. 수집품 보존 처리. 평생 하던 일 중 제일 큰 건이었다.`,
      ng:`얼음을 깨는 진동이 표본까지 울렸다. 성에가 쩍 소리를 내며 금 갔다.<br><br>금 간 틈으로 김이 샜다. 안쪽 것의 체온인지 바깥 공기인지 모를 김.<br>연장을 놓고 물러났다. 문을 닫고 손잡이에 쇠막대를 질렀다. 보존 처리가 개봉 작업이 될 뻔했다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S1', t:'산성 자국 — 남는 것',
  x:`그것들 피가 지나간 방을 봤다. 쇠 선반은 엿가락이 됐고 바닥 철판은 뚫렸다.<br><br>
    그런데 유리병들은 멀쩡하다. 실험대 유리판도.<br>
    수집가의 눈이 빛났다. 저 피는 쇠는 먹고 유리는 못 먹는다.<br><br>
    남는 것을 아는 자가 담는 것을 안다.`,
  o:[
    { l:'① 유리 그릇들을 연장으로 챙긴다.', k:'luck', dc:24,
      ok:`두꺼운 유리 대접 둘과 유리 막대를 챙겼다. 천으로 감아 소리를 죽였다.<br><br>이틀 뒤 바로 썼다. 핏방울이 듣는 길목에서 유리 대접을 투구처럼 받쳐 들고 지났다. 대접 위에서 두 방울이 끓다 말랐다.<br>쇠 투구였으면 정수리가 뚫렸다. 남는 재질의 목록은 이런 데서 밥값을 한다.`,
      ng:`유리를 챙겨 나오다 문턱에서 자루가 걸렸다. 유리끼리 부딪는 소리가 쨍 울렸다.<br><br>그 피의 임자들이 소리에 밝다는 걸 잊고 있었다.<br>복도 양쪽에서 기척이 좁혀 왔다. 유리 대접 하나를 바닥에 굴려 소리를 반대로 던지고 빠져나왔다. 챙긴 것 반, 버린 것 반.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 녹은 쇠의 모양으로 피의 길을 그린다.', k:'sense', dc:24,
      ok:`녹은 자국의 깊이와 방향을 이었다. 피가 떨어진 길. 천장 배관을 따라 일직선이다.<br><br>그 밑으로만 안 걸으면 된다. 배관 길을 피해 방들을 이었다.<br>지도에 없는 지도가 하나 생겼다. 「피의 길」. 이름은 흉해도 제일 쓸모 있는 지도다.`,
      ng:`자국을 따라가다 제일 새 자국 앞에 섰다. 아직 김이 오르는.<br><br>위를 올려다본 게 실수였다. 배관 위에서 상처 입은 것이 이쪽을 내려다보고 있었다. 뚝. 한 방울이 어깨를 스쳐 바닥에서 끓었다.<br>구르며 피했다. 외투 어깨가 타서 연기가 났다. 지도 작성비로는 과했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S1', t:'통풍구 — 떨어지는 것들',
  x:`복도 바닥에 물건이 점점이 떨어져 있다. 단추, 천 조각, 안경다리.<br><br>
    위를 봤다. 통풍구 격자. 그 속에 그것이 산다. 그리고 그것은 뭔가를 모은다.<br>
    떨어진 건 그것이 안 모으는 것들이다. 천과 쇠는 버리고, 다른 건 가져간다.<br><br>
    버린 목록을 뒤집으면 모으는 목록이 나온다. 수집가의 셈법이다.`,
  o:[
    { l:'① 버린 것들로 모으는 것을 추린다.', k:'luck', dc:25,
      ok:`떨어진 것을 다 주워 늘어놨다. 천, 쇠, 가죽, 머리카락 뭉치까지 버렸다. 안 버린 것, 즉 가져간 것은 뼈다.<br><br>뼈를 모으는 것이다. 그렇다면 뼈처럼 안 보이는 게 최선이다. 다들 겉옷을 여며 목과 손목을 가리고, 격자 밑에서는 몸을 웅크리지 않기로 했다. 웅크린 윤곽이 제일 뼈 무더기 같으니까.<br>격자 밑을 여섯 번 지났다. 여섯 번 다, 위의 것은 내려오지 않았다.`,
      ng:`추리는 동안 격자 위에서 그것이 구경하고 있었다.<br><br>늘어놓은 물건들 위로 안경다리 하나가 톡 떨어졌다. 보태 주는 것이다.<br>구경당하며 한 수집 분류는 처음이다. 물건을 그대로 두고 물러났다. 위에서 낮게 그르렁대는 소리가 났다. 웃음이었기를 빈다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 떨어진 자리들을 이어 위의 길을 그린다.', k:'sense', dc:24,
      ok:`떨어진 물건 자리를 점으로 이었다. 위에서 다니는 길이 바닥에 그려졌다.<br><br>그 선과 교차하지 않는 복도만 골라 걸었다.<br>머리 위 소리는 늘 그 선 위에서만 났다. 흘린 것으로 흘린 자의 길을 그리는 것. 수집가는 바닥만 보고도 천장을 읽는다.`,
      ng:`선을 긋다 보니 선이 이 복도 전체를 덮었다. 안 지나는 데가 없는 길이다.<br><br>여기는 그것의 안마당이었다.<br>지도고 뭐고 제일 짧은 직선으로 내달렸다. 등 뒤 격자들이 차례로 덜컹였다. 안마당에서는 지도가 아니라 다리가 답이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'알 방 — 하나만',
  x:`알의 방이다. 가죽 주머니 같은 것들이 줄지어 앉아 김을 올린다.<br><br>
    수집가의 손이 떨린다. 저것 하나면 평생의 수집이 완성된다.<br>
    배열을 봤다. 줄과 간격이 고르다. 고른 배열은 세는 배열이다. 지키는 것이 수를 안다는 뜻이다.<br><br>
    그런데 구석에 하나, 줄에서 밀려난 것이 있다. 식고, 쭈그러들고, 배열 밖에 버려진 것.`,
  o:[
    { l:'① 배열 밖의 식은 것만 거둔다.', k:'luck', dc:25, wake:1,
      ok:`줄 안의 것에는 눈길도 안 줬다. 배열 밖에 버려진 식은 것만 천에 싸서 안았다. 버린 것은 세지 않는다. 어느 수집가도 그렇다.<br><br>방을 나설 때까지 아무것도 움직이지 않았다.<br>식은 알은 가볍고 딱딱했다. 안이 비었어도 좋다. 이 방에서 나온 껍데기 하나가 뭍의 어느 온전한 보물보다 크다.<br><br>갖고 싶은 것과 가질 수 있는 것을 가르는 눈. 그 눈이 수집가를 늙어 죽게 해 준다는 스승의 말을, 알의 방에서 몸으로 새겼다.`,
      ng:`식은 것을 드는데 바닥에 수지로 살짝 붙어 있었다. 떼는 소리가 났다. 지익.<br><br>방 안쪽 어둠에서 큰 숨이 한 번 돌았다.<br>식은 알을 안은 채 숨도 못 쉬고 섰다. 숨이 다시 고르게 가라앉은 뒤에야 발꿈치로 물러났다. 버린 것을 줍는 것조차 여기서는 소리값을 치러야 한다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-17, spirit:-23 } },
    { l:'② 줄 안의 성한 것을 하나 집는다.', k:'hide', dc:26,
      doom:{ title:'배열의 수', what:'지키는 것에게 잡혀 알자리로 끌려갑니다', dc:20, sec:40,
        text:`제일 구석 줄, 제일 작은 것 하나. 이 정도 배열이면 하나쯤은.<br><br>드는 순간 방 전체의 김이 멎었다. 줄지어 앉은 것들이 일제히 이쪽으로 기울었다.<br>어둠에서 지키는 것이 나왔다. 걸음이 조용한 큰 것. 들고 있던 알을 바닥에 내려놓을 틈도 안 줬다. 목덜미를 물려 알자리 복판으로 끌려간다. 빈자리에 알이 돌아가고, 그 옆자리에 이쪽이 놓인다.<br><br>세는 배열에서 하나를 집으면 수가 빈다. 빈 수는 채워진다. 무엇으로든.`,
        dieText:`알의 방 배열이 고르다. 줄과 간격이 맞다.<br><br>다만 알 하나 곁에 천 꾸러미가 하나 놓였다.<br>수집가의 짐이다. 배열에 맞춰, 가지런히.` },
      ok:`집으려고 뻗은 손끝에서 알 겉이 움찔했다. 안엣것이 손 그림자를 느낀 것이다.<br><br>산 알이다. 산 알은 운다. 울면 온다.<br>손을 거두고 식은 것 쪽으로 돌아섰다. 줄 안의 것은 안 건드렸다는 사실만이 이 방을 나가는 통행증이다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 아무것도 안 거두고 배열만 베껴 간다.', k:'steady', dc:24,
      ok:`천에 숯으로 배열을 그대로 그렸다. 줄 수, 간격, 김이 오르는 순서까지.<br><br>물건은 못 가져가도 기록은 가져간다. 기록도 수집이다. 어쩌면 제일 오래 남는 수집이다.<br>그림을 품고 소리 없이 물러났다. 방 안쪽 어둠이 끝까지 고요했다. 가져간 게 없는 손님은 손님으로 안 치는 모양이다.`,
      ng:`그리는 데 욕심을 내 너무 오래 머물렀다. 숯이 천을 긁는 소리조차 이 방에서는 소리였다.<br><br>안쪽 어둠의 숨이 바뀌었다. 깨는 숨.<br>그리다 만 천을 움켜쥐고 물러났다. 반쪽짜리 그림이 됐다. 반쪽이어도 세상에 하나뿐인 그림이다. 그렇게 위안했다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-21 } }
  ] },

{ at:'S2', t:'호박 — 굳은 수지',
  x:`죽은 침엽수 둥치에 수지가 흘러 굳었다. 호박빛 덩이들.<br><br>
    그 속에 작은 벌레들이 박혀 있다. 날개 편 채로, 영원히.<br>
    수집가의 눈이 오랜만에 사냥이 아니라 수집으로 빛났다. 여기서 처음 만나는, 임자 없는 보물이다.<br><br>
    주머니칼로 떼면 그만이다. 아무도 안 쫓아온다. 그게 낯설어서 손이 머뭇거렸다.`,
  o:[
    { l:'① 제일 맑은 덩이 셋을 챙긴다.', k:'luck', dc:24,
      ok:`맑기로 셋을 골라 떼어 천에 쌌다. 하나엔 날개 넷 달린 벌레가, 하나엔 씨앗이, 하나엔 아무것도 없이 노을빛만 담겼다.<br><br>그날 밤 일행에게 돌려 보여 줬다. 다들 등불에 비춰 보며 처음으로 여기 들어온 뒤의 웃음을 웃었다.<br>목숨값 안 붙은 보물의 힘이다. 짐이 하나도 안 무거워졌는데 다들 발걸음이 가벼워졌다.`,
      ng:`떼는데 둥치가 울렸다. 속이 삭아 빈 나무였다.<br><br>울림을 타고 뭔가가 둥치 꼭대기에서 깼다. 날개 달린 작은 것들이 구멍에서 쏟아져 나왔다.<br>호박 한 덩이만 쥐고 뛰었다. 쏘인 데가 셋. 보물값치고는 쌌다고 해 두기로 했다.`,
      win:{ exp:20, dream:3, mind:8 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 무른 수지를 등불 기름에 개어 쓴다.', k:'fix', dc:23,
      ok:`굳은 것 말고 아직 무른 수지를 긁어 모았다. 등불 기름에 개니 오래 타는 덩이가 됐다.<br><br>횃불 세 자루 치 연료가 생겼다.<br>보물을 보고 연료를 캐는 건 수집가답지 않지만, 여기서는 타는 것이 빛나는 것보다 귀하다. 목록의 값 매김이 장소 따라 뒤집히는 걸 또 배운다.`,
      ng:`무른 수지가 손에 들러붙었다. 송진의 곱절로 끈질긴 수지다.<br><br>떼느라 살갗이 벌게졌다. 손가락 사이가 하루 종일 쩍쩍했다.<br>그 손으로 바위를 짚었다가 장갑 한 짝을 바위에 기부했다. 공짜 보물은 없다. 여기서는 더.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S2', t:'모래밭 — 걸음 수집',
  x:`물가 모래밭은 발자국 전시장이다. 수집가는 아침마다 여기 들러 어제의 걸음을 수집한다.<br><br>
    무리 것이 일곱 벌. 그제도 일곱, 어제도 일곱이었다.<br>
    오늘은 여섯 벌이다.<br><br>
    줄어든 하나는 죽은 게 아니다. 죽었으면 뼈가 남고 소란이 남는다. 모래밭에 안 온 것이다. 어디 딴 데서 걷고 있는 것이다.`,
  o:[
    { l:'① 빠진 한 벌의 임자를 걸음으로 찾는다.', k:'luck', dc:25, wake:1,
      ok:`여섯 벌을 꼼꼼히 봤다. 빠진 놈은 뒷발 안쪽이 닳은 놈이다. 그 걸음을 어디서 봤는지 목록을 뒤졌다. 오늘 아침, 야영지 뒤 언덕 돌밭.<br><br>그놈은 모래밭 대신 이쪽 뒤를 돌고 있다. 무리가 물 마시는 척 시선을 끌고, 하나가 돌아 드는 몰이.<br>언덕을 등지고 바위에 붙어 이동했다. 저녁에 언덕 쪽에서 허탕 친 그놈이 무리로 돌아가는 걸 봤다. 뒷발 안쪽이 닳은 걸음으로.<br><br>발자국 일곱 벌을 얼굴처럼 외운 덕이다. 수집가의 목록에는 이제 짐승들 이름이 하나씩 붙어 있다.`,
      ng:`빠진 놈을 찾느라 모래밭에 너무 오래 서 있었다.<br><br>모래밭은 저들의 전시장이기 전에 물가다. 물 마시러 오는 시간이 됐다.<br>여섯 벌의 임자들이 수풀 저쪽에서 나타났다. 물과 이쪽을 번갈아 보는 눈들을 뒤로하고 천천히, 등을 안 보이고 물러났다. 전시장 관람 시간을 어긴 벌이다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 이쪽 발자국을 모래밭에서 지운다.', k:'hide', dc:24,
      ok:`나뭇가지로 일행의 자국을 쓸며 물러났다. 모래밭에 사람 걸음 전시를 남길 이유가 없다.<br><br>저들이 이쪽 걸음을 수집하지 못하면 이쪽 수와 방향도 모른다.<br>쓸어 둔 모래밭에 다음 날 저들 자국만 찍혀 있었다. 사람 자국을 찾아 서성인 결이 어지러웠다. 목록에서 이쪽만 지워진 것이다.`,
      ng:`쓸다가 깨달았다. 쓴 자국도 자국이다.<br><br>자연의 모래밭에 빗자루 결이 났다. 숨긴 것이 아니라 숨겼다는 광고가 됐다.<br>다음 날 모래밭 가장자리에 저들 자국이 빗자루 결을 따라 줄지어 나 있었다. 연구한 것이다. 등골이 서늘했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'S2', t:'물가 — 떠오른 패',
  x:`물에 잠긴 양치밭 가장자리에 쇠붙이들이 떠밀려 와 있다. 사육사들의 신분패다.<br><br>
    물때가 낀 것, 성한 것, 줄까지 달린 것. 물속 어딘가에서 흘러나오는 것이다.<br>
    패마다 이름과 구역 번호가 찍혀 있다. 이 정원의 지도 조각들이다.<br><br>
    몇 개는 손 닿는 물속에 가라앉아 반짝인다.`,
  o:[
    { l:'① 물가에 밀려온 것만 줍는다.', k:'luck', dc:24,
      ok:`마른 데 밀려온 패만 여섯 장 모았다. 물속 것은 보지도 않았다.<br><br>이름 여섯, 구역 번호 여섯. 번호를 맞추니 정원의 구획이 그려졌다. 급이대가 셋, 사육동이 둘, 그리고 「E-0 승강장」.<br>승강기의 공식 이름일 것이다. 죽은 사람들의 이름표가 산 사람들의 지도가 됐다. 여섯 이름을 한 번씩 소리 내 읽어 줬다. 그 값이다.`,
      ng:`줍는데 패 하나에 긴 물풀이 감겨 있었다. 당기자 물풀이 물속으로 팽팽해졌다.<br><br>물풀이 아니었다. 놓았다.<br>수면에 큰 소용돌이가 한 번 일고 가라앉았다. 주운 패 석 장만 쥐고 물가에서 물러났다. 낚싯줄 달린 패였다. 어느 쪽이 낚시꾼인지는 분명했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 물속 반짝이는 것까지 건진다.', k:'sense', dc:26,
      doom:{ title:'얕은 물', what:'물밑의 것에게 팔을 잡혀 끌려 들어갑니다', dc:20, sec:40,
        text:`무릎까지만 들어가면 된다. 제일 성한 패가 바로 거기 가라앉아 있다.<br><br>손끝이 패에 닿는 순간, 패 밑의 모래가 통째로 움직였다.<br>모래 빛깔로 엎드려 있던 것이다. 패는 그 등에 얹혀 있었다. 미끼로. 팔이 물리고, 몸이 물속으로 당겨진다. 양치 줄기 사이로 수면이 멀어진다. 그 와중에도 손은 패를 쥐고 있었다. 이름 하나는 건진 셈이다. 제 것과 바꿔서.<br><br>얕은 물이 깊은 물보다 위험하다. 얕은 데가 사냥터니까.`,
        dieText:`물가에 신분패들이 떠밀려 와 있다.<br><br>한 장이 새로 늘었다. 물때도 안 낀 성한 패.<br>이름 칸이 비어 있는 패다.` },
      ok:`들어가기 전에 막대로 물밑을 먼저 쑤셨다. 패 옆 모래가 꿈틀했다.<br><br>모래가 아니라 모래 빛 등가죽이었다.<br>막대를 천천히 거두고 물에서 물러났다. 물속 패는 그 등에 얹힌 채 반짝였다. 미끼 상품이다. 진열의 뜻을 아는 수집가는 안 속는다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'울타리 — 사라진 애자',
  x:`울타리 기둥마다 사기 애자가 달려 있었다. 전기 먹이던 시절의 물건이다.<br><br>
    그런데 한 구간만 애자가 다 뽑혀 있다. 부서진 게 아니라 뽑혔다. 가지런히.<br>
    기둥 밑을 보니 뽑힌 애자들이 한데 모여 있다. 이빨 자국이 송송한 채.<br><br>
    저것들이 전기의 이빨을 하나하나 뽑아 모은 것이다. 뽑는 법을 배워 가면서.`,
  o:[
    { l:'① 애자가 성한 구간으로만 붙어 다닌다.', k:'luck', dc:25,
      ok:`애자가 뽑힌 구간은 저들이 공들인 구간이다. 공들인 데가 저들의 문이다.<br><br>애자 성한 구간 쪽에 야영지를 잡았다. 저들은 제가 안 뚫은 데로는 안 온다. 공든 길만 쓰는 버릇이 있다.<br>밤새 뽑힌 구간 쪽에서만 울타리 넘는 소리가 났다. 저들의 문과 이쪽의 방을 울타리 하나로 갈라 쓴 셈이다.`,
      ng:`성한 구간에 붙었는데 새벽에 바로 옆 기둥에서 소리가 났다. 사기 긁히는 소리.<br><br>새 구간을 뚫기 시작한 것이다. 하필 이쪽 옆을.<br>짐을 걷어 옮겼다. 저들의 공사 구간은 저들이 정한다. 이쪽이 할 수 있는 건 공사 소리가 나면 이사 가는 것뿐이다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-20 } },
    { l:'② 모아 둔 애자를 흩뜨려 놓는다.', k:'break', dc:24,
      ok:`모아 둔 애자 무더기를 울타리 안쪽 여기저기로 흩어 던졌다.<br><br>다음 날 저들이 흩어진 애자를 도로 모으느라 반나절을 썼다. 모으는 버릇은 못 버리는 것이다. 동업자라 안다.<br>그 반나절에 그 구간을 조용히 지났다. 수집벽을 수집벽으로 묶었다. 좀 치사했지만 잘 들었다.`,
      ng:`흩뜨리는 중에 애자 하나가 돌에 맞아 깨졌다. 사기 깨지는 소리가 밤을 갈랐다.<br><br>제 수집품 깨지는 소리를 저들이 알아들었다.<br>울타리 너머에서 성난 울음이 겹으로 울렸다. 그 구간은 포기하고 밤길을 돌았다. 남의 수집품은 흩뜨려도 깨면 안 된다. 동업자의 선이다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S2', t:'급이대 — 깃털 하나',
  x:`급이대 쇠틀에 깃털이 하나 끼어 있다. 팔뚝만 한 깃털.<br><br>
    무리 것들에게는 이만한 깃이 없다. 이건 그 큰 것의 깃이다.<br>
    깃이 끼인 높이는 사람 키의 세 곱. 끼인 결은 몸을 비빈 결이다.<br><br>
    큰 것이 여기 와서 몸을 비빈다. 가려운 데를 긁는 기둥인 것이다. 정기적으로.`,
  o:[
    { l:'① 깃의 상태로 다녀간 때를 잰다.', k:'luck', dc:25,
      ok:`깃 뿌리가 아직 기름지다. 이틀 안쪽에 다녀갔다.<br><br>몸 긁는 자리는 짐승마다 도는 간격이 있다. 이틀 전에 왔으면 당분간 안 온다.<br>급이대 그늘에서 하루를 쉬어 가기로 했다. 큰 것의 가려움 주기가 이쪽의 휴가가 됐다. 깃털은 챙겼다. 평생 수집품 중 제일 큰 깃이다.`,
      ng:`깃 뿌리를 만져 보는데 기름이 생각보다 촉촉했다. 이틀이 아니라 오늘 아침이다.<br><br>그 순간 땅이 울렸다. 아침에 긁다 만 가려움이 남았던 모양이다.<br>급이대에서 사방으로 흩어져 엎드렸다. 큰 것이 와서 한참 몸을 비볐다. 쇠틀이 휘는 소리를 들으며 다들 풀숲에서 돌이 됐다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 긁는 기둥에서 먼 길로 돈다.', k:'evade', dc:24,
      ok:`긁는 자리 둘레는 큰 것의 마당이다. 마당을 크게 둘렀다.<br><br>두르는 길에 무리 것들의 자국도 없었다. 저들도 이 마당은 피하는 것이다.<br>제일 무서운 것의 마당 가장자리가 제일 안전한 산책로라는 역설. 목록에 적어 둘 가치가 있다.`,
      ng:`두르는 길이 덤불에 막혀 자꾸 마당 쪽으로 밀렸다.<br><br>결국 마당 가장자리를 스치는데 발밑에서 깃털 하나가 또 밟혔다. 바스락.<br>소리는 작았지만 간이 철렁했다. 뛰듯이 벗어났다. 가장자리라는 게 생각보다 넓었다. 큰 것의 마당은 큰 것 기준이다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-19 } }
  ] },

{ at:'S2', t:'둥지 가장자리 — 전리품 무더기',
  x:`무리의 둥지 가장자리에 무더기가 있다. 뼈가 아니다. 쇠붙이들이다.<br><br>
    허리띠 고리, 단추, 구부러진 숟가락. 먹지도 못할 것들만 따로 모아 놓았다.<br>
    저들도 모은다. 사냥의 기념품을.<br><br>
    무더기 맨 위에 낯익은 것이 있다. 사흘 전 일행이 잃어버린 물통 고리다.`,
  o:[
    { l:'① 고리의 뜻부터 셈한다.', k:'luck', dc:25,
      ok:`사흘 전에 잃은 물건이 여기 있다는 건, 사흘 전부터 따라붙었다는 것이다. 몰랐던 건 이쪽뿐이다.<br><br>그날부터 행군의 짜임을 다 바꿨다. 쉬는 때, 걷는 줄, 불 피우는 순서까지.<br>따라붙던 저들의 눈에는 사흘 치 관찰이 하루아침에 휴지가 된 셈이다. 무더기의 경고를 읽은 덕이다. 수집품은 수집가에 대해 말한다. 저들의 수집품이 저들의 사냥법을 다 말해 줬다.`,
      ng:`고리를 보고 등골이 식는 사이, 수풀 저쪽에서 낮은 울음이 났다.<br><br>둥지 가장자리는 가장자리여도 둥지다. 너무 깊이 들어와 있었다.<br>무더기를 등지고 천천히 물러났다. 울음이 세 방향에서 번갈아 났다. 배웅인지 경고인지 모를 소리를 들으며 식은땀으로 옷이 젖었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-23 } },
    { l:'② 물통 고리를 되찾아 온다.', k:'hide', dc:26,
      doom:{ title:'기념품', what:'둥지의 것들에게 잡혀 둥지로 끌려갑니다', dc:20, sec:40,
        text:`잃은 물건은 찾아야 한다. 수집가의 몸에 밴 셈이다. 소리 없이 무더기로 다가가 고리를 집었다.<br><br>고리 밑에 가는 힘줄이 깔려 있었다. 무더기 전체가 덫 위에 차려진 진열이었다.<br>힘줄이 울리자 수풀이 세 군데서 동시에 열렸다. 저들은 기념품으로 미끼 놓는 법까지 아는 것이다. 다리를 물려 둥지 안쪽으로 끌려간다. 전리품 무더기가 눈앞을 지나간다. 거기 이쪽 물건이 하나 더 얹힐 것이다.<br><br>저들의 수집품에 손을 댔다. 동업자 사이에도, 아니 동업자 사이라서 더, 해서는 안 되는 일이었다.`,
        dieText:`둥지 가장자리 무더기가 한 층 높아졌다.<br><br>물통 고리 옆에 허리띠가 통째로 얹혔다.<br>버클이 반들반들하다. 아끼던 물건이다.` },
      ok:`다가가다 무더기 밑의 가는 힘줄을 봤다. 덫 위의 진열이다.<br><br>고리는 포기했다. 대신 주머니의 녹슨 못 하나를 힘줄 안 닿는 가장자리에 던져 보탰다.<br>셈은 이렇다. 저들의 목록에 이쪽 물건이 있는 건 어쩔 수 없다. 하지만 이쪽이 줬다는 기록을 보태면, 뺏긴 목록이 거래 목록이 된다. 정신 승리인 건 안다. 수집가는 목록 없이는 못 산다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 손잡이 찾기',
  x:`낡은 승강기의 수동 크랭크 자리가 비어 있다. 손잡이가 없으면 쇳덩이 상자일 뿐이다.<br><br>
    일행이 주저앉는다. 수집가만 눈을 감는다.<br>
    머릿속 목록을 넘긴다. 지나온 자리마다 봐 둔 물건들. 관리인 오두막, 녹슨 공구함, 급이대 물품함.<br><br>
    오두막 벽, 못에 걸린 쇠막대. 끝이 네모나게 깎인. 그때는 그냥 지나친 고철이었다.`,
  o:[
    { l:'① 목록 속 그 쇠막대를 가지러 되돌아간다.', k:'luck', dc:25, wake:1,
      ok:`반나절 길을 되짚었다. 오두막 벽, 못, 쇠막대. 기억 그대로 걸려 있었다. 네모 깎인 끝이 크랭크 축에 꼭 물렸다.<br><br>승강기가 울며 돌기 시작했다.<br>일행이 수집가를 다시 봤다. 평생 들은 「그런 건 뭐 하러 봐 두냐」는 소리가 오늘 다 갚아졌다. 봐 둔 것은 언젠가 쓰인다. 쓰이는 날이 꼭 온다.<br><br>눈에 담는 것도 수집이라는 걸 증명한 날이다. 머릿속 창고의 목록이 손에 잡히는 재산이 됐다.`,
      ng:`되짚는 길에 무리의 사냥 시간이 겹쳤다. 수풀마다 눈이 떠 있었다.<br><br>쇠막대는 가져왔다. 대신 오는 길에 두 번 쫓기고 한 번 구르고 팔뚝이 긁혔다.<br>크랭크는 돌았다. 돌긴 돌았는데, 목록의 값에 길값을 더하는 셈을 다음부터는 먼저 하기로 했다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 승강기 둘레 고철로 손잡이를 벼린다.', k:'fix', dc:24,
      ok:`통로 둘레에 떨어진 고철을 추렸다. 꺾인 난간대 하나가 축 구멍에 얼추 맞았다.<br><br>돌에 갈아 각을 맞추는 데 한 시진. 덜컹대지만 돈다.<br>목록에 없으면 만들면 된다. 수집가의 뒷면은 언제나 고물상이다. 그걸 부끄러워한 적 없다.`,
      ng:`가는 소리가 문제였다. 쇠 가는 소리는 여기서 제일 낯선 소리다.<br><br>낯선 소리에 궁금한 것들이 모여들었다.<br>반쯤 간 손잡이를 쥐고 다들 통로 안에 숨어 기척이 지나기를 기다렸다. 마무리는 천으로 감싸고 갈았다. 소리 죽인 작업은 곱절로 느렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] }

]);

// ==========================================
// 🥣 거지 (beggar) · 내공
// ==========================================
kJob('beggar', 'S', [

{ at:'S', t:'입구 — 그릇에 서리는 김',
  x:`문턱 안쪽에 그릇을 내려놓았다. 이 빠진 사기 그릇. 들어가는 데마다 하는 버릇이다.<br><br>
    동전 대신 딴것이 담겼다. 김이다. 그릇 안쪽에 뿌옇게 서렸다가 걷히고, 또 서린다.<br>
    어둠 안쪽에서 큰 숨이 밀려오는 것이다. 그릇이 그 숨을 받아 보여 준다.<br><br>
    서리는 간격이 길고 고르다. 자는 숨이다. 아직은.`,
  o:[
    { l:'① 그릇을 들고 김이 짙어지는 쪽을 가린다.', k:'luck', dc:25, wake:1,
      ok:`그릇을 받쳐 들고 어귀를 반 바퀴 돌았다. 왼쪽에서 김이 짙고 오른쪽에서 옅다.<br><br>자는 것은 왼쪽에 있다. 오른쪽 벽을 타고 들었다. 그릇의 김이 가늘어지다 마침내 안 서리는 자리까지.<br>거기서부터가 숨 밖이다. 평생 동냥을 담던 그릇이 오늘은 목숨 길을 담았다.<br><br>그릇 하나로 어둠의 숨을 뜨는 법. 빌어먹던 세간이 하나씩 연장이 되어 간다.`,
      ng:`반 바퀴 도는 사이 김의 간격이 바뀌었다. 짧아졌다.<br><br>깨는 숨이다. 그릇이 알려 준 게 고마울 지경으로 빨리.<br>그릇을 품고 오른쪽으로 내달렸다. 등 뒤 어둠이 길게 하품하는 소리를 냈다. 하품 끝이 이쪽 냄새를 물었는지는 모른다. 걸음만 늘렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 그릇에 물을 부어 수평으로 어귀 바닥을 읽는다.', k:'sense', dc:24,
      ok:`그릇에 물을 반쯤 붓고 바닥에 놓았다. 물낯이 한쪽으로 쏠린다. 어귀 바닥이 안쪽으로 기울었다는 것이다.<br><br>기운 바닥은 뭔가 드나들며 다진 바닥이다. 미끄럼틀처럼 닳은 길.<br>그 길을 피해 바위 턱으로 올라 건넜다. 물그릇 하나가 수평계 노릇을 했다. 거지 세간은 쓰임이 많아야 한다. 가진 게 몇 안 되니까.`,
      ng:`물낯을 읽는데 물에 잔금이 일었다. 바닥을 타고 오는 진동이다.<br><br>드나드는 것이 돌아오는 중이었다.<br>물을 쏟고 그릇만 챙겨 바위 뒤로 굴렀다. 닳은 길 위로 큰 것이 미끄러지듯 들어갔다. 물 한 그릇 값으로 그 꼴을 구경했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'표식 — 앞서 간 업',
  x:`벽 밑 돌에 긁힌 표식이 있다. 동그라미에 빗금 둘. 같은 업끼리 쓰는 글자다.<br><br>
    「먹는 것이 있음. 소리 내지 말 것.」<br>
    열 걸음마다 표식이 이어진다. 먼저 지나간 같은 업이 길을 그어 둔 것이다.<br><br>
    마지막 표식은 긋다 말았다. 빗금 하나가 반 토막이다.`,
  o:[
    { l:'① 표식을 따라 소리를 끊고 걷는다.', k:'luck', dc:25,
      ok:`표식이 이르는 대로 했다. 신발을 벗어 들고, 숨을 길게 늘이고, 열 걸음마다 멈춰 들었다.<br><br>표식 길은 벽 틈과 바위 그늘로만 이어졌다. 트인 데를 귀신같이 피해 간 길이다.<br>긋다 만 마지막 표식 앞에서 잠깐 섰다. 그 앞 바위 그늘에 몸을 숨길 자리가 하나 있었다. 마저 못 그은 사람 대신 빗금 반 토막을 채워 그었다. 다음 업을 위해.`,
      ng:`표식을 따르다 중간에 끊긴 데를 만났다. 돌이 뒤집혀 있었다.<br><br>뭔가가 표식 돌을 뒤집고 다니는 것이다. 읽는 놈이 있다는 걸 아는 것이다.<br>길잡이를 잃고 눈치로만 걸었다. 두 번 길을 물렸고 한 번은 하마터면 트인 데로 나설 뻔했다. 표식 없는 길이 이렇게 어두운 줄 몰랐다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 긋다 만 자리를 더듬어 본다.', k:'gaze', dc:26,
      doom:{ title:'긋다 만 빗금', what:'표식 긋던 이를 데려간 것에게 끌려갑니다', dc:20, sec:40,
        text:`반 토막 빗금 앞에 쪼그려 앉았다. 긋다 만 손끝이 어디서 멈췄는지, 돌가루의 결을 더듬었다.<br><br>결이 말해 줬다. 손은 위로 낚였다. 돌가루가 위쪽으로 쓸려 있다.<br>위. 올려다보는 순간 그늘에서 긴 것이 내려왔다. 표식 긋던 이를 데려간 그것이 아직 그 자리를 지키고 있었다. 어깨를 감겨 들려 올라간다. 마지막으로 보인 건 반 토막 빗금이었다. 저 빗금은 이제 영영 반 토막이다.<br><br>표식은 읽는 것이다. 긋던 사람의 끝을 캐는 글자가 아니다.`,
        dieText:`벽 밑 돌에 표식이 이어진다. 동그라미에 빗금 둘.<br><br>마지막 표식은 빗금 하나가 반 토막이다.<br>그 아래 이 빠진 사기 그릇이 하나 엎어져 있다.` },
      ok:`더듬기 전에 버릇대로 위부터 봤다. 처마 밑에서 평생 잔 사람의 버릇이다. 위에서 오는 것부터 살핀다.<br><br>그늘 속에 긴 것이 접혀 있었다. 긋다 만 손을 낚아 간 놈이 아직 거기서 다음 손을 기다린다.<br>물러나 표식 길을 벗어나 크게 둘렀다. 마지막 표식의 뜻을 그제야 읽었다. 반 토막 빗금. 「여기서 끊김」. 그보다 정확한 글자가 없다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'어둠 — 굶은 것 가려보기',
  x:`무엇이 일행 둘레를 돈다. 보이지는 않고 발소리만, 크게, 일정하게.<br><br>
    일행은 뛰자고 한다. 거지는 손을 들어 막았다.<br>
    평생 굶은 것들 사이에서 살았다. 굶은 걸음과 부른 걸음은 다르다. 굶은 것은 조용히 좁혀 온다. 소리를 내며 도는 것은 배가 부르다.<br><br>
    저건 사냥이 아니라 구경이다. 뛰면 사냥이 된다.`,
  o:[
    { l:'① 걸음을 안 바꾸고 그대로 걷는다.', k:'steady', dc:25, wake:1,
      ok:`같은 빠르기로, 같은 보폭으로 걸었다. 겁먹은 걸음은 냄새가 난다. 그 냄새만 안 피우면 된다.<br><br>도는 발소리가 한 바퀴, 두 바퀴. 점점 멀어졌다. 구경거리가 재미없어진 것이다.<br>일행이 어떻게 알았느냐고 물었다. 굶어 본 사람은 굶은 걸음을 안다고만 했다. 더 긴 설명은 저녁 숟가락보다 무거웠다.<br><br>굶주림을 읽는 눈이 여기서는 창보다 낫다. 빌어먹던 세월이 통째로 병법이 됐다.`,
      ng:`걸음은 지켰는데 일행 하나가 못 버티고 반걸음 뛰었다.<br><br>도는 발소리가 뚝 멎었다. 구경꾼의 눈빛이 바뀌는 소리였다.<br>다 같이 바위 틈에 끼어 한 식경을 버텼다. 부른 배가 심심풀이 사냥을 접을 때까지. 반걸음이 한 식경이 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 먹을 것 한 점을 소리 나게 떨군다.', k:'luck', dc:24,
      ok:`마른 고기 한 점을 일부러 소리 나게 떨구고 걸음을 이었다.<br><br>도는 발소리가 떨어진 자리에서 멈췄다. 킁킁대는 소리. 부른 배도 공짜는 들여다본다.<br>들여다보는 사이 간격을 벌렸다. 한 점 값으로 산 간격이다. 동냥은 받는 것만 배우는 게 아니다. 주는 때도 같이 배운다.`,
      ng:`떨군 한 점을 그것이 거들떠도 안 봤다. 배가 부른 정도가 아니라 입이 고급이었다.<br><br>마른 것은 안 먹고 산 것만 먹는 종류.<br>도는 원이 한 뼘 좁아졌다. 등불을 모아 들고 서로 등을 붙인 채 걸었다. 원이 다시 넓어진 건 바위 지대에 들어서고 나서였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'고수레 — 던지는 자리',
  x:`끼니 전에 한 점을 떼어 어둠에 던진다. 고수레. 길에서 굶어 죽은 것들 몫.<br><br>
    여기서도 버릇은 버릇이다. 그런데 여기서는 받아먹는 것들이 진짜로 있다.<br>
    던진 자리로 작은 것들이 모이는 소리가 난다. 바스락바스락.<br><br>
    그렇다면 던지는 자리가 곧 모이는 자리다. 자리를 고를 수 있다는 것이다.`,
  o:[
    { l:'① 바람 아래 먼 데로 던진다.', k:'luck', dc:24,
      ok:`야영지에서 바람 아래쪽, 돌 던져 닿는 제일 먼 자리에 한 줌을 뿌렸다.<br><br>작은 것들이 밤새 그 자리에 모여 바스락댔다. 야영지 쪽으로는 한 마리도 안 왔다. 상이 차려진 데를 두고 올 이유가 없다.<br>작은 것들이 모인 자리는 큰 것도 들여다본다. 밤중에 큰 발소리가 그쪽으로 갔다가 돌아갔다. 고수레 한 줌이 보초까지 섰다.`,
      ng:`던진 자리가 바람 위였다. 냄새가 야영지를 지나 퍼졌다.<br><br>작은 것들이 냄새를 따라오다 야영지를 먼저 만났다.<br>밤새 발치에서 바스락거리는 것들을 쫓았다. 무는 놈은 없었는데 자는 놈도 없었다. 고수레는 방향 공부부터라는 걸 새로 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-19 } },
    { l:'② 고수레를 길목 쪽에 던져 문지기를 세운다.', k:'fix', dc:24,
      ok:`야영지로 드는 길목에 한 줌을 뿌렸다. 작은 것들이 길목에 모였다.<br><br>작은 것들은 귀가 밝고 겁이 많다. 큰 것이 오면 제일 먼저 흩어진다.<br>새벽에 길목의 바스락 소리가 일제히 멎었다. 그 고요가 종소리였다. 다들 깨어 바위 뒤로 옮기고 한 숨 돌리자 큰 것이 길목을 지나갔다. 고수레로 세운 문지기가 제값을 했다.`,
      ng:`길목의 작은 것들이 서로 싸우기 시작했다. 몫이 모자랐던 것이다.<br><br>싸우는 소리는 흩어지는 소리보다 크고 멀리 간다.<br>그 소리에 궁금한 것이 길목으로 왔다. 문지기 세우려다 호객을 한 꼴이다. 밤길을 돌아 자리를 옮겼다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'쉬는 자리 — 빈속 불침번',
  x:`먹을 것이 줄었다. 다들 제 몫을 세며 어두운 낯이다.<br><br>
    거지가 제 몫 반을 자루에 도로 넣었다. 빈속은 이골이 났다.<br>
    대신 불침번을 자청했다. 배부른 몸은 잠이 무겁고, 빈속은 귀가 밝다.<br><br>
    평생 처마 밑에서 설친 잠이 여기서는 재주다.`,
  o:[
    { l:'① 빈속의 귀로 밤을 지킨다.', k:'steady', dc:24,
      ok:`배부른 일행이 곯아떨어진 밤, 빈속으로 앉아 귀만 열어 뒀다.<br><br>자정 넘어 야영지 가장자리 풀이 결 다르게 눕는 소리를 들었다. 바람은 풀을 한꺼번에 눕히고, 발은 한 포기씩 눕힌다.<br>등불을 그쪽으로 돌려 세웠다. 기척이 멈췄다가 물러갔다. 아침에 보니 가장자리에 발자국이 반 발 들어와 있었다. 반 발에서 막은 것이다.`,
      ng:`빈속이 너무 비었다. 귀는 밝은데 눈앞이 어질했다.<br><br>기척을 듣고 일어서다 휘청해 등불을 쳤다. 쏟아진 기름에 불이 번졌다.<br>불 끄는 소란에 기척은 달아났다. 다행인지 뭔지 모를 밤이었다. 다음부터는 반의 반은 먹고 서기로 했다. 버티는 데도 밑천이 든다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 다 같이 조금씩 덜어 비상 몫을 만든다.', k:'bond', dc:24,
      ok:`"한 숟갈씩만." 각자 한 숟갈씩 덜어 비상 자루를 만들었다. 빌어먹던 사람이 거두는 쪽에 서니 다들 웃었다. 웃으면서 다 덜었다.<br><br>그 자루가 이틀 뒤 밥값을 했다. 길이 막혀 한나절을 굶게 됐을 때.<br>비상 자루를 풀며 말했다. "굶는 법은 내가 제일 잘 아는데, 안 굶는 법을 아는 게 낫지." 다들 또 웃었다. 웃음도 끼니가 된다.`,
      ng:`덜자고 하자 한 명이 낯을 붉혔다. 제 몫 축나는 게 무서운 것이다. 굶어 본 적 없는 사람의 무서움이다.<br><br>억지로는 안 걷었다. 억지 곡식은 체한다.<br>그 사람 몫만 빼고 자루를 만들었다. 이틀 뒤 그 자루를 풀 때 그 사람이 제일 멀리 앉아 있었다. 그래도 한 숟갈 떠 줬다. 그게 업이다.`,
      win:{ exp:17, dream:2, hp:6 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S', t:'막대기 — 소리 없는 더듬기',
  x:`어둠이 깊어 등불로도 세 걸음뿐이다. 막대로 바닥을 더듬으며 가야 한다.<br><br>
    눈먼 거지들이 걷는 법이다. 다만 여기서는 툭툭 치는 소리가 밥상 종소리다.<br>
    치지 않고 더듬는 법이 있다. 같이 빌어먹던 눈먼 노인이 쓰던 법이다.<br><br>
    끌면서, 손바닥으로 떨림을 읽는 것이다.`,
  o:[
    { l:'① 막대 끝에 내공을 실어 땅을 읽는다.', k:'sense', dc:25, wake:1, cost:{ qi:28 },
      ok:`내공을 손바닥에서 막대 끝까지 흘려 보냈다. 막대가 손가락이 됐다.<br><br>끌기만 해도 바닥의 결이 올라온다. 돌의 찬 기운, 흙의 무른 기운, 그리고 셋째 걸음 앞의 물컹한 기운.<br>물컹한 것을 크게 돌아 지났다. 지나고 나서 그것이 바닥에서 몸을 뒤집는 소리가 났다. 밟혔으면 깼을 것이다.<br><br>노인의 걸음법에 내공이 실리자 딴 물건이 됐다. 막대 끝이 눈이고 귀고 손끝이다.`,
      ng:`내공을 흘리는데 물컹한 것이 막대 끝의 기운을 느꼈다. 산 것의 기운을.<br><br>바닥이 꿈틀하며 막대를 물었다. 당긴다.<br>내공을 끊고 막대를 놨다. 막대가 어둠 밑으로 쑥 꺼졌다. 평생 짚던 막대를 잃고 더듬이 없는 벌레 꼴로 남은 길을 기었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 막대를 끌며 무게로만 읽는다.', k:'steady', dc:24,
      ok:`내공 없이, 노인이 하던 그대로. 끌리는 막대의 무게 변화로 읽었다.<br><br>가벼워지면 구멍, 무거워지면 턱, 걸리면 멈춤. 느리지만 틀림없다.<br>세 번 구멍을 피하고 한 번 턱에서 일행을 받쳤다. 노인 생각이 났다. 그 양반은 이 법으로 서른 해를 살았다. 여기서도 통하는 법이었다.`,
      ng:`끌리는 소리가 문제였다. 스으윽, 스으윽. 치는 소리보다 작지만 끊이지 않는 소리.<br><br>끊이지 않는 소리는 따라오기 좋은 소리다.<br>뒤에서 같은 박자의 스으윽 소리가 따라붙었다. 막대를 들고 모래밭으로 꺾어 소리를 끊었다. 한참 뒤에야 뒤가 조용해졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S', t:'냄새 — 길의 몸내',
  x:`사냥하는 것들이 일행을 자꾸 찾아낸다. 숨어도 찾아낸다.<br><br>
    거지만 두 번이나 지나쳐졌다. 바위인 줄 알았는지 코앞을 지나갔다.<br>
    씻은 사람들 몸에서는 사람 냄새가 난다. 비누, 기름, 땀. 거지 몸에는 길 냄새가 밴다. 흙, 재, 비, 돌.<br><br>
    길 냄새는 먹잇감 냄새가 아니다. 길은 아무도 안 먹는다.`,
  o:[
    { l:'① 일행에게 길 냄새를 입힌다.', k:'luck', dc:25, wake:1,
      ok:`재와 젖은 흙을 개어 다들 목덜미와 손목에 바르게 했다. 옷에는 마른 풀을 비볐다. 사람 냄새 나는 속옷은 기름천에 쌌다.<br><br>처음엔 다들 질색했다. 저녁에 그것이 야영지 가장자리를 지나면서도 코를 안 돌리는 걸 보고는 서로 재를 발라 줬다.<br>평생 몸에 밴 것이 부끄러움이었는데, 여기서는 갑옷이다.<br><br>길 냄새가 왜 안 읽히는지 말로 풀 수 있게 됐다. 가르칠 수 있는 재주가 된 것이다.`,
      ng:`재를 바르다 한 사람이 재채기를 터뜨렸다. 재가 코에 들어간 것이다.<br><br>연달아 세 번. 어둠 저쪽에서 발소리가 방향을 틀었다.<br>바르다 만 채로 흩어져 숨었다. 그것이 재채기 자리를 한참 킁킁대다 갔다. 길 냄새 공부에 수업료가 들었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 사람 냄새 나는 것들을 미끼로 건다.', k:'hide', dc:25,
      ok:`걷어 낸 속옷과 땀 밴 수건을 자루에 담아, 갈 길의 반대쪽 나뭇가지에 걸었다.<br><br>사람 냄새가 그쪽에서 바람을 탔다.<br>이틀 동안 그쪽 숲이 수런댔다. 이쪽 길은 조용했다. 벗어 둔 냄새가 저쪽에서 이쪽 몫까지 쫓기는 중이다. 미안할 것 없다. 빨래는 원래 험하게 쓰는 물건이다.`,
      ng:`미끼 자루를 거는 자리까지 가는 길에 냄새가 뚝뚝 흘렀다.<br><br>건 자리와 이쪽 길이 냄새 줄로 이어진 꼴이 됐다.<br>그것이 줄을 따라 반쯤 왔을 때에야 눈치챘다. 개울을 두 번 건너 줄을 끊었다. 미끼는 거는 길부터가 미끼 일이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'잠자리 — 잔것들 곁',
  x:`잘 자리를 고른다. 마른 바위 밑이 좋아 보인다. 너무 좋아 보인다.<br><br>
    그 옆 돌무더기 틈에는 잔것들이 산다. 찍찍대고 바스락대는, 쥐 비슷한 것들.<br>
    일행은 질색한다. 거지는 반긴다.<br>
    처마 밑에서 배웠다. 잔것들 곁이 제일 안전하다. 잔것들은 큰 것이 오면 제일 먼저 안다.<br><br>
    그리고 저들이 안 떠난 자리는, 아직 아무 일 없는 자리다.`,
  o:[
    { l:'① 돌무더기 곁에 잔다.', k:'luck', dc:25,
      ok:`찍찍 소리를 자장가 삼아 돌무더기 옆에 자리를 폈다.<br><br>새벽에 그 소리가 뚝 멎었다. 멎는 순간 눈이 떠졌다. 몸이 처마 밑 시절을 기억하고 있었다.<br>다들 깨워 바위 틈에 붙었다. 잠시 뒤 큰 것이 마른 바위 밑을 들여다보고 갔다. 너무 좋아 보이던 그 자리를. 잔것들의 침묵이 목숨 종을 쳐 줬다.`,
      ng:`잔것들이 밤새 먹을 것 자루를 노렸다. 곁을 내준 값을 치르라는 것이다.<br><br>자루를 품고 자느라 잠이 설었다. 새벽엔 신발 끈까지 쏠렸다.<br>그래도 큰 것은 안 왔다. 잔것들 수고비로 마른 빵 귀퉁이를 떼어 주고 자리를 떴다. 시끄러운 이웃이 무서운 이웃보다 낫다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-15, spirit:-19 } },
    { l:'② 너무 좋은 바위 밑을 살펴본다.', k:'sense', dc:24,
      ok:`마른 바위 밑을 등불로 비췄다. 바닥이 반질하다. 뭔가 자주 눕는 자리다.<br><br>털 몇 올이 돌 틈에 끼어 있다. 팔뚝만 한 길이의 억센 털.<br>남의 안방이다. 좋아 보이는 데는 임자가 있어서 좋아 보이는 것이다. 평생 처마 밑을 고르며 배운 그대로였다. 돌무더기 곁으로 돌아갔다.`,
      ng:`비추는 등불에 안쪽 그늘이 꿈틀했다. 임자가 아직 안에 있었다.<br><br>낮잠을 깨운 것이다.<br>등불을 끄고 뒷걸음질로 물러났다. 임자가 바위 밑에서 머리만 내밀고 한참 이쪽을 봤다. 다행히 쫓아올 만큼 부지런한 임자는 아니었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S', t:'마주침 — 동냥 자세',
  x:`모퉁이에서 그것과 마주쳤다. 세 걸음. 숨이 닿는 거리다.<br><br>
    뛰면 등을 준다. 맞서면 싸움이 된다. 거지 몸이 먼저 움직였다. 평생 하던 그 자세로.<br>
    무릎을 꺾고, 그릇을 내밀고, 고개를 숙인다.<br><br>
    세상에서 제일 작고 제일 하찮은 것의 자세. 아무도 안 무서워하는 자세다.`,
  o:[
    { l:'① 동냥 자세로 굳는다.', k:'hide', dc:25,
      ok:`쪼그린 채 돌이 됐다. 그릇만 내민 채.<br><br>그것이 고개를 숙여 들여다봤다. 서 있는 것은 적이고 누운 것은 먹이인데, 쪼그린 것은 뭔지 모르는 것이다. 모르는 것은 건드리지 않는다. 여기서 오래 산 것일수록.<br>콧김이 그릇에 서렸다 걷혔다. 그러고는 지나갔다. 그릇에 침만 한 방울 받았다. 오늘 동냥은 목숨이다.`,
      ng:`쪼그렸는데 무릎에서 뚝 소리가 났다. 늙은 무릎이 하필 지금.<br><br>그것이 멈칫하며 한 발 다가왔다. 콧김이 정수리를 눌렀다.<br>숨을 끊고 버텼다. 영원 같은 세 숨 뒤에 그것이 흥미를 잃었다. 지나간 뒤에도 무릎이 안 펴졌다. 겁 반, 나이 반이다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-23 } },
    { l:'② 그릇을 그것 쪽으로 밀어 준다.', k:'bond', dc:25,
      ok:`쪼그린 채, 그릇을 아주 천천히 그것 앞으로 밀었다. 가진 것을 다 내놓는 자세. 싸울 뜻이 없다는 제일 오래된 말.<br><br>그것이 그릇 냄새를 맡았다. 평생 담긴 밥과 국과 빗물의 냄새.<br>그러고는 그릇을 코끝으로 이쪽에 도로 밀어 줬다. 안 받겠다는 것이다. 받는 쪽과 주는 쪽이 평생 처음으로 뒤집혔다가 제자리로 왔다. 그것이 지나간 뒤 그릇을 끌어안았다.`,
      ng:`그릇을 미는 손이 떨렸다. 그릇이 돌에 긁혀 소리를 냈다.<br><br>그것이 그릇을 발로 눌렀다. 사기 금 가는 소리.<br>그릇에 금이 하나 늘었다. 그것은 눌러 본 것으로 만족했는지 지나갔다. 금 간 그릇을 주워 품었다. 금도 그릇의 나이테다. 오늘 것은 제일 굵다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'S', t:'벌판 — 임자 있는 끼니',
  x:`트인 벌판 한가운데 사냥감이 쓰러져 있다. 갓 잡힌 것. 제일 좋은 부위가 그대로다.<br><br>
    일행 눈이 빛난다. 거지 눈은 어두워진다.<br>
    길바닥의 공짜 밥은 두 가지다. 버린 밥과 남의 밥. 버린 밥은 식어 있고, 남의 밥은 따뜻하다.<br><br>
    저건 김이 오른다.`,
  o:[
    { l:'① 벌판 가장자리 마른 죽은 것에서만 거둔다.', k:'luck', dc:25,
      ok:`김 오르는 것은 눈에서 지웠다. 대신 벌판 가장자리, 며칠 묵어 바싹 마른 죽은 것을 찾았다.<br><br>마른 것은 임자가 버린 밥이다. 햇볕에 저절로 포가 된 살을 저몄다.<br>거두는 내내 벌판 가운데 쪽에서 시선이 느껴졌다. 돌아온 임자가 제 밥과 이쪽을 번갈아 보고 있었다. 제 밥에 손 안 댄 것을 확인하고는 눈을 거뒀다. 버린 밥만 먹는 것은 어느 벌판에서도 안 쫓긴다.`,
      ng:`마른 것을 저미는데 칼이 뼈에 걸려 쨍 소리를 냈다.<br><br>벌판 가운데로 돌아오던 임자가 소리에 고개를 들었다.<br>저민 것 반만 쥐고 가장자리 덤불로 물러났다. 임자는 제 밥 곁에 서서 오래 이쪽 덤불을 노려봤다. 버린 밥도 소리 내서 먹으면 안 되는 동네다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 김 오르는 것에서 한 점만 벤다.', k:'evade', dc:26,
      doom:{ title:'밥상 임자', what:'돌아온 임자에게 물려 제 밥상 곁으로 끌려갑니다', dc:20, sec:40,
        text:`빨리 베면 된다. 한 점만. 뛰어들어 칼을 댔다.<br><br>그늘이 덮였다. 임자는 멀리 간 게 아니라 벌판 가장자리 풀숲에서 제 밥상을 지키고 있었다. 트인 벌판에 밥을 두고 가는 사냥꾼은 없다. 거지가 제일 잘 아는 것을 배가 고파 잊었다.<br>목덜미를 물려 밥상 곁으로 끌려간다. 나란히 놓인다. 먼저 것 옆에, 다음 끼니로.<br><br>남의 밥에 손대면 손이 잘린다. 길의 법이 여기서는 몸 전체로 적용될 뿐이다.`,
        dieText:`벌판 한가운데 사냥감이 둘 나란히 놓여 있다.<br><br>하나는 짐승이고 하나는 아니다.<br>이 빠진 사기 그릇이 그 곁에 엎어져 있다.` },
      ok:`뛰어들려다 멈췄다. 김 오르는 것 둘레 풀이 한 방향으로 눌려 있다. 누가 엎드려 지키는 결이다.<br><br>빈 벌판이 아니라 차려진 밥상이고, 임자가 상머리에 있다.<br>발꿈치로 물러났다. 풀숲의 결이 이쪽을 따라 천천히 돌았다. 눈이 마주치지 않은 채로 벌판을 벗어났다. 오늘 배운 것 하나. 여기 임자들은 상을 안 치우고 기다린다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'숨 — 겨울나기 숨',
  x:`그것은 눈이 아니라 몸의 김으로 찾는다. 따뜻한 것만 좇는다.<br><br>
    바위 뒤에 숨어도 몸의 김이 바위 위로 오른다.<br>
    거지는 겨울을 안다. 한데서 자는 겨울마다 몸을 식혀 버티는 법을 몸이 익혔다. 떨면 죽는다. 식히고, 느려지고, 돌이 되는 것이다.<br><br>
    그 법에 내공을 실으면, 몸의 김을 아주 끌 수 있다.`,
  o:[
    { l:'① 내공으로 몸의 김을 끈다.', k:'steady', dc:25, wake:1, cost:{ qi:32 },
      ok:`숨을 아랫배로 내리고 내공을 살갗 안쪽으로 거뒀다. 손끝부터 식는다. 겨울 처마 밑의 몸으로.<br><br>그것이 바위 위로 지나갔다. 따뜻한 것을 좇는 코가 찬 돌 두 덩이를 지나쳤다. 하나는 진짜 돌이고 하나는 거지다.<br>지나간 뒤 몸을 데우는 데 한참 걸렸다. 손끝이 저리고 아팠다. 겨울마다 아프던 꼭 그 자리가.<br><br>얼어 죽지 않으려고 익힌 법이 잡아먹히지 않는 법이 됐다. 겨울들이 헛되지 않았다.`,
      ng:`몸은 식혔는데 곁의 일행까지는 못 식혔다.<br><br>그것의 코가 일행의 김을 걸었다. 방향을 트는 콧김.<br>식힌 몸을 급히 데워 일행을 끌고 뛰었다. 식었다 데워진 몸이 비명을 질렀다. 혼자 넘는 겨울과 여럿이 넘는 겨울은 다른 공부라는 걸 배웠다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 더운 재를 뿌려 가짜 김을 만든다.', k:'luck', dc:25,
      ok:`모닥불 남은 재를 걷어 바람 아래 바위에 뿌렸다. 더운 재가 김을 올린다. 사람 몸만 한 바위에서.<br><br>그것이 그 바위를 덮쳤다. 돌 깨지는 소리와 성난 울음.<br>가짜 김이 얻어맞는 사이 진짜 김들은 반대로 빠졌다. 더운 것을 좇는 코에는 더운 것을 주면 된다. 뭐가 더운지는 이쪽이 정하고.`,
      ng:`재를 뿌리다 바람이 돌았다. 더운 재가 이쪽으로 날렸다.<br><br>재를 뒤집어쓴 일행의 몸이 김과 재로 뿌옇게 표가 났다.<br>그것이 올 때까지 개울까지 내달려 몸을 적셨다. 찬물이 김을 눌렀다. 이가 딱딱 부딪치는 걸 서로 틀어막으며 그것이 지나가길 기다렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'식당 — 숨긴 몫',
  x:`연구소 식당이다. 선반은 다 털렸다. 먼저 온 사람들이 쓸어 간 것이다.<br><br>
    거지는 빈 선반을 안 본다. 일하는 사람들이 제 몫을 숨기는 자리를 본다.<br>
    평생 식당 뒷문에서 얻어먹었다. 주방 사람들이 어디에 제 참을 숨기는지 안다.<br><br>
    국솥 밑, 쌀통 뒤 벽 틈, 그리고 제일 높은 선반 위 빈 상자 속.`,
  o:[
    { l:'① 주방지기의 자리만 골라 뒤진다.', k:'luck', dc:24,
      ok:`국솥 밑에서 기름종이 꾸러미가 나왔다. 말린 고기 한 줄과 각설탕 몇 알. 누군가의 야참이었다.<br><br>쌀통 뒤 벽 틈에서는 봉한 물 한 병.<br>선반 털러 온 사람들은 선반만 털고 간다. 뒷문에서 평생을 보낸 눈은 선반 뒤를 본다. 죽은 주방지기의 야참을 거두며 속으로 인사했다. 잘 먹겠습니다. 뒷문에서 하던 그 인사다.`,
      ng:`국솥을 들추는데 솥 안에서 소리가 났다. 솥이 비어 있지 않았다.<br><br>작은 것이 솥을 집 삼아 들어앉아 있었다. 뚜껑 틈으로 긴 것이 채찍처럼 나왔다.<br>손등을 긁히고 물러났다. 솥 속의 것은 야참 꾸러미를 깔고 산다. 임자가 바뀐 몫은 포기했다. 길의 법이다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 식당 바닥의 흘린 자국을 따라간다.', k:'sense', dc:24,
      ok:`바닥에 마른 국물 자국이 점점이 나 있다. 누가 급하게 뭘 안고 가며 흘린 길이다.<br><br>자국은 식당 뒤 창고 벽의 가짜 판자로 이어졌다. 판자 뒤에 상자 하나. 밀봉된 건빵과 물.<br>마지막 사람이 숨어 먹던 자리다. 사람은 없고 몫만 남았다. 몫 곁에 가지런히 놓인 안경을 그대로 두고, 먹을 것만 거뒀다.`,
      ng:`자국을 따라간 판자 뒤가 비어 있지 않았다. 숨어 먹던 사람이 아직 있었다. 사람이었던 것이.<br><br>가슴이 빈 채로, 앉은 자세 그대로.<br>먹을 것에는 손도 못 대고 판자를 도로 세웠다. 그 사람 몫은 그 사람 곁에 두는 것으로 했다. 발길이 한동안 무거웠다.`,
      win:{ exp:17, dream:2, item:'맑은 물' }, lose:{ mind:-17, spirit:-23 } }
  ] },

{ at:'S1', t:'통풍구 — 떨어지는 동냥',
  x:`복도 바닥에 뭔가 톡, 떨어졌다. 천장 격자에서다. 또 톡.<br><br>
    손이 저절로 나갔다. 떨어지는 것을 받는 건 거지의 반사다.<br>
    받기 전에 봤다. 떨어진 건 뼛조각이다. 위에서 그것이 먹으며 흘리는 것.<br><br>
    위에서 떨어지는 게 다 동냥은 아니다. 여기서는 더.`,
  o:[
    { l:'① 떨어지는 자리들을 이어 위의 길을 읽는다.', k:'luck', dc:25,
      ok:`뼛조각 떨어진 자리를 눈으로 이었다. 점선이 복도를 비스듬히 가로지른다. 위의 것이 다니며 먹는 길이다.<br><br>점선에서 먼 벽에 붙어 걸었다. 머리 위 소리는 늘 점선 위에서만 났다.<br>떨어지는 것으로 떨어뜨리는 것의 길을 읽었다. 처마 밑에서 빗물 떨어지는 자리로 처마 기운 꼴을 읽던 눈 그대로다.`,
      ng:`점선을 읽으며 걷다가 새 점 하나가 바로 앞에 떨어졌다. 아직 마르지 않은 것이.<br><br>바로 머리 위에 있다는 뜻이다.<br>격자 틈으로 내려오는 침 한 줄을 보며 벽에 붙었다. 그것이 지나갈 때까지 점선의 점이 되지 않으려고 숨을 접었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 제일 성한 조각을 주워 챙긴다.', k:'sense', dc:26,
      doom:{ title:'흘린 몫', what:'격자 틈의 것에게 낚여 천장으로 끌려 올라갑니다', dc:20, sec:40,
        text:`조각 중에 쓸 만한 게 있었다. 갈면 송곳이 될 굵은 뼈. 허리를 굽혀 집었다.<br><br>집는 순간 알았다. 이 조각만 유난히 바닥 한가운데, 유난히 반듯하게 놓여 있었다.<br>흘린 게 아니라 놓은 것이다. 격자가 열리며 긴 것이 쏟아져 내려와 허리를 감았다. 낚여 올라간다. 위에서 보니 복도의 점선이 한눈에 보였다. 점선 끝마다 이렇게 낚인 자들의 세간이 걸려 있었다.<br><br>떨어진 동냥을 넙죽 받던 손버릇. 여기서는 그 손부터 낚인다.`,
        dieText:`복도 바닥에 뼛조각이 점점이 떨어져 있다.<br><br>한가운데 제일 굵고 반듯한 조각이 하나 놓였다.<br>줍기 좋은 자리에, 줍기 좋은 각도로.` },
      ok:`집으려다 손을 멈췄다. 이 조각만 너무 반듯하게, 너무 줍기 좋게 놓였다.<br><br>평생 동냥 그릇에 담긴 것만 받았다. 길에 반듯하게 놓인 것은 받는 물건이 아니라 무는 물건이다.<br>조각을 두고 물러났다. 위에서 격자가 아주 조금 들렸다 내려앉는 소리가 났다. 허탕 친 낚시꾼의 소리다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S1', t:'흰 가운 — 굶은 척',
  x:`복도 구석에 흰 가운 하나가 웅크려 있다. 산 사람이다. 먹을 것을 달라고 한다. 사흘을 굶었다고.<br><br>
    마른 고기 한 점을 건넸다. 그가 받았다. 그리고 거지는 봤다.<br>
    사흘 굶은 손이 아니다. 굶은 손은 떨고, 받자마자 입으로 간다. 이 손은 안 떨고, 고기를 품에 넣는다.<br><br>
    거지 앞에서 굶은 척은 안 통한다. 굶기로는 평생 선수였다.`,
  o:[
    { l:'① 먹는 꼴을 끝까지 본다.', k:'luck', dc:25, wake:1,
      ok:`"드시오. 보는 데서." 한 점을 더 내밀며 말했다.<br><br>그가 머뭇대다 입에 넣었다. 씹는 꼴이 또 말해 줬다. 목으로 넘기질 못한다. 목 아래 딴것이 차 있는 것이다.<br>품에 넣은 고기는 제 것이 아니라 속엣것 몫이었다. 그는 울기 시작했고, 사실대로 다 말했다. 멀찍이 두고, 먹을 것을 나누고, 갈 수 있는 데까지 같이 갔다. 굶은 척을 가려내는 눈이 거짓 밑의 사정까지 읽었다.<br><br>굶주림의 결을 읽는 눈. 뺏으려는 자와 숨기려는 자와 살려는 자가 다 다르게 굶는다. 그 결이 다 보이기 시작했다.`,
      ng:`한 점을 더 내밀자 그가 받아서 또 품에 넣었다. 세 점째도.<br><br>"그만 주게." 뒤에서 일행이 말렸다. 그 순간 그의 품이 꿈틀했다. 받은 것을 품속에서 먼저 먹는 것이 있었다.<br>그가 비명처럼 웃으며 물러났다. 쫓아갈 수가 없었다. 품을 안은 채 어둠으로 사라지는 등을 보고만 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 부축해 일으킨다.', k:'bond', dc:25,
      doom:{ title:'품속의 입', what:'품에서 나온 것에게 감겨 끌려갑니다', dc:19, sec:40,
        text:`굶었다는 사람을 앉혀 두고 따질 게 아니다. 어깨를 끼고 부축해 일으켰다.<br><br>가슴과 가슴이 닿았다. 그의 품속 것이 더 따뜻한 쪽을 골랐다.<br>가운 안에서 그것이 옮겨 탔다. 목에 감긴다. 그가 울면서 떼어 내려 하지만 손이 늦다. 감긴 채 복도 안쪽으로 끌려간다. 그것은 제가 자랄 자리를 아는 것이다.<br><br>부축은 가슴을 내주는 자세다. 평생 부축받던 쪽이라, 내주는 쪽의 셈을 몰랐다.`,
        dieText:`복도 구석에 흰 가운이 혼자 앉아 있다.<br><br>이제 숨이 편해 보인다. 가슴이 고요하다.<br>곁에 마른 고기 세 점이 가지런히 놓여 있다. 손도 안 댄 채.` },
      ok:`부축하려다, 버릇대로 먼저 그의 가슴 쪽에 그릇을 내밀었다. 동냥 그릇부터 들이미는 평생 버릇.<br><br>그릇이 가슴에 닿자 가운 속에서 그것이 성을 냈다. 사기 그릇의 찬 기운이 싫은 것이다.<br>그가 제 가슴을 내려다보고, 이쪽을 보고, 고개를 저으며 물러났다. "가까이 오지 마시오." 제 입으로 말해 줬다. 그릇이 또 한 번 목숨을 벌었다.`,
      win:{ exp:24, dream:3 } },
    { l:'③ 몫만 놓아두고 물러난다.', k:'steady', dc:24,
      ok:`따지지도 부축하지도 않았다. 마른 고기 두 점과 물을 그 앞에 놓고 세 걸음 물러났다.<br><br>주는 것은 주는 것이고, 거리는 거리다. 길에서 배운 분별이다.<br>그가 그 자리에서 천천히, 아주 조금 먹었다. 먹을 수 있는 만큼이 그만큼인 것이다. 나머지는 품에 넣었다. 서로 아무것도 묻지 않았다. 그게 서로에게 자비였다.`,
      ng:`놓아두고 물러나는데 그가 기어 와 바짓단을 잡았다. 두고 가지 말라고.<br><br>떼어 내지도 끌고 가지도 못할 손이었다.<br>결국 해 질 녘까지 곁에 있어 줬다. 그가 잠들고서야 일어났다. 잠든 가슴이 두 박자로 뛰는 걸 못 본 척하는 게 제일 힘들었다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-23 } }
  ] },

{ at:'S1', t:'에어록 — 문간살이',
  x:`에어록 문이 닫히려 한다. 남은 동력이 마지막으로 도는 것이다. 이 문이 닫히면 돌아 나갈 길이 없다.<br><br>
    문틈에 뭘 괴어야 한다. 쇠붙이는 문힘에 으스러진다. 괴는 물건은 단단하면서 틈에 꼭 맞아야 한다.<br>
    품에서 그릇이 만져졌다. 이 빠진 사기 그릇. 평생을 같이 빌어먹은.<br><br>
    문간에서 살아온 세월이 말한다. 문은 한번 닫히면 끝이다.`,
  o:[
    { l:'① 그릇을 문틈에 괸다.', k:'luck', dc:25, wake:1,
      ok:`그릇을 모로 세워 문틈에 끼웠다. 문이 그릇을 물고 멈췄다. 사기가 우는 소리를 냈지만 버텼다.<br><br>일행이 다 지나고, 마지막으로 이쪽이 지나며 그릇을 봤다. 금이 세 줄 늘었다. 그래도 온전했다.<br>빼내려다, 뒀다. 다음에 갇히는 누군가의 문틈 몫으로. 평생 얻어먹은 그릇이 마지막엔 베푸는 그릇이 됐다.<br><br>쥔 것 중 제일 아까운 것을 내놓는 손. 그 손이 떨리지 않게 되기까지가 이 업의 공부였다.`,
      ng:`그릇을 끼우는 각이 틀렸다. 문힘이 그릇 빈 속을 눌렀다.<br><br>사기 깨지는 소리가 복도를 울렸다. 반 토막 난 그릇이 문틈에서 튕겨 나왔다.<br>문은 쇠지렛대 두 개를 먹고서야 멈췄다. 깨진 그릇 반쪽을 주워 품에 넣었다. 반쪽이어도 그릇은 그릇이다. 손이 한참 떨렸다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 내공으로 문을 받쳐 일행을 보낸다.', k:'steady', dc:25, cost:{ qi:34 },
      ok:`문짝에 등을 대고 내공을 뼈대에 둘렀다. 문힘이 등을 눌렀다. 겨울 밤바람을 버티던 그 등이다.<br><br>"지나가시오." 일행이 하나씩 빠져나갔다.<br>마지막에 몸을 굴려 빠지자 문이 쾅 닫혔다. 등짝에 문짝 무늬가 멍으로 찍혔다. 문간살이 한평생에 문을 이겨 본 건 처음이다.`,
      ng:`받치는 중에 내공이 출렁했다. 빈속이 밑천을 갉은 것이다.<br><br>문이 한 뼘 더 닫혔다. 마지막 사람이 몸을 긁히며 간신히 빠졌다.<br>이쪽도 어깨를 문틀에 쓸리며 굴러 나왔다. 닫힌 문 안쪽에서 뭔가 문을 두드리는 소리가 들렸다. 안 열리는 게 다행인 소리였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'산성 바닥 — 깡통 징검다리',
  x:`복도 바닥이 그것들 피에 삭아 구멍투성이다. 성한 데가 드문드문 섬처럼 남았다.<br><br>
    남들은 바닥만 본다. 거지는 버려진 것을 본다. 복도 가득 뒹구는 빈 깡통, 쟁반, 들통.<br>
    평생 쓰레기 더미에서 살림을 건졌다. 쓰레기가 많은 데서는 길도 건질 수 있다.<br><br>
    깡통은 바닥이 두껍다. 디딤 한 번은 버틴다.`,
  o:[
    { l:'① 깡통과 쟁반으로 징검다리를 놓는다.', k:'luck', dc:25,
      ok:`들통은 엎어 디딤돌, 쟁반은 약한 칸에 깔개, 깡통은 틈 메우기. 쓰레기의 쓰임을 한눈에 가르는 건 평생 한 일이다.<br><br>징검다리가 복도를 건넜다. 디딜 때마다 깡통이 조금씩 주저앉았지만 한 사람씩은 버텼다.<br>다 건너고 돌아보니 쓰레기 길이 당당했다. 버려진 것들로 낸 길. 버려져 본 사람이 제일 잘 놓는 길이다.`,
      ng:`들통 하나가 속까지 삭아 있었다. 디딘 발이 들통째 내려앉았다.<br><br>반사적으로 몸을 던져 옆 성한 칸을 짚었다. 들통은 구멍 아래로 떨어져 한참 만에 바닥을 쳤다.<br>그 소리에 아래층 어둠이 웅성였다. 남은 징검다리를 뛰다시피 건넜다. 쓰레기도 속까지 봐야 한다. 사람처럼.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 벽 쪽 배관 턱을 타고 돈다.', k:'evade', dc:24,
      ok:`벽에 붙은 배관 턱이 한 뼘 폭으로 이어진다. 처마 밑 담장을 타던 발이면 되는 폭이다.<br><br>발꿈치를 턱에 걸고 벽을 안듯이 게걸음으로 건넜다.<br>아래 구멍에서 찬 바람이 올라올 때마다 발가락에 힘이 들어갔다. 담장 타기 삼십 년의 발바닥이 오늘 밥값을 했다.`,
      ng:`배관 한 마디가 손 밑에서 바스러졌다. 삭은 가루가 아래 구멍으로 쏟아졌다.<br><br>매달린 채 발끝으로 다음 턱을 더듬었다.<br>구멍 아래서 가루 떨어지는 소리를 들은 무엇이 올려다보는 기척이 났다. 남은 턱을 반쯤 뛰어 건넜다. 손바닥이 녹가루에 쓸려 벌겠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S1', t:'깊은 방 어귀 — 나르는 줄',
  x:`아래로 내려가는 어귀에 줄이 섰다. 사람 줄이 아니다.<br><br>
    그것들이 줄지어 뭔가를 나른다. 수지 덩이, 먹을 것, 알 땔감 같은 것들. 다 안쪽으로, 깊은 데로.<br>
    바치러 가는 줄이다. 제일 깊은 데 앉은 것에게.<br><br>
    거지는 줄을 안다. 줄 서는 법도, 줄에 안 보이게 끼는 법도. 배급 줄에서 평생을 살았다.`,
  o:[
    { l:'① 아무것도 아닌 것의 자세로 줄 곁을 지난다.', k:'hide', dc:25, wake:1,
      ok:`허리를 굽히고, 눈을 내리깔고, 빈손을 보이며 줄 가장자리를 따라 걸었다. 배급 줄 곁을 지나는 법 그대로. 욕심 없는 걸음은 줄을 안 건드린다.<br><br>나르는 것들은 제 짐만 봤다. 줄은 원래 제 차례만 보는 법이다.<br>어귀를 다 지나도록 아무것도 고개를 돌리지 않았다. 평생 줄 곁에서 익힌 걸음이 괴물 줄 옆에서도 통했다.<br><br>줄의 법은 어디나 같다는 것. 그걸 아는 것이 거지의 학문이고, 오늘 학위가 나왔다.`,
      ng:`줄 곁을 지나는데 일행 하나가 짐을 고쳐 메다 쇠붙이 소리를 냈다.<br><br>줄이 일제히 멈췄다. 모든 짐이 바닥에 놓이고 모든 머리가 돌았다.<br>다들 그 자리에 엎드려 돌이 됐다. 한 식경 뒤 줄이 다시 움직였다. 줄은 참을성이 없다. 그게 살렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-23 } },
    { l:'② 수지 덩이를 주워 들고 줄에 낀다.', k:'luck', dc:26,
      doom:{ title:'성실한 일꾼', what:'줄의 것들에게 떠밀려 깊은 데로 끌려 내려갑니다', dc:20, sec:45,
        text:`떨어진 수지 덩이를 주워 안고 줄 꽁무니에 붙었다. 줄에 끼면 줄이 숨겨 준다. 배급 줄의 법이다.<br><br>법은 맞았다. 아무것도 이쪽을 수상해하지 않았다. 문제는 줄이 어디로 가는 줄이냐는 것이다.<br>빠지려는 길목마다 뒤의 것이 바짝 붙었다. 줄은 이탈을 모른다. 떠밀려 내려간다. 깊이, 더 깊이, 바치는 데까지. 안은 수지 덩이가 점점 따뜻해졌다. 아래가 가까운 것이다.<br><br>줄에 끼는 법만 알고 줄에서 빠지는 법을 몰랐다. 배급 줄은 끝이 밥이지만, 이 줄은 끝이 입이다.`,
        dieText:`깊은 데로 가는 줄이 오늘도 선다.<br><br>나르는 것들 틈에 유난히 작은 짐꾼이 하나 있었다고, 줄은 기억하지 않는다.<br>줄은 제 차례만 본다.` },
      ok:`수지 덩이를 안고 줄에 붙었다가, 세 걸음 만에 알았다. 이 줄은 돌아 나오는 줄이 없다.<br><br>가는 줄만 있고 오는 줄이 없는 길은 끝이 좋지 않다. 배급소에서도 그런 줄은 섰다가 큰일 난다.<br>모퉁이에서 덩이를 조용히 내려놓고 빠졌다. 뒤의 것이 그 덩이를 제 짐에 보태 지고 갔다. 줄은 아무 일 없다는 듯 흘렀다. 줄의 법을 아는 자만 줄에서 나온다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 줄이 끊기는 때를 기다린다.', k:'steady', dc:24,
      ok:`바위 뒤에 앉아 줄을 셌다. 배급 줄도 끼니때는 끊긴다. 이 줄도 어느 박자에 한 번씩 성겨졌다.<br><br>성긴 틈이 오자 어귀를 가로질렀다.<br>기다림은 거지의 본업이다. 평생 기다렸다. 반 시진쯤은 기다림 축에도 못 든다.`,
      ng:`줄이 좀처럼 안 끊겼다. 기다리는 사이 다리가 저리고 해가 기울었다.<br><br>어두워지자 줄이 되레 굵어졌다. 밤이 나르기 좋은 때인 것이다.<br>결국 자리를 물려 딴 길을 찾았다. 한나절을 허비했다. 기다림에도 끗발이 있는 날과 없는 날이 있다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S1', t:'냉동고 — 겨울 창고',
  x:`냉동고를 지나야 한다. 입김이 바로 어는 추위다.<br><br>
    일행이 문 앞에서 벌써 떤다. 거지만 덤덤하다. 이만한 추위의 겨울을 열몇 번 났다.<br>
    안에는 갈고리마다 고기가 얼어 걸렸다. 사람들 식량이었던 것.<br><br>
    추위는 거지의 옛 원수고, 옛 원수는 다루는 법을 안다.`,
  o:[
    { l:'① 내공을 돌려 일행의 몸을 데우며 건넌다.', k:'heal', dc:25, cost:{ qi:30 },
      ok:`내공을 데워 손바닥에 모으고, 일행의 등을 차례로 짚으며 걸었다. 겨울 처마 밑에서 제 몸 하나 데우던 화기를 넷으로 나눴다.<br><br>떨림이 멎은 다리들이 빨라졌다. 냉동고를 단숨에 건넜다.<br>나오며 갈고리에서 얼어 돌 같은 고깃덩이 하나를 내렸다. 겨울 창고의 인심이다. 녹여 먹으면 사나흘 끼니다.`,
      ng:`넷을 데우다 제 몸이 식었다. 화기가 모자란 것이다.<br><br>마지막 열 걸음에서 다리가 굳어 일행에게 업혔다. 업혀서 나온 거지라니, 평생 처음이다.<br>문밖에서 한참을 비벼서야 몸이 돌아왔다. 베푸는 데도 밑천 셈이 먼저라는 걸 얼어 가며 배웠다.`,
      win:{ exp:23, dream:3, item:'짐승 고기' }, lose:{ hp:-28, mind:-14 } },
    { l:'② 성에 낀 바닥의 발자국부터 읽는다.', k:'sense', dc:24,
      ok:`성에 바닥은 종이다. 다녀간 것이 다 적혀 있다. 사람 발자국 둘, 안쪽으로. 돌아 나온 자국 없음. 그리고 그 위를 덮은 크고 넓적한 자국.<br><br>안쪽 깊은 데는 들어가지 않기로 했다. 바깥쪽 갈고리의 고기만 한 덩이 내려 서둘러 건넜다.<br>성에에 적힌 글을 읽을 줄 알면 냉동고도 책이다. 결말까지 읽을 필요는 없는 책.`,
      ng:`읽는 사이 입김이 수염에 얼어붙었다. 추위는 책 읽을 시간을 안 준다.<br><br>안쪽에서 성에 밟히는 소리가 났다. 넓적한 자국의 임자가 깨어 있었다.<br>고기고 뭐고 문으로 내달렸다. 문을 닫자 안쪽에서 문에 성에 긁히는 소리가 길게 났다. 빈손이 시렸다. 추위 때문만은 아니었다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-17, spirit:-21 } }
  ] },

{ at:'S2', t:'울타리 — 개구멍',
  x:`울타리가 길을 막는다. 문은 저쪽들이 지켜본다.<br><br>
    거지는 담을 보면 구멍부터 찾는다. 세상 모든 담에는 개구멍이 있다. 일꾼들이 몰래 다니는 지름길.<br>
    울타리를 따라 반 바퀴. 덤불에 묻힌 데서 철망이 들려 있다. 사람 하나 길 만큼.<br><br>
    들린 모양새가 낯익다. 안쪽에서 바깥으로 들어 둔 것이다. 사육사들의 퇴근길이다.`,
  o:[
    { l:'① 개구멍의 임자 시간을 피해 쓴다.', k:'luck', dc:25, wake:1,
      ok:`구멍 둘레 흙을 봤다. 사람 자국은 옛것이고, 작은 짐승 자국이 새것이다. 잔것들도 이 구멍을 쓴다. 자국의 마른 결로 보아 저들 통행은 새벽.<br><br>지금은 한낮. 빈 시간이다. 하나씩 빠르게 통과시켰다.<br>마지막에 철망을 원래 모양으로 들어 두었다. 개구멍은 쓰고 나서 손봐 두는 것이 길의 예의다. 다음 손님이 사람이기를 빌면서.<br><br>담의 구멍마다 임자와 시간표가 있다는 것. 뒷골목의 학문이 백악기 울타리에서도 통했다.`,
      ng:`구멍을 반쯤 지났을 때 안쪽 수풀에서 바스락 소리가 났다. 잔것들이 낮에도 다니는 날이었다.<br><br>구멍 안에서 잔것들과 마주쳤다. 서로 놀라 서로 소리를 질렀다.<br>그 소란에 멀리서 큰 발소리가 방향을 틀었다. 나머지는 구멍을 구르듯 통과해 덤불로 흩어졌다. 시간표는 날마다 다시 읽어야 한다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 구멍을 넓혀 짐까지 통하게 한다.', k:'break', dc:24,
      ok:`철망 아랫단을 두 뼘 더 들어 돌로 괴었다. 짐과 사람이 같이 지날 폭.<br><br>조용히, 녹슨 철망이 비명을 안 지르게 천에 싸서 들었다.<br>다 지나고 괸 돌을 빼자 철망이 제자리로 내려앉았다. 흔적은 원래만큼만 남았다. 뒷문은 넓혀 써도 넓힌 티를 안 내는 것이다.`,
      ng:`철망을 드는데 녹슨 가시가 손바닥을 그었다. 피가 철망에 묻었다.<br><br>피 냄새는 울타리 안쪽으로 바람을 탔다.<br>서둘러 다 지나고 손을 흙으로 문질렀다. 그날 밤 그 구멍 쪽에서 킁킁대는 소리가 오래 났다. 개구멍에 피 묻힌 값이다. 당분간 그 구멍은 못 쓴다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S2', t:'물 양치밭 — 바닥 걷기',
  x:`물에 잠긴 양치밭. 헤엄은 서툴다. 거지 평생 헤엄칠 물가에 산 적이 없다.<br><br>
    대신 숨을 오래 참는 법은 안다. 매 맞을 때, 추울 때, 숨어 있을 때. 숨을 접고 견디는 법.<br>
    내공을 실으면 그 숨이 곱절은 간다.<br><br>
    물 위가 아니라 물 밑으로. 바닥을 밟고 걸어서 건너는 것이다.`,
  o:[
    { l:'① 내공으로 숨을 잠그고 바닥을 걷는다.', k:'steady', dc:26, cost:{ qi:36 },
      ok:`돌을 하나 안아 무게를 만들고, 숨을 아랫배에 잠그고 물로 들어갔다.<br><br>바닥은 생각보다 밝았다. 양치 줄기 사이로 빛이 내렸다. 천천히, 바닥 흙을 안 일으키며 걸었다.<br>중간에 긴 것이 머리 위로 지나갔다. 물 위를 훑는 놈이었다. 바닥 걷는 것은 셈에 없는 모양이다. 건너편 물가로 머리를 내밀자 일행이 유령 본 낯을 했다. 숨 참기 평생 공부의 졸업 시험이었다.`,
      ng:`반쯤 건넜을 때 발이 바닥 수렁에 빠졌다. 허우적대자 흙탕이 일었다.<br><br>흙탕은 물속의 연기다. 뭔가 그 연기를 보러 왔다.<br>돌을 버리고 양치 줄기를 당겨 몸을 뽑았다. 마지막은 숨이 모자라 반쯤 기다시피 물가로 나왔다. 토한 물에 흙이 반이었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 물 위를 헤엄쳐 지른다.', k:'evade', dc:26,
      doom:{ title:'물낯의 그림자', what:'물밑의 것에게 다리를 물려 끌려 가라앉습니다', dc:20, sec:40,
        text:`서툰 헤엄이지만 거리가 짧다. 개헤엄으로 물낯을 저었다.<br><br>반쯤에서 알았다. 물낯을 젓는 소리가 물밑에는 종소리라는 걸. 첨벙. 첨벙. 밥 종.<br>다리가 물렸다. 숨 쉴 새도 없이 뒤집혀 가라앉는다. 양치 줄기 사이로, 초록 빛이 깜깜해지는 데까지. 마지막 생각이 우스웠다. 평생 종 치는 소리에 얻어먹었는데, 마지막엔 제가 종을 쳤구나.<br><br>물에서는 조용한 것이 산다. 뭍의 법과 같다. 요란한 것이 먼저 불린다.`,
        dieText:`양치밭 물낯이 고요하다.<br><br>개헤엄 물결이 반쯤 가다 끊긴 자리, 거품 몇 알.<br>이 빠진 사기 그릇 하나가 물가에 남아 주인을 기다린다.` },
      ok:`헤엄치다 물밑에서 올라오는 물살을 종아리에 느꼈다. 뭔가 밑에서 따라붙는 물살.<br><br>첨벙임을 뚝 끊고 통나무처럼 떴다. 흐르는 척, 죽은 척.<br>밑의 것이 흥미를 잃고 지나갔다. 그다음부터는 소리 없는 개구리헤엄으로, 숨풍 한 번 안 내고 건넜다. 물에서도 하찮아 보이는 법이 통했다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'사냥 끝 — 얻어먹는 순서',
  x:`무리가 사냥을 끝냈다. 먹고, 트림하고, 그늘로 물러갔다. 남은 것이 벌판에 있다.<br><br>
    일행이 바로 가자고 한다. 거지가 막는다.<br>
    남의 상에는 얻어먹는 순서가 있다. 주인이 뜨고, 날것들이 오고, 잔것들이 오고, 그다음이 사람이다.<br><br>
    순서를 어기면 상이 아니라 밥이 된다.`,
  o:[
    { l:'① 잔것들이 뜰 때까지 기다렸다 거둔다.', k:'luck', dc:25, wake:1,
      ok:`그늘의 주인들이 코를 골고, 날개 달린 것들이 내려앉았다 뜨고, 잔것들이 바스락대다 흩어졌다.<br><br>그제야 갔다. 뼈에 붙은 것과 질긴 부위. 남들이 못 먹는 데가 거지 몫이다. 평생 그랬다.<br>저미는 동안 그늘 쪽에서 한쪽 눈이 떠서 이쪽을 봤다. 순서 지켜 온 손님인 걸 확인하고 도로 감겼다. 상의 법도는 여기도 있었다.<br><br>얻어먹는 순서의 학문. 뒷골목 잔칫집에서 백악기 벌판까지, 어디서나 통하는 유일한 학문일 것이다.`,
      ng:`잔것들이 뜨기 전에 일행 하나가 참지 못하고 나섰다.<br><br>잔것들이 놀라 한꺼번에 울며 흩어졌다. 소란은 그늘의 주인들 낮잠을 건드렸다.<br>다들 수풀에 엎드려 한 식경을 보냈다. 상은 날것들이 그 사이 다 쓸어 갔다. 순서를 어기면 차례가 아예 안 온다. 산 채로 배운 게 그나마 남는 장사다.`,
      win:{ exp:24, dream:3, item:'짐승 고기' }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 잔것들 몫을 먼저 던져 주고 같이 먹는다.', k:'bond', dc:24,
      ok:`기다리는 대신 끼었다. 마른 빵 부스러기를 잔것들 쪽에 뿌려 주고, 사람 몫 자리로 갔다.<br><br>잔것들은 제 몫이 생기자 사람을 안 경계했다. 같은 상의 손님이 된 것이다.<br>잔것들 사이에 끼어 먹을 것을 거두는 사람들. 멀리서 보면 우스운 그림이었겠지만, 잔것들이 곤두서면 같이 뛰면 된다는 보험까지 든 셈이었다.`,
      ng:`뿌린 부스러기가 모자랐다. 잔것들이 사람 몫까지 넘봤다.<br><br>손등을 할퀴는 놈까지 나왔다.<br>거둔 것 반을 잔것들에게 뜯기고 물러났다. 상 나눠 먹자고 낀 손님이 제일 많이 먹는 법은 없다. 알면서도 당했다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'급이대 — 사료 고수레',
  x:`급이대 밑 통에 묵은 사료가 반쯤 남았다. 돌처럼 굳은 덩어리들.<br><br>
    사람은 못 먹는다. 냄새를 맡아 보니 잔것들은 먹겠다.<br>
    거지 눈에 이건 식량이 아니라 밑천이다. 뿌릴 수 있는 것은 다 밑천이다.<br><br>
    앞길에 잔것들 많은 덤불 지대가 있다. 통행세로 쓰면 된다.`,
  o:[
    { l:'① 사료를 앞서 뿌리며 덤불 지대를 산다.', k:'luck', dc:24,
      ok:`덤불 지대 초입에서 사료 덩이를 멀찍이 던졌다. 잔것들이 우르르 그쪽으로 몰렸다.<br><br>길이 비었다. 반쯤 가서 또 한 줌, 끝에서 또 한 줌.<br>사료 반 통으로 덤불 지대를 무사 통과했다. 고수레가 통행세가 되고 통행세가 보험이 됐다. 뿌리는 법을 아는 손은 어디서나 길을 산다.`,
      ng:`던진 사료에 잔것들이 몰린 건 좋았는데, 몰린 잔것들을 노리는 것이 따라왔다.<br><br>덤불 지대 복판이 사냥터가 됐다.<br>쫓고 쫓기는 소란 한가운데를 머리 숙이고 내달렸다. 통행세를 냈더니 길에서 싸움이 났다. 세상일이 다 그렇다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 사료 통 바닥까지 뒤져 본다.', k:'sense', dc:23,
      ok:`통 바닥에 사육사들의 물건이 가라앉아 있었다. 사료 푸던 바가지, 가죽 장갑, 그리고 기름종이에 싼 소금 덩이.<br><br>가축 핥으라고 두는 소금이다. 사람 먹어도 소금은 소금이다.<br>바가지도 챙겼다. 거지 살림에 바가지가 빠지면 섭섭하다. 통 바닥은 어디서나 보물자리다. 바닥을 치고 살아 봐서 안다.`,
      ng:`통 바닥을 휘젓는데 굳은 사료 더미 속에서 뭔가 꿈틀했다. 사료에 깃들어 사는 벌레 뭉치.<br><br>놀라 손을 빼다 통을 넘어뜨렸다. 와르르.<br>소리에 급이대 그늘에 자던 것이 깼다. 바가지 하나만 건지고 뛰었다. 바닥 욕심이 과했다.`,
      win:{ exp:17, dream:2, item:'소금 덩이' }, lose:{ mind:-16, spirit:-19 } }
  ] },

{ at:'S2', t:'큰 것의 뒤 — 줍는 길',
  x:`땅이 울린다. 큰 것이 지나가는 중이다. 다들 엎드려 떤다.<br><br>
    거지만 고개를 들고 있다. 큰 것이 지나가면, 모든 것이 숨는다. 사냥하는 것들까지.<br>
    즉 큰 것의 등 뒤가 이 정원에서 제일 빈 길이다.<br><br>
    잔칫집 행렬 뒤를 따라 걸으며 떨어진 것을 줍던, 꼭 그 셈이다.`,
  o:[
    { l:'① 큰 것의 자취를 따라 걷는다.', k:'luck', dc:25, wake:1,
      ok:`울림이 멀어지는 쪽으로, 스무 걸음 뒤를 따랐다. 부러진 가지와 뒤집힌 흙의 길. 양옆 수풀은 쥐 죽은 듯했다.<br><br>길에는 떨어진 것이 많았다. 그 큰 입이 훑다 흘린 열매, 뒤집힌 흙에 드러난 덩이뿌리, 놀라 뛰다 버려진 잔것들의 사냥감.<br>한나절을 그 뒤를 따라 안전하게, 주우며 갔다. 제일 무서운 것의 등 뒤가 제일 넉넉한 길이었다. 행렬 꽁무니의 학문이다.<br><br>무서움의 그늘을 길로 쓰는 법. 거지는 평생 남의 그늘에서 살았고, 여기서는 그게 생존술의 맨 윗줄이다.`,
      ng:`스무 걸음이 모자랐다. 큰 것이 갑자기 멈춰 돌아봤다. 뭔가 마음에 안 드는 소리를 들은 것이다.<br><br>엎드린 머리 위로 그 눈이 지나갔다. 집채만 한 머리가 스무 걸음 앞에서 수풀을 훑었다.<br>다시 걷기 시작할 때까지 흙에 코를 박고 있었다. 행렬 꽁무니도 거리 계산은 목숨 계산이다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 울림이 지난 자리의 물웅덩이를 턴다.', k:'sense', dc:24,
      ok:`큰 발자국마다 물이 고이고, 고인 물에 놀란 물고기들이 갇힌다. 지나간 자리의 웅덩이들을 돌았다.<br><br>세 번째 발자국 웅덩이에서 손바닥만 한 민물고기가 두 마리 퍼덕였다.<br>맨손으로 건졌다. 큰 것이 걸어가며 차려 준 밥상이다. 세상에서 제일 큰 상차림꾼이다.`,
      ng:`웅덩이를 터는 데 정신이 팔려 울림이 돌아오는 걸 늦게 느꼈다.<br><br>큰 것이 같은 길로 되짚어 오고 있었다.<br>웅덩이에서 튀어나와 수풀로 굴렀다. 큰 발이 방금 그 웅덩이를 다시 밟아 뭉갰다. 고기는 한 마리만 건졌다. 손이 떨려 한 마리는 놓쳤는지 놓아줬는지 모르겠다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'S2', t:'관리인 오두막 — 빈집 예절',
  x:`관리인 오두막이 비어 있다. 문이 반쯤 열린 채.<br><br>
    거지는 빈집에 드는 법을 안다. 문간에서 기척을 내고, 한 박자 기다리고, 조심히 들고, 적게 가져가고, 들어온 모양 그대로 두고 나온다.<br>
    남의 빈집에서 평생을 잤다. 예절이 밥이고 목숨이었다.<br><br>
    문간에서 기척을 냈다. 대답 대신, 마루 밑에서 숨소리가 났다.`,
  o:[
    { l:'① 마루 위만 밟고 조용히 볼일을 본다.', k:'luck', dc:25,
      ok:`마루 밑 임자는 임자고, 마루 위 세간은 세간이다. 빈집 예절대로 했다. 발소리 죽이고, 삐걱대는 널은 피하고.<br><br>선반의 기름 한 병과 벽의 밧줄만 거뒀다. 적게, 꼭 쓸 것만.<br>나올 때 문을 들어온 각도 그대로 뒀다. 마루 밑 숨소리는 끝까지 고르게 잤다. 셋방살이 손님끼리는 서로 안 깨우는 법이다.`,
      ng:`조심했는데 삐걱대는 널이 하나 더 있었다. 새로 삭은 널.<br><br>끼익. 마루 밑 숨소리가 멎었다.<br>세간이고 뭐고 다들 창으로 구르듯 나왔다. 마루 밑에서 뭔가 마루청을 코로 미는 소리가 뒤따랐다. 빈집 예절 제일 조는 역시 「빨리 뜬다」다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-21 } },
    { l:'② 마루 밑을 들여다본다.', k:'gaze', dc:26,
      doom:{ title:'마루 밑 임자', what:'마루 밑으로 끌려 들어갑니다', dc:20, sec:40,
        text:`뭐가 사는지는 알아야 잠자리를 정한다. 엎드려 마루 밑 어둠에 눈을 댔다.<br><br>어둠 속에서 눈 하나가 마주 떠졌다. 가까웠다. 생각한 것보다 훨씬.<br>마루 밑에 웅크려 살 크기가 아니었다. 접혀 있던 것이다. 긴 것이 풀리며 팔을 감았다. 마루 널 틈으로 끌려 들어간다. 널이 등 뒤에서 도로 내려앉는다. 빈집의 마루 밑은 들여다보는 데가 아니다. 평생 지킨 예절을 여기서 깼다.<br><br>남의 집 아랫목은 캐는 게 아니다. 빈집 예절 제일 조를 어긴 값이다.`,
        dieText:`관리인 오두막 문이 반쯤 열린 채다.<br><br>마루 한가운데 널 하나가 들썩, 하고 가라앉았다.<br>마루 밑 숨소리가 다시 고르게 길어진다. 배부른 숨이다.` },
      ok:`엎드리려다 멈췄다. 마루 틈으로 올라오는 숨의 더운 김이 뺨에 닿았다. 틈 바로 밑까지 차 있는 숨이다.<br><br>마루 밑에 꽉 차게 사는 것이면, 들여다보는 눈과 한 뼘 거리다.<br>그대로 일어나 발꿈치로 물러났다. 볼일은 마당에서 끝냈다. 궁금함과 목숨을 저울에 달면 언제나 목숨이 무겁다. 거지 저울은 그게 잘 든다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S2', t:'낡은 승강기 — 마지막 밀기',
  x:`낡은 승강기 크랭크가 무겁다. 녹이 반, 세월이 반. 장정 둘이 돌려도 반 바퀴에 멎는다.<br><br>
    돌 때마다 끼익끼익 우는 소리가 정원 전체에 광고를 한다.<br>
    빨리, 단숨에 돌려야 한다. 거지가 소매를 걷었다.<br>
    평생 받기만 한 팔이다. 들 것이라곤 그릇 하나뿐이던 팔.<br><br>
    오늘은 이 팔로 일행을 들어 올린다.`,
  o:[
    { l:'① 내공을 쥐어짜 단숨에 감아올린다.', k:'break', dc:26, wake:1, cost:{ qi:38 },
      ok:`아랫배의 내공을 바닥까지 긁어 두 팔에 실었다. 크랭크가 울 틈도 없이 돌았다.<br><br>승강기가 단숨에 올라붙었다. 긴 비명 대신 짧은 기합 한 번.<br>일행이 다 오르고 크랭크를 고정쇠에 걸었다. 팔이 후들거려 한참 못 폈다. 평생 내밀기만 하던 손으로 사람들을 올려 보냈다.<br><br>받는 손이 미는 손이 되는 데 평생이 걸렸다. 내공은 거들었을 뿐이다. 민 것은 세월이다.`,
      ng:`내공을 싣다 빈속이 또 발목을 잡았다. 반 바퀴에서 힘이 출렁했다.<br><br>크랭크가 길게 울었다. 끼이이익. 정원이 다 들었을 소리.<br>남은 반 바퀴는 다 같이 매달려 돌렸다. 승강기가 오르는 동안 아래 수풀에서 기척들이 모여드는 게 보였다. 턱걸이로 떴다. 다음부터는 끼니부터 챙기고 힘쓰기로 했다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 크랭크에 기름부터 먹인다.', k:'fix', dc:24,
      ok:`오두막에서 거둔 기름을 크랭크 축에 천천히 먹였다. 녹이 기름을 마시는 시간을 기다렸다.<br><br>반 시진 뒤 크랭크가 반값의 힘으로, 반값의 소리로 돌았다.<br>급할수록 기름칠이다. 뒷골목 수레꾼들에게 평생 들은 말인데, 백악기에서 써먹을 줄은 몰랐다.`,
      ng:`기름이 스미기 전에 멀리서 울림이 왔다. 큰 것이 이쪽 방향이다.<br><br>덜 먹은 크랭크를 그냥 돌렸다. 우는 소리 반, 기름 소리 반.<br>승강기가 오르는 것과 울림이 닿는 것이 비슷했다. 올라서 내려다보니 큰 머리가 승강기 통로 밑을 한 바퀴 돌고 있었다. 기름 반 병 차이였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-20 } }
  ] }

]);
